INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B01_17', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B01'), 'LS6_KNTT_B01', 'Ý nghĩa phù hợp của lời nhắc “Dân ta phải biết sử ta” đối với việc học lịch sử', 'biết cội nguồn, truyền thống và trân trọng giá trị được trao truyền', 'chỉ cần biết chuyện nổi tiếng, không cần hiểu ý nghĩa của chúng', 'học lịch sử chủ yếu để ghi nhớ tên nhân vật và niên đại càng nhiều càng tốt', 'chỉ những người làm công việc nghiên cứu mới cần tìm hiểu lịch sử dân tộc', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: hiểu lịch sử dân tộc để biết cội nguồn, truyền thống và trân trọng những giá trị được trao truyền') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B01_18', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B01'), 'LS6_KNTT_B01', 'Mối quan hệ giữa quá khứ, hiện tại và tương lai thể hiện rõ qua việc học lịch sử ở điểm', 'hiện tại hoàn toàn tách biệt với quá khứ nên không thể rút ra kinh nghiệm', 'hiểu quá khứ, rút kinh nghiệm cho hiện tại và hướng tới tương lai', 'tương lai luôn lặp lại nguyên vẹn quá khứ nên chỉ cần sao chép cách làm cũ', 'quá khứ chỉ để lưu niệm, không giúp ích cho các quyết định hiện nay', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: hiểu quá khứ và rút kinh nghiệm để phục vụ cuộc sống hiện tại, hướng tới tương lai') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B01_19', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B01'), 'LS6_KNTT_B01', 'Nhận xét phù hợp về ý kiến “Học lịch sử chỉ là học thuộc tên người và ngày tháng”', 'đúng vì môn Lịch sử không cần tìm hiểu nguyên nhân hay ý nghĩa', 'đúng vì nội dung lịch sử chỉ gồm danh sách các niên đại', 'chưa đầy đủ vì Lịch sử còn tìm hiểu quá trình phát triển và ý nghĩa', 'chưa đầy đủ vì Lịch sử chủ yếu nghiên cứu hiện tượng tự nhiên', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: ý kiến chưa đầy đủ vì môn Lịch sử còn tìm hiểu quá trình phát triển của xã hội và ý nghĩa của quá khứ') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B01_20', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B01'), 'LS6_KNTT_B01', 'Một sự việc từng xảy ra trong gia đình hoặc địa phương có thể trở thành đối tượng tìm hiểu lịch sử vì', 'chỉ các sự kiện cấp quốc gia mới thuộc về quá khứ và có thể nghiên cứu', 'những việc gần gũi luôn quan trọng hơn mọi sự kiện của dân tộc và nhân loại', 'chỉ những sự việc có văn bản chính thức mới được xem là đã từng xảy ra', 'lịch sử gồm những gì xảy ra trong quá khứ, từ gần gũi đến rộng lớn', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: lịch sử gồm những gì đã xảy ra trong quá khứ, từ phạm vi gần gũi đến rộng lớn hơn') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B01_21', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B01'), 'LS6_KNTT_B01', 'Gia đình em có ảnh cũ, gia phả và nhiều câu chuyện của ông bà. Cách làm phù hợp để tìm hiểu cội nguồn gia đình', 'thu thập, đối chiếu thông tin và hỏi người thân để ghi lại sự việc', 'chọn một câu chuyện thú vị nhất rồi coi đó là toàn bộ lịch sử của gia đình', 'bỏ qua vì chỉ sự kiện cấp quốc gia mới có giá trị lịch sử', 'tự bổ sung những chi tiết còn thiếu để câu chuyện về gia đình hấp dẫn hơn', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: sưu tầm, đối chiếu các thông tin và hỏi thêm người thân để ghi lại những sự việc đáng tin cậy') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B01_22', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B01'), 'LS6_KNTT_B01', 'Từ ENIAC (1946), máy tính thế hệ 4 (1971-1980) và laptop hiện nay, kết luận nào phù hợp?', 'Máy tính hiện nay không có mối liên hệ với quá trình phát triển trước đó', 'Sự vật biến đổi theo thời gian; quá trình đó giúp hình dung về lịch sử', 'Chỉ phát minh khoa học mới có lịch sử, con người và xã hội thì không', 'Mọi giai đoạn của máy tính đều giống nhau về hình dạng và tính năng', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Sự vật có quá trình hình thành và biến đổi theo thời gian; quá trình ấy giúp hình dung về lịch sử') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B01_23', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B01'), 'LS6_KNTT_B01', 'Khi gặp một vấn đề hiện nay có nét tương tự với một thất bại trong quá khứ, cách vận dụng bài học lịch sử phù hợp là', 'Lặp lại cách giải quyết cũ vì hoàn cảnh mọi thời kì đều giống nhau', 'bỏ qua kinh nghiệm quá khứ vì các sự việc đã kết thúc và không còn giá trị', 'Xem xét nguyên nhân, kết quả trước đây để rút kinh nghiệm cho hiện tại', 'Chỉ ghi nhớ tên sự kiện cũ mà không xem xét lí do thành bại', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: xem xét hoàn cảnh, nguyên nhân và kết quả trước đây để rút kinh nghiệm phù hợp với hiện tại') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B01_24', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B01'), 'LS6_KNTT_B01', 'Một bạn cho rằng chỉ người thích môn Lịch sử mới cần học lịch sử. Cách phản hồi nào sau đây là phù hợp?', 'Đúng vì lịch sử chỉ hữu ích cho người làm bảo tàng hoặc nghiên cứu', 'Đúng vì học môn khác không cần biết cội nguồn gia đình, dân tộc', 'Chưa đúng vì học lịch sử để dự đoán chính xác mọi việc tương lai', 'Chưa đúng vì hiểu cội nguồn và rút kinh nghiệm có ý nghĩa với mỗi người', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Chưa đúng vì hiểu cội nguồn và rút kinh nghiệm từ quá khứ có ý nghĩa với mỗi người trong cuộc sống.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
