INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B02_20', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B02'), 'LS6_KNTT_B02', 'Nguyên tắc phù hợp nhất khi phục dựng một sự kiện lịch sử', 'chỉ chọn nguồn phù hợp với ý kiến có sẵn và bỏ qua các nguồn khác', 'ưu tiên truyền miệng vì loại nguồn này luôn phản ánh đủ mọi khía cạnh', 'đối chiếu nhiều nguồn, chú ý giá trị và hạn chế của từng loại', 'chỉ dùng tư liệu thứ cấp vì đã được tổng hợp, không cần kiểm chứng', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: kết hợp, đối chiếu nhiều nguồn và chú ý giá trị cũng như hạn chế của từng loại') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B02_21', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B02'), 'LS6_KNTT_B02', 'Gia đình còn giữ một chiếc sắc phong cổ có phần giấy, dấu và nội dung chữ. Cách khai thác phù hợp nhất', 'xem xét chất liệu, hình thức, chữ viết và đối chiếu nguồn khác', 'chỉ đọc chữ vì chất liệu, hình thức hiện vật không có giá trị', 'chỉ xem chất liệu vì nội dung chữ luôn chủ quan, không đáng tin', 'coi là tư liệu truyền miệng vì được lưu truyền qua nhiều thế hệ', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: xem xét chất liệu, hình thức và nội dung chữ, đồng thời đối chiếu với nguồn khác') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B02_22', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B02'), 'LS6_KNTT_B02', 'Một học sinh nghe kể truyền thuyết về địa phương rồi muốn xác định sự kiện có thật. Việc nên làm trước hết', 'khẳng định mọi chi tiết trong truyền thuyết đều đúng vì được kể từ lâu đời', 'đối chiếu lời kể với di tích, hiện vật và các nguồn liên quan', 'loại bỏ truyền thuyết vì cho rằng nguồn này không có giá trị lịch sử', 'chỉ hỏi thêm người kể khác mà không tìm nguồn sử liệu nào khác', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: đối chiếu lời kể với di tích, hiện vật, văn bản và những nguồn liên quan khác') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
