INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_18', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Tục chôn người chết và thờ thần linh ở công xã thị tộc cho thấy', 'con người đã sáng tạo ra hệ thống chữ viết để truyền lại tín ngưỡng', 'đời sống tinh thần phong phú hơn và xuất hiện những quan niệm tín ngưỡng', 'xã hội đã phân hóa sâu sắc và hình thành những giai cấp đối kháng', 'mọi cộng đồng đều theo một tôn giáo thống nhất có tổ chức chặt chẽ', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: đời sống tinh thần phong phú hơn và xuất hiện những quan niệm tín ngưỡng') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_19', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Tìm thấy đá mài, gốm, xương thú, hạt cây ở Hòa Bình, Bắc Sơn cho thấy', 'cư dân chỉ sống bằng săn bắt thú rừng và chưa biết chế biến thức ăn', 'cư dân dùng phổ biến kim loại và sản xuất thủ công quy mô lớn', 'cư dân kết hợp nhiều hoạt động kiếm sống và bước đầu biết làm nông nghiệp', 'cư dân đã xây dựng các đô thị và tổ chức xã hội thành những nhà nước cổ đại', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: cư dân kết hợp nhiều hoạt động kiếm sống và bước đầu biết làm nông nghiệp') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_20', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Ý nghĩa khái quát của lao động đối với quá trình phát triển xã hội nguyên thủy', 'chỉ đổi hình dáng công cụ, không ảnh hưởng con người và cộng đồng', 'chỉ tăng thức ăn nhưng không đổi cách thức tổ chức xã hội', 'chủ yếu tạo của cải riêng, thúc đẩy cá nhân rời cộng đồng', 'hoàn thiện con người, gắn kết cộng đồng, đổi mới công cụ, nâng đời sống', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: góp phần hoàn thiện con người, gắn kết cộng đồng, đổi mới công cụ và nâng cao đời sống') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_21', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Một di chỉ mới phát hiện có rìu đá mài, đồ gốm, xương gia súc và nhiều hạt cây ăn được. Nhận định phù hợp nhất', 'cư dân tiến bộ hơn, bước đầu phát triển trồng trọt và chăn nuôi', 'cư dân vẫn chỉ dựa vào hái lượm, chưa có hoạt động sản xuất thức ăn', 'cư dân đã bước vào thời đại kim loại và hình thành nhà nước có giai cấp', 'cư dân chủ yếu sống bằng thương mại và trao đổi sản phẩm giữa các đô thị', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: cư dân đã ở giai đoạn tiến bộ hơn, bước đầu phát triển trồng trọt và chăn nuôi') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_22', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Chuỗi biến đổi từ công cụ đá ghè đẽo đến đá mài, đồ gốm rồi trồng trọt, chăn nuôi cho phép rút ra kết luận', 'công cụ thay đổi nhưng đời sống, xã hội hầu như không chuyển biến', 'tiến bộ công cụ và sản xuất gắn với quá trình phát triển xã hội', 'nông nghiệp xuất hiện trước khi con người cải tiến công cụ lao động', 'đời sống tinh thần quyết định hoàn toàn sự thay đổi kĩ thuật, sản xuất', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: tiến bộ của công cụ và phương thức sản xuất gắn với quá trình phát triển của xã hội') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B05_23', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B05'), 'LS6_KNTT_B05', 'Chế tác công cụ đá cần lặp lại thao tác và phối hợp. Liên hệ đúng về vai trò lao động:', 'chỉ tăng sản phẩm nhưng không ảnh hưởng đến kĩ năng con người', 'làm cá nhân ngày càng tách biệt, không giúp hình thành cộng đồng', 'vừa rèn luyện kĩ năng, vừa thúc đẩy hợp tác và sáng tạo cộng đồng', 'chỉ có ý nghĩa khi đã biết dùng kim loại và có tổ chức nhà nước', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: lao động vừa rèn luyện kĩ năng cơ thể vừa thúc đẩy hợp tác, sáng tạo trong cộng đồng') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
