INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B19_19', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B19'), 'LS6_KNTT_B19', 'Việc cư dân Chăm-pa cải biến chữ viết của Ấn Độ để tạo chữ Chăm cổ thể hiện', 'cư dân Chăm-pa từ chối mọi ảnh hưởng chữ viết từ các nền văn hóa bên ngoài', 'chữ Chăm cổ hình thành độc lập, không liên hệ với giao lưu văn hóa', 'tiếp thu ảnh hưởng bên ngoài gắn với sáng tạo chữ viết riêng', 'Chăm-pa chỉ dùng chữ Phạn, không xây dựng hệ thống chữ viết riêng', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: sự tiếp nhận ảnh hưởng bên ngoài gắn với sáng tạo chữ viết riêng của cộng đồng') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B19_20', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B19'), 'LS6_KNTT_B19', 'Sự tồn tại của tín ngưỡng bản địa bên cạnh Phật giáo, Bà La Môn giáo và kiến trúc Mỹ Sơn cho thấy', 'văn hóa Chăm-pa đa dạng, vừa có giao lưu bên ngoài vừa mang bản sắc riêng', 'tôn giáo du nhập đã thay thế hoàn toàn tín ngưỡng bản địa', 'đời sống tinh thần Chăm-pa chỉ ở cung đình, không gắn với cộng đồng', 'kiến trúc Chăm-pa tách biệt với tôn giáo, không chịu ảnh hưởng khu vực', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: văn hóa Chăm-pa đa dạng, vừa có giao lưu bên ngoài vừa mang bản sắc riêng') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B19_21', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B19'), 'LS6_KNTT_B19', 'Cảng Chăm-pa nhập hàng ngoại, xuất trầm hương, kì nam, ngọc trai cho thấy:', 'thương mại biển chỉ là phụ, chủ yếu trao đổi giữa các làng gần nhau', 'hàng ngoại nhập xuất hiện do Chăm-pa không có sản vật bản địa', 'Chăm-pa là đầu mối giao thương biển, kết nối sản vật với nhiều nơi', 'thương cảng chỉ nhận hàng từ một nước, không tham gia mạng lưới rộng', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Chăm-pa là một đầu mối giao thương biển kết nối sản vật địa phương với nhiều khu vực') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B19_22', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B19'), 'LS6_KNTT_B19', 'Khi trình bày tiến trình Chăm-pa từ trước thế kỉ VIII đến thế kỉ IX, cách sử dụng dữ kiện về kinh đô phù hợp', 'thể hiện trung tâm quyền lực thay đổi theo giai đoạn, không cố định', 'chỉ ghi một kinh đô vì việc đổi địa điểm không liên quan phát triển', 'xếp Sin-ha-pu-ra, Vi-ra-pu-ra, In-đra-pu-ra cùng lúc để so sánh', 'bỏ các mốc thời gian vì tên kinh đô không phản ánh sự phát triển', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: thể hiện các trung tâm quyền lực thay đổi theo từng giai đoạn thay vì coi kinh đô luôn cố định') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS6_B19_23', (SELECT id FROM lesson_metadata WHERE code = 'LS6_KNTT_B19'), 'LS6_KNTT_B19', 'Khi tham quan Thành địa Mỹ Sơn, hành động phù hợp để góp phần bảo tồn và phát huy giá trị di sản', 'chạm vào điêu khắc để kiểm tra vật liệu và ghi lại cảm nhận', 'tự lấy một mảnh gạch nhỏ làm kỉ niệm để lưu giữ dấu tích lịch sử lâu dài', 'viết tên lên bề mặt công trình để đánh dấu chuyến tham quan', 'tuân thủ quy định, không xâm hại di tích, giới thiệu qua nguồn tin cậy', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: tuân thủ quy định, không xâm hại di tích, tìm hiểu và giới thiệu giá trị bằng nguồn tin cậy') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
