INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS7_B11_22', (SELECT id FROM lesson_metadata WHERE code = 'LS7_KNTT_B11'), 'LS7_KNTT_B11', 'Kết hợp các mốc 1009, 1010 và 1054, nhận xét có cơ sở về quá trình xây dựng đất nước thời Lý', 'chỉ đổi tên kinh đô, chưa có bước củng cố nào về nhà nước, quốc gia', 'từng bước lập vương triều, định đô mới và củng cố vị thế Đại Việt', 'cho thấy nhà Lý muốn quay lại mô hình lệ thuộc chính trị phương Bắc', 'nhà Lý liên tục đổi kinh đô vì chưa tìm được trung tâm ổn định', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: nhà Lý từng bước xác lập vương triều, xây dựng trung tâm chính trị mới và củng cố ý thức quốc gia Đại Việt') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
