INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS7_B13_13', (SELECT id FROM lesson_metadata WHERE code = 'LS7_KNTT_B13'), 'LS7_KNTT_B13', 'Sự thành lập nhà Trần đầu thế kỉ XIII phù hợp với hoàn cảnh lịch sử chủ yếu vì', 'nhà Lý suy yếu, xã hội rối ren nên cần chính quyền đủ sức ổn định đất nước', 'nhà Lý đang thịnh trị nên chủ động giao quyền lực để mở rộng lãnh thổ', 'họ Trần chỉ mạnh về thương mại, chưa có ảnh hưởng đáng kể trong chính trị', 'triều đình nhà Lý không gặp khó khăn nội bộ và xã hội vẫn hoàn toàn ổn định', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: nhà Lý suy yếu, xã hội rối ren nên cần một chính quyền đủ khả năng ổn định đất nước') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS7_B13_14', (SELECT id FROM lesson_metadata WHERE code = 'LS7_KNTT_B13'), 'LS7_KNTT_B13', 'Việc đặt chế độ Thái thượng hoàng cùng tổ chức chính quyền chặt chẽ hơn phản ánh', 'nhà Trần giao trọn quyền quản lí đất nước cho các địa phương tự quyết', 'nhà Trần phối hợp trong hoàng tộc và củng cố quyền lực trung ương', 'nhà Trần bỏ vai trò của vua, chuyển quyền cai trị cho quan ở lộ, phủ', 'nhà Trần tinh gọn bộ máy hơn thời Lý, giảm số cơ quan ở triều đình', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: nhà Trần tăng cường sự phối hợp trong hoàng tộc và củng cố quyền lực của chính quyền trung ương') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS7_B13_15', (SELECT id FROM lesson_metadata WHERE code = 'LS7_KNTT_B13'), 'LS7_KNTT_B13', 'Việc duy trì “ngụ binh ư nông” và tổ chức nhiều lực lượng quân đội có tác dụng chủ yếu', 'tách quân đội khỏi sản xuất, cho binh sĩ thường xuyên ở doanh trại', 'giảm lực lượng địa phương, tập trung toàn bộ quân đội ở Thăng Long', 'kết hợp bảo vệ đất nước với sản xuất, duy trì lực lượng rộng khắp', 'giao phòng thủ cho các vương hầu, không duy trì quân đội triều đình', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: chuyển việc phòng thủ sang các vương hầu và không còn duy trì quân đội của triều đình') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS7_B13_16', (SELECT id FROM lesson_metadata WHERE code = 'LS7_KNTT_B13'), 'LS7_KNTT_B13', 'Các biện pháp khai hoang, làm thủy lợi, đắp đê và miễn giảm tô thuế cho thấy', 'chủ trương giảm diện tích đất canh tác để chuyển sang thương nghiệp', 'chỉ chú trọng ruộng quý tộc, không quan tâm sản xuất của làng xã', 'nông nghiệp phát triển tự phát, không có sự hỗ trợ từ triều đình', 'nhà Trần coi trọng phục hồi nông nghiệp, giúp ổn định đời sống', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: nhà Trần coi trọng phục hồi và phát triển nông nghiệp, tạo điều kiện mở rộng sản xuất và ổn định đời sống') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS7_B13_17', (SELECT id FROM lesson_metadata WHERE code = 'LS7_KNTT_B13'), 'LS7_KNTT_B13', 'Sự phát triển của chợ, phố phường Thăng Long và thương cảng Vân Đồn phản ánh', 'thương nghiệp mở rộng cả trong nước lẫn buôn bán với nước ngoài', 'trao đổi chủ yếu thu hẹp ở làng xã, ít liên hệ với trung tâm kinh tế', 'thương nghiệp chỉ ở biên giới, chưa có điểm buôn bán tại kinh thành', 'nhà Trần hạn chế ngoại thương và đóng cửa các cảng biển quan trọng', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: hoạt động thương nghiệp mở rộng cả trong nước lẫn giao lưu buôn bán với thương nhân nước ngoài') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS7_B13_18', (SELECT id FROM lesson_metadata WHERE code = 'LS7_KNTT_B13'), 'LS7_KNTT_B13', 'Sự phân hóa giữa quý tộc, nông dân, thợ thủ công, thương nhân và nô tì cho thấy', 'các tầng lớp xã hội thời Trần có địa vị, quyền lợi hoàn toàn bình đẳng', 'xã hội có nhiều tầng lớp với quyền lợi, nghĩa vụ khác nhau, phân hóa rõ', 'nông dân có nhiều đặc quyền nhất, nắm chức vụ chủ chốt của triều đình', 'nô tì có địa vị cao hơn quý tộc do trực tiếp tham gia sản xuất', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: xã hội thời Trần có nhiều tầng lớp với quyền lợi và nghĩa vụ khác nhau, thể hiện sự phân hóa rõ hơn') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS7_B13_19', (SELECT id FROM lesson_metadata WHERE code = 'LS7_KNTT_B13'), 'LS7_KNTT_B13', 'Việc Nho giáo nâng cao vị thế trong khi Phật giáo, Đạo giáo và tín ngưỡng dân gian vẫn tồn tại phản ánh', 'Nho giáo thay thế hoàn toàn mọi tôn giáo khác trong đời sống thời Trần', 'Phật giáo mất ảnh hưởng do triều đình chỉ khuyến khích Nho học, thi cử', 'tư tưởng đa dạng, Nho giáo ngày càng có vai trò rõ hơn trong xã hội', 'nhà Trần cấm tôn giáo khác để xây dựng bộ máy nhà nước theo Nho giáo', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: đời sống tư tưởng, tôn giáo đa dạng, đồng thời Nho giáo ngày càng có vai trò rõ hơn trong xã hội') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS7_B13_20', (SELECT id FROM lesson_metadata WHERE code = 'LS7_KNTT_B13'), 'LS7_KNTT_B13', 'Việc mở rộng trường học, tổ chức thi cử thường xuyên và xuất hiện nhiều thành tựu sử học, quân sự, y học cho thấy', 'khoa học thời Trần chủ yếu truyền miệng, chưa có học thuật quy củ', 'giáo dục phát triển nhưng sử học, quân sự và y học chưa có thành tựu', 'nhà Trần chỉ chú trọng khoa cử, bỏ bê tri thức quân sự và đời sống', 'giáo dục, khoa học phát triển, nâng cao trí tuệ và năng lực quản lí', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: giáo dục và khoa học - kĩ thuật có bước phát triển, góp phần nâng cao đời sống trí tuệ và năng lực quản lí đất nước') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS7_B13_21', (SELECT id FROM lesson_metadata WHERE code = 'LS7_KNTT_B13'), 'LS7_KNTT_B13', 'Từ tổ chức chính quyền, pháp luật và quân đội, nhận xét phù hợp về nhà nước thời Trần', 'bộ máy nhà nước chặt chẽ hơn, tăng năng lực quản lí, bảo vệ quốc gia', 'chính quyền trung ương yếu do các lộ, phủ, vương hầu tự trị độc lập', 'nhà Trần chỉ quản lí bằng huyết thống hoàng tộc, không dùng luật pháp', 'quân đội phát triển làm cơ quan hành chính, pháp luật mất hết vai trò', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: bộ máy nhà nước được củng cố theo hướng chặt chẽ hơn, tăng khả năng quản lí và bảo vệ quốc gia') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS7_B13_22', (SELECT id FROM lesson_metadata WHERE code = 'LS7_KNTT_B13'), 'LS7_KNTT_B13', 'Kết hợp tình hình nông nghiệp, thủ công nghiệp và thương nghiệp, kết luận phù hợp về kinh tế thời Trần', 'kinh tế chỉ phát triển nông nghiệp, công - thương nghiệp suy giảm', 'kinh tế đa dạng, coi trọng nông nghiệp và mở rộng sản xuất, trao đổi', 'triều đình chỉ quan tâm thương nghiệp, bỏ bê các ngành sản xuất khác', 'kinh tế thời Trần phụ thuộc hoàn toàn vào ngoại thương qua Vân Đồn', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: nền kinh tế có bước phát triển tương đối đa dạng, vừa coi trọng nông nghiệp vừa mở rộng sản xuất và trao đổi') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
