INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS7_B17_21', (SELECT id FROM lesson_metadata WHERE code = 'LS7_KNTT_B17'), 'LS7_KNTT_B17', 'Từ bộ máy tập quyền, Quốc triều hình luật và việc xây dựng quân đội mạnh, nhận xét phù hợp', 'nhà Lê sơ tăng cường năng lực quản lí, giữ kỉ cương và bảo vệ quốc gia', 'triều đình giảm quyền trung ương, để các thừa tuyên tự quyết mọi việc', 'pháp luật ban hành nhưng không gắn với chính quyền và bảo vệ đất nước', 'quân đội quản lí toàn bộ xã hội, thay thế bộ máy hành chính', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: nhà Lê sơ tăng cường năng lực quản lí, giữ kỉ cương và bảo vệ quốc gia') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
