INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS8_B02_15', (SELECT id FROM lesson_metadata WHERE code = 'LS8_KNTT_B02'), 'LS8_KNTT_B02', 'Nông dân và bình dân thành thị có vai trò lớn trong Cách mạng tư sản Pháp vì', 'chiếm đa số dân cư, bị áp bức nặng nề và là lực lượng đông đảo nhất', 'nắm các vị trí chủ chốt trong nhà nước, quân đội và Giáo hội', 'có đặc quyền về thuế và ruộng đất nên muốn bảo vệ trật tự xã hội cũ', 'đã nắm quyền trước 1789 và trực tiếp điều hành bộ máy nhà nước', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: chiếm phần lớn dân số, chịu áp bức nặng nề và trở thành lực lượng đông đảo của cách mạng') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
