INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS8_B03_22', (SELECT id FROM lesson_metadata WHERE code = 'LS8_KNTT_B03'), 'LS8_KNTT_B03', 'Một nhà máy sử dụng máy hơi nước có thể đặt xa các dòng sông chảy xiết hơn trước. Hiện tượng này phản ánh', 'máy hơi nước làm sản xuất quay lại phụ thuộc chủ yếu vào sức nước tự nhiên', 'động lực mới giúp chọn địa điểm linh hoạt và mở rộng quy mô', 'máy hơi nước chỉ dùng cho tàu hoả, không đổi cách sản xuất', 'nhà máy không còn cần nhiên liệu, nhân công hay tài nguyên', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: nguồn động lực mới giúp lựa chọn địa điểm sản xuất linh hoạt hơn và mở rộng quy mô nhà máy') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS8_B03_23', (SELECT id FROM lesson_metadata WHERE code = 'LS8_KNTT_B03'), 'LS8_KNTT_B03', 'Năm 1850 Anh có 10.000 km đường sắt, Mỹ đứng thứ 4 thế giới về công nghiệp. Nhận xét đúng là:', 'công nghiệp hoá chưa tác động đáng kể đến giao thông và kinh tế', 'đường sắt phát triển khiến các nước giảm sản xuất công nghiệp', 'công nghiệp hoá giúp mở rộng hạ tầng, nâng vị thế kinh tế quốc gia', 'phát triển công nghiệp làm các nước quay lại kinh tế nông nghiệp', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: cách mạng công nghiệp góp phần mở rộng hạ tầng, nâng năng lực sản xuất và làm thay đổi vị thế kinh tế của các quốc gia') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS8_B03_24', (SELECT id FROM lesson_metadata WHERE code = 'LS8_KNTT_B03'), 'LS8_KNTT_B03', 'Bài học phù hợp khi liên hệ tác động hai mặt của cách mạng công nghiệp với quá trình công nghiệp hoá hiện nay', 'chỉ cần tăng máy móc vì kĩ thuật sẽ tự giải quyết mọi vấn đề xã hội', 'hạn chế đổi mới công nghệ để tránh biến đổi cơ cấu lao động, đô thị', 'ưu tiên sản xuất, vấn đề môi trường và lao động xử lí sau cùng', 'đổi mới công nghệ song hành với bảo vệ lao động, môi trường bền vững', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: cần thúc đẩy đổi mới công nghệ đồng thời bảo vệ người lao động, giảm ô nhiễm và sử dụng thành tựu theo hướng bền vững') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
