INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS8_B04_15', (SELECT id FROM lesson_metadata WHERE code = 'LS8_KNTT_B04'), 'LS8_KNTT_B04', 'Việc xây dựng đường giao thông ở thuộc địa cho thấy đặc điểm chủ yếu của chính sách kinh tế thực dân', 'đầu tư hạ tầng chủ yếu để nâng cao đời sống cư dân và cân bằng vùng miền', 'ưu tiên kết nối các trung tâm văn hoá nhằm bảo tồn bản sắc truyền thống', 'phát triển giao thông độc lập với hoạt động khai thác và mục tiêu quân sự', 'gắn hạ tầng với khai thác kinh tế và khả năng kiểm soát, đàn áp thuộc địa', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: gắn hạ tầng với khai thác kinh tế và khả năng kiểm soát, đàn áp thuộc địa') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS8_B04_16', (SELECT id FROM lesson_metadata WHERE code = 'LS8_KNTT_B04'), 'LS8_KNTT_B04', 'Nhận xét phù hợp nhất về những chuyển biến ở Đông Nam Á dưới ách đô hộ của thực dân phương Tây', 'mọi lĩnh vực đều biến đổi theo yêu cầu cai trị và khai thác của thực dân', 'chỉ kinh tế thay đổi, còn chính trị, văn hoá, xã hội giữ nguyên như cũ', 'xoá bỏ tầng lớp thống trị bản xứ và xây dựng xã hội không có giai cấp', 'nhằm nâng cao phúc lợi và bảo đảm quyền tự chủ của cư dân bản địa', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: các lĩnh vực chính trị, kinh tế, văn hoá và xã hội đều bị biến đổi theo yêu cầu cai trị và khai thác') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
