INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS8_B06_23', (SELECT id FROM lesson_metadata WHERE code = 'LS8_KNTT_B06'), 'LS8_KNTT_B06', 'Từ kết quả cuối thế kỉ XVIII, nhận xét khái quát nhất về ý nghĩa của công cuộc khai phá vùng đất phía Nam', 'giúp mở rộng lãnh thổ, phát triển kinh tế và củng cố chủ quyền quốc gia', 'chỉ đổi vùng cư trú, không tác động tới kinh tế và tổ chức xã hội', 'chủ yếu tạo điểm buôn bán, không liên quan đến việc mở rộng lãnh thổ', 'làm giảm vai trò cư dân, tách đất mới khỏi tiến trình lịch sử dân tộc', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: góp phần mở rộng lãnh thổ, phát triển kinh tế - giao thương và củng cố chủ quyền quốc gia') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
