INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_09', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Chính sách cộng sản thời chiến của nước Nga có nội dung nào sau đây?', 'Nhà nước kiểm soát tất cả các ngành kinh tế.', 'Quốc hữu hóa toàn bộ các xí nghiệp.', 'Trưng thu toàn bộ lương thực của nông dân.', 'Xóa bỏ cơ chế quản lý tập trung, bao cấp.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Quốc hữu hóa toàn bộ các xí nghiệp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_10', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Sau khi đánh tan giặc ngoại xâm và nội phản, nước Nga Xô viết đã thi hành chính sách tiến bộ nào?', 'Trao trả độc lập, tự do cho các dân tộc thuộc địa của đế quốc Nga.', 'Thi hành chính sách đối đầu căng thẳng với Mĩ và các nước tư bản.', 'Thực hiện các quyền tự do dân chủ và quyền tự quyết cho các dân tộc.', 'Xóa bỏ các giai cấp và tầng lớp để tạo nên sự công bằng trong xã hội.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Thực hiện các quyền tự do dân chủ và quyền tự quyết cho các dân tộc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_11', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Liên Xô bước vào quá trình xây dựng chủ nghĩa xã hội trong bối cảnh nào?', 'Là nước nông nghiệp, bị các nước bao vây, cấm vận.', 'Bình thường hóa quan hệ ngoại giao với Mỹ và Tây Âu.', 'Chịu tác động sâu sắc của khủng hoảng kinh tế 1929-1933.', 'Hệ thống xã hội chủ nghĩa đã hình thành và phát triển.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Là nước nông nghiệp, bị các nước bao vây, cấm vận.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_12', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Nội dung nào phản ánh đúng tình hình đất nước Liên Xô từ năm 1925 đến năm 1945?', 'Công cuộc tập thể hóa nông nghiệp đã hoàn thành.', 'Cơ cấu giai cấp trong xã hội không thay đổi lớn.', 'Phổ cập trung học cơ sở ở các vùng nông thôn.', 'Quá trình công nghiệp hóa, đô thị hóa đã tạm dừng.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Công cuộc tập thể hóa nông nghiệp đã hoàn thành.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_13', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Chính sách Cộng sản thời chiến (1918 – 1921) và chính sách Kinh tế mới (1921 – 1925) ở Nga đều nhằm mục đích', 'bảo vệ và xây dựng nước Nga Xô Viết.', 'phục hồi và phát triển nền kinh tế của Nga.', 'huy động mọi nguồn lực để chống thù trong, giặc ngoài.', 'xây dựng cơ sở vật chất của chủ nghĩa xã hội.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: phục hồi và phát triển nền kinh tế của Nga.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_17', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Chính sách kinh tế mới của nước Nga không có tác động nào sau đây?', 'Nền kinh tế Nga từng bước được phục hồi.', 'Đời sống nhân dân Nga được cải thiện.', 'Huy động lực lượng chống ngoại xâm.', 'Đất nước từng bước vượt qua khủng hoảng.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Huy động lực lượng chống ngoại xâm.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_18', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Đến năm 1940, ở nước Nga không còn tồn tại giai tầng nào?', 'Giai cấp công nhân.', 'Giai cấp nông dân.', 'Giai cấp tư sản.', 'Tầng lớp trí thức', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Giai cấp tư sản.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_19', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Năm 1920, những thắng lợi của Hồng quân trong việc đánh tan giặc ngoại xâm và nội phản đã', 'bảo vệ thành quả của Cách mạng tháng Mười.', 'bảo vệ thành quả của Chính sách kinh tế mới.', 'ngăn chặn được nguy cơ chiến tranh trên thế giới.', 'góp phần kết thúc chiến tranh thế giới thứ nhất.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: bảo vệ thành quả của Cách mạng tháng Mười.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_20', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Nhận xét nào đúng về tình hình nước Nga và các nước Cộng hòa Xô viết đồng minh trước khi thống nhất?', 'Tăng cường sức mạnh để xây dựng thành công chủ nghĩa xã hội.', 'Xác định hướng đi mới cho các nước Cộng hoà Xô viết ở Nga.', 'Xác lập hệ thống xã hội chủ nghĩa làm đối trọng với chủ nghĩa tư bản.', 'Hình thành một quốc gia rộng lớn, có uy tín ở châu Âu và châu Á.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Tăng cường sức mạnh để xây dựng thành công chủ nghĩa xã hội.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_21', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Nước Nga đấu tranh chống thù trong, giặc ngoài (1918-1920) trong bối cảnh lịch sử nào?', 'Chiến tranh thế giới thứ nhất chưa kết thúc.', 'Đất nước vô cùng khó khăn, gian khổ.', 'Chính quyền Xô viết chưa được xác lập.', 'Quyền lực của đế quốc Nga còn mạnh.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Đất nước vô cùng khó khăn, gian khổ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_22', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Nước Nga đã đạt được kết quả nào sau đây trong quá trình thực hiện nhiệm vụ trọng tâm giai đoạn (1918 - 1920)?', 'Khắc phục được hậu quả của chiến tranh', 'Xóa bỏ hoàn toàn các tổ chức phản động.', 'Ký hòa ước với các nước đế quốc.', 'Bảo vệ được chính quyền cách mạng.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Bảo vệ được chính quyền cách mạng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_23', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Tình hình nước Nga (1917 - 1920) và tình hình Việt Nam (1945 - 1946) có điểm tương đồng nào sau đây?', 'Tiến hành trưng thu lương thực thừa.', 'Đấu tranh chống thù trong giặc ngoài.', 'Phát động phong trào bình dân học vụ.', 'Ban hành và thực thi “Sắc lệnh ruộng đất”.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Đấu tranh chống thù trong giặc ngoài.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_25', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Từ năm 1922 đến năm 1941, công cuộc xây dựng chủ nghĩa xã hội ở Liên Xô đạt được kết quả tiêu biểu nào?', 'Đạt được thế cân bằng về sức mạnh quân sự với Mỹ.', 'Phá vỡ thế độc quyền về vũ khí nguyên tử của Mỹ.', 'Mở rộng được không gian của chủ nghĩa xã hội.', 'Trở thành một trong những cường quốc của thế giới.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Trở thành một trong những cường quốc của thế giới.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_26', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Chính sách kinh tế mới của nước Nga năm 1921 được ban hành trong bối cảnh nào?', 'Liên quân 14 nước tấn công vào nước Nga Xô viết.', 'Độc lập dân tộc bị đe dạo rất nghiêm trọng.', 'Nước Nga Xô viết đã vượt qua được khủng hoảng.', 'Chính sách Cộng sản thời chiến không còn phù hợp.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Chính sách Cộng sản thời chiến không còn phù hợp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_27', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Ý nào sau đây mô tả đúng tình hình nước Nga trước khi Liên Xô được thành lập?', 'Tiến hành xây dựng chủ nghĩa xã hội, trọng tâm là công nghiệp hoá.', 'Đấu tranh chống thù trong giặc ngoài, bảo vệ chính quyền cách mạng.', 'Tiến hành tập thể hóa nông nghiệp, tiêu diệt bộ phận bóc lột ở nông thôn.', 'Thực hiện cách mạng văn hóá, xoá nạn mù chữ trong cả nước.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Đấu tranh chống thù trong giặc ngoài, bảo vệ chính quyền cách mạng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
