INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_29', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Thành tựu quan trọng trên lĩnh vực kinh tế của Liên Xô trong công cuộc xây dựng chủ nghĩa xã hội là', 'trở thành cường quốc công nghiệp đứng thứ hai thế giới.', 'tỉ trọng nông nghiệp chiếm đa số trong cơ cấu kinh tế.', 'trở thành cường quốc công nghiệp đứng thứ hai châu Âu.', 'trở thành cường quốc nông nghiệp đứng đầu châu Âu.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: trở thành cường quốc công nghiệp đứng thứ hai thế giới.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B01_31', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B01'), 'LS9_KNTT_B01', 'Nội dung nào sau đây không phải là hạn chế của công cuộc xây dựng chủ nghĩa xã hội ở Liên Xô giai đoạn 1925 - 1941?', 'Mất cân đối giữa công nghiệp nặng và công nghiệp nhẹ.', 'Mất cân đối giữa ngành công nghiệp và ngành nông nghiệp.', 'Vi phạm nguyên tắc tự chủ trong công nghiệp hoá.', 'Vi phạm nguyên tắc tự nguyện trong tập thể hóa nông nghiệp.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Vi phạm nguyên tắc tự chủ trong công nghiệp hoá.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
