INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B02_04', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B02'), 'LS9_KNTT_B02', 'Nội dung nào sau đây phản áng đúng phạm vi ảnh hưởng của cuộc khủng hoảng kinh tế thế giới 1929-1933?', 'Chỉ ảnh hưởng ở các nước tư bản phát triển trên thế giới.', 'Chỉ có ở các nước tư bản phát triển và thuộc địa của chúng.', 'Bùng nổ đầu tiên ở châu Âu, sau đó lan rộng ra châu Mỹ.', 'Chỉ xuất hiện các nước phát xít và các nước phụ thuộc.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Chỉ có ở các nước tư bản phát triển và thuộc địa của chúng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
