INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B02_07', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B02'), 'LS9_KNTT_B02', 'Cuộc khủng hoảng kinh tế thế giới 1929 - 1933 diễn ra đầu tiên ở Mỹ vì', 'Mỹ thiếu một thị trường và hệ thống thuộc địa rộng lớn.', 'Mỹ đã đạt đến sự phồn vinh trong phát triển kinh tế.', 'những cuộc đình công, bãi công của công nhân ngày càng nhiều.', 'Mỹ bước vào quá trình công nghiệp tương đối muộn.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Mỹ đã đạt đến sự phồn vinh trong phát triển kinh tế.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
