INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B02_15', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B02'), 'LS9_KNTT_B02', 'Cuộc khủng hoảng kinh tế thế giới 1929 - 1933 diễn ra đầu tiên ở quốc gia nào sau đây?', 'Anh.', 'Pháp.', 'Đức.', 'Mỹ.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Mỹ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B02_16', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B02'), 'LS9_KNTT_B02', 'Nhận xét nào sau đây là đúng về phong trào đấu tranh của nhân dân Đức từ năm 1918 đến năm 1923?', 'Có sự thay đổi về mục tiêu đấu tranh.', 'Ngăn cả quá trình phát xít hóa của Đức.', 'Thành lập được chính quyền Xô viết.', 'Làm sụp đổ hệ thống thuộc địa của Đức.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Có sự thay đổi về mục tiêu đấu tranh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B02_17', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B02'), 'LS9_KNTT_B02', 'Tổ chức nào được thành lập năm 1919 có vai trò quan trọng đối với phong trào cách mạng thế giới?', 'Đảng Cộng sản Pháp.', 'Hội Quốc liên.', 'Liên hợp quốc.', 'Quốc tế Cộng sản.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Quốc tế Cộng sản.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B02_18', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B02'), 'LS9_KNTT_B02', 'Sự ra đời của Quốc tế Cộng sản năm 1919 nhờ vai trò tích cực của', 'Hội Quốc liên.', 'Chiến tranh thế giới thứ nhất.', 'Quốc tế II.', 'Đảng Bônsêvích Nga.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Đảng Bônsêvích Nga.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B02_19', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B02'), 'LS9_KNTT_B02', 'Trong thời gian tồn tại (1919-1943), Quốc tế Cộng sản đã', 'tạo cơ sở về mặt tổ chức và lý luận cho sự ra đời của Liên hợp quốc.', 'làm cho chủ nghĩa tư bản châu Âu bước vào thời kỳ khủng hoảng kéo dài.', 'đề ra đường lối cho từng thời kì phát triển của cách mạng thế giới.', 'hoàn thành sứ mệnh lịch sử trong việc bảo vệ hòa bình, an ninh thế giới.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: đề ra đường lối cho từng thời kì phát triển của cách mạng thế giới.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B02_20', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B02'), 'LS9_KNTT_B02', 'Nhân tố nào sau đây thúc đẩy mạnh mẽ phong trào đấu tranh của nhân dân Đức giai đoạn 1918-1923?', 'Chế độ quân chủ chuyên chế suy yếu.', 'Lãnh thổ bị chia cắt thành hai miền.', 'Sự ra đời của Đảng Cộng sản Đức.', 'Giai cấp công nhân Đức bị thất nghiệp.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Sự ra đời của Đảng Cộng sản Đức.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B02_22', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B02'), 'LS9_KNTT_B02', 'Ý nào sau đây không phải là nguyên nhân dẫn đến sự bùng nổ và phát triển của phong trào cách mạng 1918 - 1923 ở châu Âu?', 'Ảnh hưởng của thắng lợi Cách mạng tháng Mười Nga.', 'Sự hình thành và phát triển của chủ nghĩa phát xít.', 'Sự thành lập chính quyền Xô viết ở nước Nga.', 'Tinh thần đấu tranh của công nhân, nhân dân lao động.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Sự hình thành và phát triển của chủ nghĩa phát xít.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B02_23', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B02'), 'LS9_KNTT_B02', 'Ý nào sau đây là mục tiêu của phong trào cách mạng 1918 - 1923 ở châu Âu?', 'Thành lập chính quyền do giai cấp tư sản tiến bộ lãnh đạo.', 'Xây dựng mô hình nhà nước mới theo kiểu nước Nga Xô viết.', 'Yêu cầu chính phủ kết thúc Chiến tranh thế giới thứ nhất.', 'Thành lập tổ chức quốc tế lãnh đạo phong trào công nhân.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Xây dựng mô hình nhà nước mới theo kiểu nước Nga Xô viết.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B02_24', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B02'), 'LS9_KNTT_B02', 'Ý nghĩa của sự thành lập Quốc tế Cộng sản đối với phong trào cách mạng ở châu Âu là', 'thúc đẩy sự phát triển của phong trào công nhân.', 'thúc đẩy sự hình thành nhiều nhà nước vô sản.', 'định hướng sự phát triển của phong trào nông dân.', 'giành ruộng đất và quyền lợi cho bộ phận tiểu nông.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: thúc đẩy sự phát triển của phong trào công nhân.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B02_25', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B02'), 'LS9_KNTT_B02', 'Một trong những nguyên nhân dẫn đến sự hình thành của chủ nghĩa phát xít Đức là', 'sự ủng hộ về vũ khí chiến tranh của I-ta-li-a.', 'sự phát triển kinh tế của Đức giai đoạn 1924 - 1929.', 'chính sách dung dưỡng, thoả hiệp của Anh, Pháp và Ba Lan.', 'hậu quả nặng nề của cuộc đại suy thoái kinh tế 1929 - 1933.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: hậu quả nặng nề của cuộc đại suy thoái kinh tế 1929 - 1933.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B02_26', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B02'), 'LS9_KNTT_B02', 'Một trong những chính sách đối ngoại của Mỹ trong giai đoạn giữa hai cuộc chiến tranh thế giới (1918 - 1939) là', 'tham gia tích cực vào hoạt động của Hội Quốc liên.', 'liên kết với Liên Xô chống chủ nghĩa phát xít.', 'thực hiện và đề cao chủ nghĩa biệt lập truyền thống.', 'viện trợ cho Anh, Pháp chống lại sự xâm lược của Đức.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: thực hiện và đề cao chủ nghĩa biệt lập truyền thống.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B02_27', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B02'), 'LS9_KNTT_B02', 'Ý nào sau đây phản ánh đúng sự phát triển của kinh tế Mỹ giai đoạn 1924-1929?', 'Lâm vào đại suy thoái khiến sản lượng công nghiệp sụt giảm.', 'Phát triển nhanh chóng, xen kẽ với khủng hoảng nhẹ.', 'Trở thành trung tâm công nghiệp, thương mại, tài chính quốc tế.', 'Tiến hành công cuộc công nghiệp hoa xã hội chủ nghĩa.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Trở thành trung tâm công nghiệp, thương mại, tài chính quốc tế.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B03_01', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B03'), 'LS9_KNTT_B03', 'Năm 1940, tình hình các nước Đông Nam Á có đặc điểm nổi bật nào sau đây?', 'Liên minh khu vực được hình thành.', 'Các nước giành được độc lập.', 'Đảng Cộng sản ra đời ở các nước.', 'Phát xít Nhật tiến hành xâm lược.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Phát xít Nhật tiến hành xâm lược.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B03_02', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B03'), 'LS9_KNTT_B03', 'Nhận xét vào đúng về phong trào đấu tranh giải phóng dân tộc ở Đông Nam Á từ năm 1920 đến năm 1940?', 'Chủ yếu đấu tranh chống thực dân bằng phương pháp hoà bình.', 'Chuyển từ đấu tranh đòi độc lập sang đòi quyền lợi kinh tế.', 'Có sự chuyển biến từ khởi nghĩa vũ trang sang đấu tranh ôn hoà.', 'Phát triển đồng thời theo hai khuynh hướng: tư sản và vô sản.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Phát triển đồng thời theo hai khuynh hướng: tư sản và vô sản.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B03_03', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B03'), 'LS9_KNTT_B03', 'Từ năm 1922, lãnh đạo phong trào đấu tranh của giai cấp công nhân Nhật Bản là', 'Đảng Dân chủ.', 'Đảng Quốc đại.', 'Quốc dân Đảng.', 'Đảng Cộng sản.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Đảng Cộng sản.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B03_04', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B03'), 'LS9_KNTT_B03', 'Năm 1927, ở Nhật Bản diễn ra sự kiện nào sau đây tác động tiêu cực đến nền kinh tế?', 'Quân phiệt nắm giữ mọi quyền lực.', 'Động đất và sóng thần ở Nagasaki.', 'Thủ tướng Tanaca lên nắm quyền.', 'Cuộc khủng hoảng tài chính ở Tôkiô.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Cuộc khủng hoảng tài chính ở Tôkiô.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
