INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B03_08', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B03'), 'LS9_KNTT_B03', 'Sau khi ra đời, nước Cộng hòa nhân dân Mông Cổ đã', 'từng bước tiến lên con đường xây dựng chủ nghĩa xã hội.', 'phát triển theo đường lối hòa bình, trung lập và tích cực.', 'tích cực viện trợ cho các nước châu Á đấu tranh giành độc lập.', 'đấu tranh kiên cường chống lại chính sách cấm vận của Mỹ.', 1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: từng bước tiến lên con đường xây dựng chủ nghĩa xã hội.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B03_09', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B03'), 'LS9_KNTT_B03', 'Sự kiện nào đánh dấu bước ngoặt quan trọng trong lịch sử Trung Quốc từ năm 1918 đến năm 1945?', 'Đảng Cộng sản Trung Quốc được thành lập.', 'Đảng Cộng sản đánh bại Quốc dân đảng.', 'Phong trào Ngũ Tứ bùng nổ và lan rộng.', 'Cuộc nội chiến giữa Quốc - Cộng lần thứ nhất.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Đảng Cộng sản Trung Quốc được thành lập.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B03_10', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B03'), 'LS9_KNTT_B03', 'Từ năm 1937 đến năm 1945, Quốc Dân đảng và Đảng Cộng sản có mối quan hệ nào sau đây?', 'Đoàn kết chống lại sự xâu xé của đế quốc.', 'Diễn ra quá trình xung đột quân sự sâu sắc.', 'Đối đầu căng thẳng, chạy đua vũ trang.', 'Hợp tác để cùng kháng chiến chống Nhật.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Hợp tác để cùng kháng chiến chống Nhật.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B03_11', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B03'), 'LS9_KNTT_B03', 'Từ Năm 1937, nhân dân Trung Quốc đã phải thực hiện nhiệm vụ nào sau đây?', 'Quốc hữu hóa các xí nghiệp để hạn chế ảnh hưởng của đế quốc.', 'Chống lại cuộc chiến tranh xâm lược của quân phiệt Nhật.', 'Tiến hành cuộc thập tự chinh để giải quyết nhiệm vụ dân chủ.', 'Chống lại chế độ phong kiến giành ruộng đất cho nhân dân.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Chống lại cuộc chiến tranh xâm lược của quân phiệt Nhật.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
