INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B03_14', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B03'), 'LS9_KNTT_B03', 'Nội dung nào sau đây phản ánh đúng đặc điểm của Nhật Bản ngay sau Chiến tranh thế giới thứ nhất?', 'Nội bộ giới quân phiệt và tài phiệt Nhật có sự phân hóa sâu sắc.', 'Nền kinh tế Nhật Bản phát triển nhanh chóng sau chiến tranh.', 'Chính quyền Nhật Bản tiến hành quân sự hóa bộ máy nhà nước.', 'Cuộc khủng hoảng tài chính trầm trọng đã diễn ra ở Tôkiô.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Nền kinh tế Nhật Bản phát triển nhanh chóng sau chiến tranh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
