INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B03_16', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B03'), 'LS9_KNTT_B03', 'Ý nào sau đây là tình hình của Nhật Bản sau cuộc đại suy thoái kinh tế?', 'Chủ nghĩa quân phiệt phục hồi, tiến hành đẩy mạnh chiến tranh xâm lược.', 'Đảng phát xít nắm quyền lãnh đạo, tiến hành quân sự hóa đất nước.', 'Chính phủ tìm cách khắc phục ảnh hưởng của cuộc khủng hoảng năng lượng.', 'Đảng Cộng sản lên nắm quyền, thực hiện các quyền tự do, dân chủ.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Chủ nghĩa quân phiệt phục hồi, tiến hành đẩy mạnh chiến tranh xâm lược.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
