INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B04_01', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B04'), 'LS9_KNTT_B04', 'Giai đoạn 1939 - 1941, cuộc chiến tranh thế giới thứ hai mang tính chất phi nghĩa đối với cả hai bên tham chiến vì', 'phát xít sử dụng lực lượng quân sự lớn, nhanh chóng đánh chiếm các nước.', 'các nước Anh, Pháp không thành thực ngăn cản chiến tranh phát xít.', 'Pháp bị quân Đức chiếm đóng và phải chịu mọi phí tổn của chiến tranh.', 'mặt trận Đồng minh chưa được thành lập để đoàn kết các dân tộc đấu tranh.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: các nước Anh, Pháp không thành thực ngăn cản chiến tranh phát xít.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B04_02', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B04'), 'LS9_KNTT_B04', 'Trước âm mưu và hành động của phe phát xít, nước nào đã ban hành đạo luật trung lập?', 'Liên Xô.', 'Pháp.', 'Anh.', 'Mỹ.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Mỹ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B04_03', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B04'), 'LS9_KNTT_B04', 'Nội dung nào sau đây không phản ánh đúng về hậu quả của Chiến tranh thế giới thứ hai (1939 -1945)', 'Chiến tranh đã lôi cuốn hơn 76 quốc gia tham gia vào vòng chiến.', 'Phá hủy hàng triệu làng mạc, thành phố, nhà máy, xí nghiệp.', 'Các nước thắng trận không bị thiệt hại và giành được nhiều lợi nhuận.', 'Liên Xô là quốc gia chịu nhiều tổn thất về người nhất trong chiến tranh.', 3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Các nước thắng trận không bị thiệt hại và giành được nhiều lợi nhuận.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B04_04', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B04'), 'LS9_KNTT_B04', 'Tháng 8 năm 1945, Nhật tuyên bố đầu hàng quân Đồng minh vô điều kiện vì', 'Nhật muốn bảo tồn những thành quả của quá trình phát triển đất nước.', 'Ở Nhật diễn ra cuộc cách mạng, lật đổ sự thống trị của Nhật hoàng.', 'Những thiệt hại nặng nề của quân Nhật ở trên chiến trường.', 'Quân đội Nhật trên các chiến trường đã bị đánh bại hoàn toàn.', 3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Những thiệt hại nặng nề của quân Nhật ở trên chiến trường.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B04_06', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B04'), 'LS9_KNTT_B04', 'Các cường quốc tư bản dân chủ và Liên Xô không thể ngăn chặn được cuộc chiến tranh phát xít vì', 'chưa có sự đoàn kết thống nhất ngay từ đầu cuộc chiến.', 'chưa có một trật thế giới để điều phối quan hệ quốc tế.', 'các nước quá tự tin vào sức mạnh quân sự của mỗi nước.', 'sức mạnh áp đảo hoàn toàn của Đức và đồng minh.', 1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: chưa có sự đoàn kết thống nhất ngay từ đầu cuộc chiến.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B04_07', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B04'), 'LS9_KNTT_B04', 'Chiến tranh thế giới thứ hai (1939-1945) đã không có tác động nào đến tình hình thế giới?', 'Dẫn tới sự ra đời của các nước xã hội chủ nghĩa trên thế giới.', 'Ảnh hưởng tích cực đến phong trào giải phóng dân tộc trên thế giới.', 'Dẫn tới những mâu thuẫn của các nước thắng trận về vấn đề thuộc địa.', 'Làm thay đổi tương quan lực lượng giữa các nước tư bản chủ nghĩa.', 3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Dẫn tới những mâu thuẫn của các nước thắng trận về vấn đề thuộc địa.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B04_09', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B04'), 'LS9_KNTT_B04', 'Nguyên nhân sâu xa dẫn tới sự bùng nổ của các cuộc chiến tranh thế giới trong thế kỉ XX là do', 'sự ra đời của Liên Xô và các nước xã hội chủ nghĩa.', 'sự mâu thuẫn giữa các nước đế quốc về vấn đề thuộc địa.', 'sự dung dưỡng, thỏa hiệp của các nước tư bản châu Âu.', 'sự bùng nổ mạnh mẽ của phong trào cách mạng thế giới.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: sự mâu thuẫn giữa các nước đế quốc về vấn đề thuộc địa.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B04_10', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B04'), 'LS9_KNTT_B04', 'Sự kiện quân đội Nhật tấn công hạm đội Thái Bình Dương của Mỹ tại Trân Châu Cảng ngày 7/12/1941 có tác động nào sau đây?', 'Chấm dứt mối quan hệ đồng minh giữa Mỹ và Nhật.', 'Mỹ buộc phải tham gia vào cuộc chiến tranh.', 'Làm suy giảm nghiêm trọng sức mạnh của quân Mỹ.', 'Bảo vệ hệ thống thuộc địa của Nhật ở châu Á.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Mỹ buộc phải tham gia vào cuộc chiến tranh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B04_11', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B04'), 'LS9_KNTT_B04', 'Nguyên nhân sâu sa nào sau đây dẫn đến sự bùng nổ của Chiến tranh thế giới thứ hai?', 'Chính sách dung dưỡng, thoả hiệp của các cường quốc phương Tây.', 'Sự hình thành các lò lửa chiến tranh của chủ nghĩa phát xít.', 'Mâu thuẫn giữa các nước về thị trường và thuộc địa.', 'Các nước Anh, Pháp, Mỹ bao vây, tiêu diệt Liên Xô.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Mâu thuẫn giữa các nước về thị trường và thuộc địa.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B04_12', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B04'), 'LS9_KNTT_B04', 'Sự kiện nào sau đây thúc đẩy mâu thuẫn giữa các nước đế quốc trở nên sâu sắc?', 'Nhật Bản xâm lược Trung Quốc (1931).', 'Hít-le trở thành Thủ tướng Đức (1933).', 'Liên Xô hoàn thành công cuộc công nghiệp hóa (1937).', 'Cuộc đại suy thoái kinh tế bùng nổ và kéo dài (1929 -1933).', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Cuộc đại suy thoái kinh tế bùng nổ và kéo dài (1929 -1933).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B04_13', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B04'), 'LS9_KNTT_B04', 'Sự kiện châm ngòi cho sự bùng nổ của cuộc Chiến tranh thế giới thứ hai là', 'cuộc đại suy thoái kinh tế (1929 - 1933).', 'Đức tấn công Ba Lan (1-9-1939).', 'Nhật tấn công Mỹ (7-12-1941).', 'chiến dịch Xta-lin-grát (11-1942).', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Đức tấn công Ba Lan (1-9-1939).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B04_15', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B04'), 'LS9_KNTT_B04', 'Quốc gia nào trong phe Đồng minh giữ vai trò đi đầu trong chiến thắng chủ nghĩa phát xít?', 'Trung Quốc. Anh', 'Hà Lan. Pháp', 'Tây Ban Nha. Mĩ', 'Liên Xô.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Liên Xô.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_01', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Ngoài mục tiêu kinh tế, cuộc bãi công của công nhân Ba Son còn nhằm mục đích nào sau đây?', 'Thực hiện khẩu hiệu đấu tranh “Nhà máy về tay thợ thuyền”.', 'Ngăn cản tàu chiến Pháp sang đàn áp cách mạng Trung Quốc.', 'Đấu tranh chống Pháp và phong kiến để giành độc lập dân tộc.', 'Phá bỏ những giao kèo đã ký kết trước đó với chủ xưởng..', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Ngăn cản tàu chiến Pháp sang đàn áp cách mạng Trung Quốc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_02', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Nội dung nào sau đây không phản ánh mục tiêu đấu tranh của giai cấp tư sản Việt Nam sau Chiến tranh thế giới thứ nhất?', 'chống lại sự canh tranh, chèn ép của tư sản Pháp và tư sản Hoa kiều.', 'đòi được tham gia vào bộ máy chính quyền, đòi quyền lợi về kinh tế.', 'tố cáo tội ác của chế độ quân chủ, đòi các quyền độc lập, tự do, dân chủ.', 'yêu cầu chính quyền thuộc địa trao cho một số quyền tự do, dân chủ.', 3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: tố cáo tội ác của chế độ quân chủ, đòi các quyền độc lập, tự do, dân chủ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_03', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Cuộc khởi nghĩa Yên Bái (1930) thất bại là do nguyên nhân khách quan nào?', 'Khởi nghĩa nổ ra hoàn toàn bị động.', 'Đường lối đấu tranh không rõ ràng.', 'Tổ chức Việt Nam Quốc dân đảng còn non yếu.', 'Thực dân Pháp còn mạnh, đủ sức đàn áp.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Thực dân Pháp còn mạnh, đủ sức đàn áp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_04', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Cuộc bãi công Ba Son năm 1925 có điểm khác biệt chủ yếu so với phong trào công nhân trước đó về', 'mục tiêu đấu tranh.', 'quy mô phong trào.', 'thành phần tham gia.', 'hình thức đấu tranh.', 1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: mục tiêu đấu tranh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_05', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Trong những năm 20 của thế kỷ XX, giai cấp công nhân Việt Nam không có hình thức đấu tranh nào sau đây?', 'Bãi công.', 'Khởi nghĩa từng phần.', 'Phá bỏ giao kèo.', 'Bỏ trốn.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Khởi nghĩa từng phần.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_07', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Sự chuyển biến về chất của phong trào công nhân Việt Nam trong những năm 1926 - 1927 đã chứng tỏ điều gì?', 'Công nhân trở thành giai cấp lãnh đạo cách mạng Việt Nam.', 'Trình độ giác ngộ của công nhân được nâng lên rõ rệt.', 'Phong trào công nhân hoàn toàn chuyển sang đấu tranh tự giác.', 'Khuynh hướng vô sản thắng thế hoàn toàn ở Việt Nam.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Trình độ giác ngộ của công nhân được nâng lên rõ rệt.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_08', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Cộng sản đoàn là nòng cốt cho sự ra đời của tổ chức cách mạng nào ở sau đây?', 'Tân Việt Cách mạng đảng.', 'Hội Việt Nam Cách mạng Thanh niên.', 'Đông Dương Cộng sản đảng.', 'Việt Nam Quốc dân đảng.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Hội Việt Nam Cách mạng Thanh niên.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_09', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Cơ sở hạt nhân đầu tiên của Việt Nam Quốc dân đảng là tổ chức nào sau đây?', 'Cộng sản đoàn.', 'Nam đồng thư xã.', 'Tâm tâm xã.', 'Việt Nam nghĩa đoàn.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Nam đồng thư xã.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_11', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Phong trào đấu tranh của công nhân Việt Nam trong giai đoạn 1926 - 1929 có điểm gì khác so với giai đoạn 1919 - 1925?', 'Bãi công với khẩu hiệu đấu tranh chính “tăng lương giảm giờ làm”.', 'Mang tính chất chính trị rõ rệt, có sự liên kết thành các phong trào chung.', 'Diễn ra quyết liệt đòi các mục tiêu về kinh tế, mang tính tự phát.', 'Phong trào đã giành được mục tiêu chiến lược cho cách mạng Việt Nam.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Mang tính chất chính trị rõ rệt, có sự liên kết thành các phong trào chung.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_12', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Một trong những hoạt động tiêu biểu của tầng lớp tiểu tư sản Việt Nam giai đoạn 1919-1925 là', 'Mít tinh kỷ niệm ngày Quốc tế Lao động.', 'đòi nhà cầm quyền thả Nguyễn An Ninh.', 'chống độc quyền kinh doanh cảng Sài Gòn.', 'ám sát trùm mộ phu Badanh ở Hà Nội.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: đòi nhà cầm quyền thả Nguyễn An Ninh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_14', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Nội dung nào phản ánh mục tiêu đấu tranh trong phong trào dân tộc dân chủ ở Việt Nam những năm 1919 - 1925?', 'Chống bọn tư bản Pháp nắm độc qưyền xuất cảng lúa gạo.', 'Đấu tranh chống Pháp, giành độc lập hoàn toàn cho dân tộc.', 'Chống phong kiến, giành quyền tự do dân chủ.', 'Đòi một số quyền lợi về kinh tế và các quyền tự do dân chủ.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Đòi một số quyền lợi về kinh tế và các quyền tự do dân chủ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_15', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Năm 1919, Phan Châu Trinh và một số người Việt Nam yêu nước tại Pháp đã sáng lập tổ chức nào sau đây?', 'Hội liên hiệp các dân tộc thuộc địa.', 'Hội liên hiệp các dân tộc bị áp bức Á Đông.', 'Hội những người Việt Nam yêu nước.', 'Hội Việt Nam Cách mạng Thanh niên.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Hội những người Việt Nam yêu nước.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_16', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Trong thời gian hoạt động ở Pháp, Phan Châu Trinh đã viết nhiều tác phẩm nhằm mục tiêu chủ yếu nào sau đây?', 'Truyền bá chủ nghĩa Mác Lê-nin về nước.', 'Lên án chế độ quân chủ ở trong nước.', 'Hình thành khuynh hướng cứu nước mới.', 'Cổ vũ phong trào chống thuế ở Trung Kì.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Lên án chế độ quân chủ ở trong nước.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_18', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Nội dung nào phản ánh đặc điểm của phong trào dân tộc dân chủ ở Việt Nam (1918-1929)?', 'Phong trào diễn ra sôi nổi nhưng vẫn chưa thành công.', 'Có sự chuyển biến từ lập trường vô sản sang tư sản.', 'Có sự mâu thuẫn giữa các khuynh hướng cách mạng.', 'Đáp ứng được yêu cầu khách quan của lịch sử Việt Nam.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Phong trào diễn ra sôi nổi nhưng vẫn chưa thành công.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_19', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Hoạt động tiêu biểu nhất của Hội Việt Nam Cách mạng Thanh niên nhằm phát triển cơ sở của Hội là', 'mở lớp huấn luyện chính trị ở Quảng Châu.', 'ra báo Thanh niên làm cơ quan ngôn luận.', 'xuất bản tác phẩm Đường Kách mệnh.', 'phong trào “Vô sản hóa”.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: phong trào “Vô sản hóa”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_20', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Nguyên nhân chủ quan dẫn tới thất bại của cuộc khởi nghĩa Yên Bái là', 'khởi nghĩa nổ ra chậm so với yêu cầu.', 'sự lỗi thời của tư tưởng dân chủ tư sản.', 'khởi nghĩa nổ ra trong thế bị động.', 'thực dân Pháp còn mạnh, tăng cường đàn áp.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: khởi nghĩa nổ ra trong thế bị động.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_22', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Việt Nam Quốc dân đảng chủ trương đấu tranh chống Pháp bằng phương pháp chủ yếu nào sau đây?', 'Tiến hành khởi nghĩa từng phần.', 'Cổ động bãi công đánh đuổi giặc Pháp.', 'Chống Pháp bằng biện pháp ôn hòa.', 'Tiến hành bạo lực cách mạng.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Tiến hành bạo lực cách mạng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_23', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Hội Việt Nam Cách mạng Thanh niên và Việt Nam Quốc dân đảng có điểm tương đồng nào sau đây?', 'Chú trọng gây dựng cơ sở cách mạng trong công nhân.', 'Mục tiêu đánh đổ Pháp, thiết lập nền quân chủ lập hiến.', 'Có sự phân hoá mạnh mẽ thành các tổ chức cộng sản.', 'Thể hiện tinh thần yêu nước, đấu tranh giải phóng dân tộc.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Thể hiện tinh thần yêu nước, đấu tranh giải phóng dân tộc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_24', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Trong quá trình đấu tranh, giai cấp tư sản đã lập một số tờ báo nhằm mục đích chủ yếu nào sau đây?', 'Làm công cụ tuyên truyền và đòi quyền lợi cho mình.', 'Truyền bá khuynh hướng cách mạng tư sản và vô sản.', 'Buộc Pháp phải trao trả các quyền dân tộc cơ bản.', 'Lên án chế độ quân chủ và giai cấp địa chủ phong kiến.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Làm công cụ tuyên truyền và đòi quyền lợi cho mình.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_25', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Lực lượng tham gia vào tổ chức Việt Nam Quốc dân đảng là', 'thân hào, thân sĩ ở nông thôn.', 'công nhân đồn điền cao su.', 'Việt kiều ở châu Âu và châu Á.', 'tầng lớp quý tộc tư sản hóa.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: thân hào, thân sĩ ở nông thôn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_27', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Sau Chiến tranh thế giới thứ nhất, phong trào dân tộc dân chủ ở Việt Nam có đặc điểm nổi bật nào sau đây?', 'Thu hút nhiều giai tầng lớp tham gia, hình thức phong phú và sôi nổi.', 'Xây dựng được khuynh hướng cứu nước khác biệt với thế giới.', 'Các khuynh hướng cách mạng mâu thuẫn và đối lập nhau.', 'Bị thực dân Pháp đàn áp, khủng bố trắng nên tạm thời lắng xuống.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Thu hút nhiều giai tầng lớp tham gia, hình thức phong phú và sôi nổi.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_28', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Tân Việt Cách mạng Đảng có hoạt động chính nào sau đây ?', 'Thường xuyên tổ chức ám sát cá nhân.', 'Phát triển mạnh hoạt động ở hải ngoại.', 'Giới thiệu các sách báo yêu nước tiến bộ.', 'Tổ chức cuộc đấu tranh nghị trường.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Giới thiệu các sách báo yêu nước tiến bộ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_29', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Cuộc đấu tranh của giai cấp tư sản Việt Nam sau Chiến tranh thế giới thứ nhất mang tính chất nào sau đây?', 'Triệt để.', 'Bạo lực.', 'Cải lương.', 'Tự giác.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Cải lương.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_31', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Nội dung nào sau đây không phải là hoạt động chủ yếu của Hội Việt Nam Cách mạng Thanh niên?', 'Ra báo Thanh niên, cử hội viên đi học ở Trung Quốc và Liên Xô.', 'Cử cán bộ học tập kinh nghiệm của Tân Việt Cách mạng đảng.', 'Thực hiện chủ trương “Vô sản hóa”, truyền bá lí luận giải phóng dân tộc.', 'Huấn luyện chính trị, đào tạo cán bộ, xây dựng cơ sở của Hội.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Cử cán bộ học tập kinh nghiệm của Tân Việt Cách mạng đảng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_32', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Nửa sau những năm 20 của thế kỉ XX, giai cấp tư sản Việt Nam đã thành lập một chính đảng là', 'Việt Nam Nghĩa đoàn.', 'Tân Việt Cách mạng đảng.', 'Việt Nam Quốc dân đảng.', 'Đảng Lập hiến.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Việt Nam Quốc dân đảng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_33', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Tổ chức Tâm tâm xã (1923) ra đời và hoạt động nhằm mục tiêu chủ yếu nào sau đây?', 'Đưa đất nước phát triển theo con đường tư bản chủ nghĩa.', 'Khôi phục quyền làm người của người Việt Nam.', 'Thành lập liên minh quốc tế để đấu tranh chống Pháp.', 'Nhờ sự giúp đỡ của Trung Quốc để đánh đuổi Pháp.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Khôi phục quyền làm người của người Việt Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_34', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Trong thời gian hoạt động ở Pháp, Phan Châu Trinh không có hoạt động tiêu biểu nào sau đây?', 'Diễn thuyết.', 'Viết báo.', 'Lập hội.', 'Ám sát.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Ám sát.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_35', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Nội dung nào sau đây phản ánh đúng về quy mô phong trào đấu tranh của giai cấp công nhân giai đoạn (1928 - 1929)?', 'Diễn ra khắp cả nước, thúc đẩy phong trào của giai cấp tư sản phát triển.', 'Diễn ra trên phạm vi cả nước nhưng sôi nổi và mạnh mẽ nhất ở Trung Kì.', 'Ngày càng được mở rộng và dần có sự liên kết thành phong trào chung.', 'Diễn ra trong phạm vi nhỏ hẹp nhưng sôi nổi, có nhiều thành phần tham gia.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Ngày càng được mở rộng và dần có sự liên kết thành phong trào chung.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_36', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Năm 1929, tổ chức Việt Nam Quốc dân đảng có hoạt động tiêu biểu nào sau đây?', 'Ám sát toàn quyền Đông Dương Méc-lanh.', 'Khởi nghĩa Yên Bái.', 'Ám sát trùm mộ phu Ba-danh.', 'Đấu tranh đòi thả Nguyễn An Ninh.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Ám sát trùm mộ phu Ba-danh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_37', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Các tổ chức yêu nước cách mạng ở Việt Nam ra đời trong bối cảnh nào sau đây?', 'Các tổ chức cộng sản lần lượt ra đời.', 'Phong trào công nhân mang tính tự giác.', 'Sự tăng cường đàn áp của thực dân Pháp.', 'Nền kinh tế thế giới lâm vào khủng hoảng.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Sự tăng cường đàn áp của thực dân Pháp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_38', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Hoạt động yêu nước của người Việt Nam ở nước ngoài trong những năm 20 của thế kỷ XX diễn ra chủ yếu ở nước nào sau đây?', 'Anh và Hà Lan.', 'Trung Quốc và Ấn Độ.', 'Trung Quốc và Pháp.', 'Liên Xô và Angiêri.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Trung Quốc và Pháp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B05_39', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B05'), 'LS9_KNTT_B05', 'Cuộc đấu tranh của công nhân thợ máy xưởng Ba Son (Sài Gòn) tháng 8/1925 đã chứng tỏ điều gì?', 'Giai cấp công nhân đã trưởng thành, đủ sức lãnh đạo cách mạng.', 'Phong trào công nhân chủ yếu hướng tới mục tiêu kinh tế.', 'Phong trào công nhân còn mang tính tự phát, quy mô nhỏ.', 'Phong trào công nhân bước đầu đi vào đấu tranh tự giác.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Phong trào công nhân bước đầu đi vào đấu tranh tự giác.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
