INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_01', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Hoạt động tích cực của Nguyễn Ái Quốc trong những năm 20 của thế kỷ XX đã', 'trực tiếp tạo ra sự phân hóa sâu sắc của các tổ chức cộng sản ở Việt Nam.', 'góp phần quan trọng hình thành khuynh hướng cách mạng vô sản ở Việt Nam.', 'làm cho Hội Việt Nam Cách mạng Thanh niên có sự phân hóa trong tổ chức.', 'làm thất bại con đường cứu nước mới theo khuynh hướng dân chủ tư sản.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: góp phần quan trọng hình thành khuynh hướng cách mạng vô sản ở Việt Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
