INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_05', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Sự kiện nào sau đây là minh chứng cho việc Nguyễn Ái Quốc trở thành người cộng sản đầu tiên của Việt Nam?', 'Đọc Luận cương Lê-nin về vấn đề dân tộc và thuộc địa (1920).', 'Tham hội Đại hội V của Quốc tế Cộng sản ở Liên Xô (1924).', 'Trở thành Ủy viên Ban Chấp hành Quốc tế Nông dân (1923).', 'Bỏ phiếu tán thành gia nhập Quốc tế Cộng sản (1920).', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Bỏ phiếu tán thành gia nhập Quốc tế Cộng sản (1920).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_07', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Đảng Cộng sản Việt Nam ra đời là sự kết hợp của nhiều yếu tố, trong đó yếu tố quan trọng hàng đầu là', 'phong trào công nhân.', 'phong trào dân tộc, dân chủ.', 'phong trào yêu nước.', 'chủ nghĩa Mác - Lê-nin.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: chủ nghĩa Mác - Lê-nin.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
