INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_21', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Đầu năm 1929, những người cộng sản ở Việt Nam nhận thức cần thiết phải thành lập một Đảng Cộng sản là do', 'phong trào yêu nước theo khuynh hướng tư sản phát triển mạnh.', 'cuộc khởi nghĩa Yên Bái thất bại, Việt Nam Quốc dân đảng tan rã.', 'phong trào công, nông theo con đường cách mạng vô sản phát triển mạnh.', 'sự phát triển mạnh của Hội Việt Nam Cách mạng Thanh niên.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: phong trào công, nông theo con đường cách mạng vô sản phát triển mạnh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
