INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_26', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Quá trình hoạt động của Nguyễn Ái Quốc từ năm 1920 đến năm 1923 có đặc điểm nổi bật nào sau đây?', 'Vừa vận động quốc tế vừa gây dựng cơ sở cách mạng trong nước.', 'Đưa chủ nghĩa Mác - Lênin vào các tổ chức cộng sản ở Việt Nam.', 'Xây dựng lý luận giải phóng dân tộc và đấu tranh giai cấp.', 'Vừa nghiên cứu lý luận Mác - Lênin, vừa làm công tác thực tế.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Vừa nghiên cứu lý luận Mác - Lênin, vừa làm công tác thực tế.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
