INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_46', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Nội dung nào sau đây không có trong Hội nghị thành lập Đảng Cộng sản Việt Nam tháng 2/1930?', 'Thống nhất các tổ chức cộng sản thành Đảng Cộng sản Việt Nam.', 'Bầu Ban Chấp hành Trung ương chính thức của Đảng Cộng sản.', 'Nguyễn Ái Quốc phê phán quan điểm sai lầm của ba tổ chức cộng sản.', 'Thông qua Chính cương vắn tắt, Sách lược vắn tắt của Đảng.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Bầu Ban Chấp hành Trung ương chính thức của Đảng Cộng sản.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_47', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Nội dung nào sau đây không phải hoạt động chủ yếu của Nguyễn Ái Quốc từ năm 1921 đến năm 1930?', 'Tiếp tục hành trình tìm đường cứu nước.', 'Đào tạo những cán bộ cốt cán cho cách mạng.', 'Xuất bản nhiều sách, báo tiến bộ, tích cực.', 'Tham gia sáng lập các tổ chức cách mạng.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Tiếp tục hành trình tìm đường cứu nước.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_48', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Nhiệm vụ hàng đầu của cách mạng Việt Nam được Nguyễn Ái Quốc nêu trong Cương lĩnh chính trị đầu tiên của Đảng là', 'thành lập chính phủ của toàn thể nhân dân.', 'lập chính chủ dân chủ cộng hòa.', 'chia ruộng đất cho người nông dân.', 'đánh đổ đế quốc và phong kiến.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: đánh đổ đế quốc và phong kiến.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_50', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Trong những năm 1921 - 1924, Nguyễn Ái Quốc có vai trò nào sau đây đối với cách mạng Việt Nam?', 'Tìm ra con đường cách mạng chân chính, khoa học.', 'Thành lập một chính đảng của giai cấp công nhân.', 'Xây dựng lý luận cách mạng giải phóng dân tộc.', 'Soạn thảo Cương lĩnh chính trị đầu tiên của Đảng.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Xây dựng lý luận cách mạng giải phóng dân tộc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_51', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Nguyễn Ái Quốc đã học tập và nghiên cứu xây dựng Đảng kiểu mới trong thời gian hoạt động ở quốc gia nào sau đây?', 'Anh.', 'Liên Xô.', 'Bỉ.', 'Trung Quốc.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Liên Xô.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_53', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Sự xuất hiện của ba tổ chức cộng sản ở Việt Nam năm 1929 không phải là', 'minh chứng cho sự phát triển mạnh mẽ của phong trào công nhân.', 'sự chuẩn bị trực tiếp cho sự thành lập Đảng Cộng sản Việt Nam.', 'sự kiện khởi đầu cho quá trình truyền bá chủ nghĩa Mác - Lê nin.', 'xu thế của cuộc đấu tranh giải phóng dân tộc theo khuynh hướng vô sản.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: sự kiện khởi đầu cho quá trình truyền bá chủ nghĩa Mác - Lê nin.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_54', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Tổ chức nào sau đây được Nguyễn Ái tham gia thành lập năm 1921?', 'Hội Liên hiệp các dân tộc thuộc địa.', 'Quốc tế Cộng sản.', 'Đảng Xã hội Pháp.', 'Hội Liên hiệp các dân tộc bị áp bức Á Đông.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Hội Liên hiệp các dân tộc thuộc địa.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_55', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Nội dung nào sau đây phản ánh đúng về Cương lĩnh chính trị đầu tiên của Đảng Cộng sản Việt Nam?', 'Là sự vận dụng linh hoạt các khuynh hướng cách mạng trên thế giới.', 'Là sự vận dụng sáng tạo tư tưởng dân chủ cộng hoà vào thực tiễn Việt Nam.', 'Là sự vận dụng sáng tạo chủ nghĩa Mác - Lê-nin vào thực tiễn Việt Nam.', 'Là sự kế thừa bài học kinh nghiệm của khuynh hướng dân chủ tư sản.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Là sự vận dụng sáng tạo chủ nghĩa Mác - Lê-nin vào thực tiễn Việt Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_56', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Phong trào công nhân có tác động nào sau đây đối với sự thành lập Đảng Cộng sản Việt Nam?', 'Là nhân tố quyết định cho sự ra đời của Đảng Cộng sản Việt Nam.', 'Chuẩn bị về lý luận, tổ chức và tư tưởng cho sự hình thành chính đảng.', 'Là nhân tố quan trọng đầu tiên, chi phối sự ra đời của Đảng Cộng sản.', 'Là cơ sở để tiếp thu chủ nghĩa Mác - Lê-nin, thúc đẩy phong trào yêu nước.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Là cơ sở để tiếp thu chủ nghĩa Mác - Lê-nin, thúc đẩy phong trào yêu nước.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_57', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Từ năm 1920, Nguyễn Ái Quốc đã trở thành thành viên của tổ chức quốc tế nào sau đây?', 'Hội Liên hiệp thuộc địa.', 'Tâm tâm xã.', 'Hội Quốc liên.', 'Quốc tế Cộng sản.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Quốc tế Cộng sản.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B06_58', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B06'), 'LS9_KNTT_B06', 'Nguyễn Ái Quốc đã vai trò quan trọng đầu tiên nào sau đây đối với cách mạng Việt Nam?', 'Thiết lập mối quan hệ của các mạng Việt Nam với cách mạng thế giới.', 'Chuẩn bị về tư tưởng chính trị cho sự ra đời của Đảng Cộng sản Việt Nam.', 'Khẳng định con đường cứu nước mới theo khuynh hướng vô sản.', 'Thống nhất các tổ chức cộng sản thành Đảng Cộng sản Việt Nam.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Khẳng định con đường cứu nước mới theo khuynh hướng vô sản.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_02', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Phong trào cách mạng 1930 - 1931 và 1936 - 1939 ở Việt Nam có đều có điểm tương đồng nào sau đây?', 'Chống kẻ thù của dân tộc và đòi quyền lợi cho toàn dân tộc.', 'Xây dựng khối liên minh công - nông vững mạnh trên cả nước.', 'Góp phần vào chống thế lực phát xít và chiến tranh đế quốc.', 'Tấn công vào kẻ thù chiến lược là Pháp và phong kiến tay sai.', 1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: Chống kẻ thù của dân tộc và đòi quyền lợi cho toàn dân tộc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_04', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Phong trào đấu tranh do Đảng lãnh đạo trong những năm 1936 - 1939 mang tính chất nào sau đây?', 'Dân tộc cải lương.', 'Dân tộc, dân chủ.', 'Dân tộc cực đoan.', 'Dân chủ chuyên chế.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Dân tộc, dân chủ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_06', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Trên lĩnh vực văn hóa - giáo dục, chính quyền Xô Viết Nghệ - Tĩnh (1930 – 1931) đã thực hiện chính sách nào sau đây?', 'Du nhập những làn sóng văn hóa mới vào Việt Nam.', 'Tăng cường an ninh trật tự, xóa bỏ tệ nạn xã hội.', 'Mở lớp dạy chữ Quốc ngữ và xóa bỏ các tệ nạn xã hội.', 'Tiến hành cải cách giáo dục toàn diện, đồng bộ.', 3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Mở lớp dạy chữ Quốc ngữ và xóa bỏ các tệ nạn xã hội.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_07', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Trong cuộc vận động dân chủ 1936 - 1939, lực lượng tham gia đấu tranh chủ yếu là', 'các lực lượng yêu nước, dân chủ tiến bộ.', 'thân hào, thân sĩ ở nông thôn.', 'công nhân và tư sản mại bản.', 'tư sản, tiểu tư sản, nông dân.', 1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: các lực lượng yêu nước, dân chủ tiến bộ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_08', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Phong trào cách mạng 1930 - 1931 đã khẳng định nhân tố đầu tiên đảm bảo thắng lợi cho cách mạng Việt Nam là', 'một chính quyền dân chủ được xây dựng hoàn chỉnh.', 'sự vững chắc của khối liên minh công nhân - nông dân.', 'một mặt trận đoàn kết lực lượng toàn dân tộc.', 'Đảng Cộng sản - đội tiên phong của giai cấp công nhân.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Đảng Cộng sản - đội tiên phong của giai cấp công nhân.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_10', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Nội dung nào sau đây là điều kiện khách quan thuận lợi cho phong trào đấu tranh ở Việt Nam trong những năm 1936 - 1939?', 'Đại hội lần thứ VII của Quốc tế Cộng sản được triệu tập (1935).', 'Phe trục phát xít Béc-lin - Rô-ma - Tô-ky-ô được thành lập (1935).', 'Thắng lợi của Liên Xô trong công cuộc xây dựng CNXH (1925 - 1941).', 'Chính phủ Mặt trận Nhân dân Pháp lên cầm quyền (1936).', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Chính phủ Mặt trận Nhân dân Pháp lên cầm quyền (1936).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_11', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Nội dung nào không phải là ý nghĩa của phong trào cách mạng 1930 - 1931 ở Việt Nam?', 'Khẳng định trên thực tế vai trò lãnh đạo của Đảng Cộng sản Đông Dương.', 'Khối liên minh công - nông được hình thành và phát triển mạnh mẽ.', 'Được đánh giá cao trong phong trào cộng sản và công nhân quốc tế.', 'Buộc thực dân Pháp phải thi hành một số nghị định có lợi cho nhân dân.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Buộc thực dân Pháp phải thi hành một số nghị định có lợi cho nhân dân.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_13', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Phong trào cách mạng 1936 - 1939 phát triển mạnh mẽ trong điều kiện chủ quan thuận lợi nào sau đây?', 'Pháp ban hành nhiều chính sách tự do dân chủ.', 'Căn cứ địa kháng chiến được hình thành và phát triển.', 'Lực lượng vũ trang được xây dựng và phát triển.', 'Cơ sở Đảng được phục hồi và phát triển mạnh mẽ.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Cơ sở Đảng được phục hồi và phát triển mạnh mẽ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_14', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Nội dung nào sau đây phản ánh kết quả cuối cùng của phong trào cách mạng 1930 - 1931 ở Việt Nam là', 'thực dân Pháp đàn áp, phong trào thất bại.', 'phá sản các kế hoạch bình định càn quét của Pháp.', 'lật đổ được chính quyền thực dân, phong kiến.', 'duy trì được chính quyền ở Nghệ An – Hà Tĩnh.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: thực dân Pháp đàn áp, phong trào thất bại.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_16', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Trong phong trào Đông Dương đại hội năm 1936, quần chúng Đông Dương không đặt ra yêu cầu nào sau đây?', 'Thi hành luật lao động ngày làm 8 giờ.', 'Tăng giờ làm, giảm lương.', 'Trả tự do cho các tù chính trị.', 'Cải thiện đời sống của nhân dân.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Tăng giờ làm, giảm lương.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_17', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Năm 1937, Chính phủ Pháp cử Brê-vi-ê sang Đông Dương nhận chức', 'Toàn quyền Đông Dương.', 'Trưởng phái đoàn điều tra tình hình.', 'Tổng chỉ huy quân đội viễn chinh.', 'Thống sứ Pháp ở Đông Dương.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Toàn quyền Đông Dương.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_19', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Trong thời kì 1936 - 1939 Đảng Cộng sản Đông Dương đã đề hình thức và phương pháp đấu tranh nào sau đây?', 'Công khai, bí mật, bất hợp pháp, bạo lực vũ trang.', 'Đấu tranh chính trị kết hợp với đấu tranh vũ trang.', 'Sử dụng bạo lực cách mạng, bí mật, bất hợp pháp.', 'Công khai, hợp pháp kết hợp với bí mật, bất hợp pháp.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Công khai, hợp pháp kết hợp với bí mật, bất hợp pháp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_20', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Cờ đỏ búa liềm của Đảng Cộng sản Việt Nam lần đầu xuất hiện trong', 'Cách mạng tháng Tám năm 1945.', 'khởi nghĩa Yên Bái (2/1930).', 'phong trào cách mạng (1930 - 1931).', 'khởi nghĩa Nam Kì (1941).', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: phong trào cách mạng (1930 - 1931).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_21', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Phong trào dân chủ 1936 - 1939 ở Việt Nam là một bước chuẩn bị cho thắng lợi của Cách mạng tháng Tám năm 1945 vì đã', 'khắc phục triệt để hạn chế của Luận cương chính trị tháng 10/1930.', 'bước đầu xây dựng được lực lượng vũ trang nhân dân.', 'đưa Đảng Cộng sản Đông Dương ra hoạt động công khai.', 'xây dựng được một lực lượng chính trị quần chúng đông đảo.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: xây dựng được một lực lượng chính trị quần chúng đông đảo.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_24', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Nội dung nào sau đây không phản ánh ý nghĩa của phong trào dân chủ 1936 - 1939 ở Việt Nam?', 'Uy tín và ảnh hưởng của Đảng được mở rộng và thấm sâu trong nhân dân.', 'Thể hiện rõ bản chất của chính quyền cách mạng của dân do dân, vì dân.', 'Trình độ chính trị và công tác của cán bộ, đảng viên được nâng cao.', 'Đảng đã xây dựng lực lượng chính trị đông đảo ở nông thôn và thành thị.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Thể hiện rõ bản chất của chính quyền cách mạng của dân do dân, vì dân.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_25', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Nhận xét nào không phản ánh đúng về phong trào cách mạng 1930 - 1931 ở Việt Nam?', 'Sử dụng bạo lực cách mạng của quần chúng để đánh đổ đế quốc và phong kiến.', 'Quần chúng làm rung chuyển trận địa của chủ nghĩa đế quốc ở nông thôn.', 'Lực lượng chính trị, liên minh công nông được tạo ra từ trong phong trào.', 'Lực lượng du kích đã ra đời làm nhiệm vụ hỗ trợ quần chúng đấu tranh.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Lực lượng du kích đã ra đời làm nhiệm vụ hỗ trợ quần chúng đấu tranh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_26', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Nội dung sau đây phản ánh nguyên nhân quyết định dẫn đến thành công của phong trào cách mạng 1936 - 1939 ở Việt Nam?', 'Đảng đã đề ra chủ trương đấu tranh phù hợp với tình hình.', 'Sự chỉ đạo và giúp đỡ trực tiếp của Quốc tế Cộng sản.', 'Lực lượng chính trị và vũ trang được xây dựng vững mạnh.', 'Những chính sách tiến bộ của Mặt trận Nhân dân Pháp.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Đảng đã đề ra chủ trương đấu tranh phù hợp với tình hình.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_27', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Đầu năm 1930, các cuộc đấu tranh của công nhân và nông dân Việt Nam diễn ra nhằm thực hiện mục tiêu nào sau đây?', 'Đòi giảm tô, giảm sưu thuế.', 'Đòi cải thiện đời sống.', 'Ủng hộ khởi nghĩa Yên Bái.', 'Đòi tăng lương, giảm giờ làm.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Ủng hộ khởi nghĩa Yên Bái.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_28', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Cuộc đấu tranh nhân ngày 1/5/1930 trong phong trào cách mạng 1930 - 1931 ở Việt Nam có ý nghĩa như thế nào?', 'Thể hiện tình đoàn kết của nhân dân Đông Dương với vô sản thế giới.', 'Đã giải quyết được vấn đề cơ bản của một cuộc cách mạng.', 'Lật đổ được chính quyền thực dân phong kiến ở một số địa phương.', 'Thể hiện sự chuyển hướng chiến lược cách mạng của Đảng.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Thể hiện tình đoàn kết của nhân dân Đông Dương với vô sản thế giới.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_29', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Phong trào Đông Dương đại hội năm 1936 diễn ra dưới hình thức đấu tranh chủ yếu nào sau đây?', 'Bí mật, bất hợp pháp.', 'Đấu tranh vũ trang.', 'Công khai, hợp pháp.', 'Đấu tranh bạo lực.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Công khai, hợp pháp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
