INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_32', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Cao trào dân chủ 1936 - 1939 và phong trào cách mạng 1930 - 1931 ở Việt Nam không có điểm khác biệt về', 'hình thức mặt trận.', 'nhiệm vụ trước mắt.', 'nhiệm vụ chiến lược.', 'khẩu hiệu đấu tranh.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: nhiệm vụ chiến lược.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_33', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Nội dung nào là đặc điểm nổi bật của nền kinh tế Việt Nam trong những năm 1936 - 1939?', 'Phát triển mạnh nhưng hạn chế về công nghiệp, khai mỏ.', 'Có sự phục hồi và phát triển so với các thời kì trước.', 'Lâm vào tình trạng khủng hoảng, suy yếu nghiêm trọng.', 'Đã chuyển hướng phát triển theo tư bản chủ nghĩa.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Có sự phục hồi và phát triển so với các thời kì trước.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_34', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Năm 1936, lực lượng nào đã giành thắng lợi trong cuộc bầu cử và lên cầm quyền ở Pháp?', 'Đảng Dân chủ Pháp.', 'Đảng Xã hội Pháp.', 'Chủ nghĩa phát xít.', 'Mặt trận Nhân dân Pháp.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Mặt trận Nhân dân Pháp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_35', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Phong trào cách mạng 1930 - 1931 ở Việt Nam mang tính chất triệt để vì', 'đã tấn công trực diện vào hai kẻ thù chính của cách mạng.', 'buộc chính quyền thực dân ban hành các chính sách tiến bộ.', 'đã khẳng định được vai trò lãnh đạo của Đảng Cộng sản.', 'đã xây dựng được khối liên minh công - nông vững chắc.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: đã tấn công trực diện vào hai kẻ thù chính của cách mạng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_36', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Phong trào cách mạng 1930 - 1931 của nhân dân Việt Nam giành được kết quả cao nhất nào sau đây?', 'Thành lập được chính quyền kiểu mới.', 'Đặt cơ sở cho sự ra đời mặt trận thống nhất.', 'Mang lại ruộng đất cho toàn thể nhân dân.', 'Lôi cuốn đông đảo quần chúng nhân dân đi theo.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Thành lập được chính quyền kiểu mới.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_37', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Cuộc vận động dân chủ 1936 - 1939 ở Việt Nam không có phong trào đấu tranh nào sau đây?', 'Phong trào phá kho thóc, giải quyết nạn đói.', 'Phong trào đấu tranh nghị trường.', 'Phong trào đấu tranh báo chí.', 'Phong trào đấu tranh đòi tự do, dân sinh, dân chủ.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Phong trào phá kho thóc, giải quyết nạn đói.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_41', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Nhận xét nào sau đây phản ánh đúng về phong trào cách mạng 1930 - 1931?', 'Không ảo tưởng vào kẻ thù của dân tộc và giai cấp.', 'Không đề nhiệm vụ dân chủ để giành quyền lợi.', 'Có sự đấu tranh để lựa chọn khuynh hướng phát triển.', 'Lần đầu tiên xuất hiện hình thức đấu tranh nghị trường.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Không ảo tưởng vào kẻ thù của dân tộc và giai cấp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
