INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B07_52', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B07'), 'LS9_KNTT_B07', 'Nội dung nào sau đây là ý nghĩa quan trọng của cao trào dân chủ 1936 - 1939 ở Việt Nam?', 'Đánh dấu quá trình chuyển hướng chiến lược cách mạng của Đảng.', 'Hoàn thành thắng lợi mục tiêu đề ra từ Đại hội VI của Quốc tế Cộng sản.', 'Tập hợp được đội quân chính trị đông đảo từ thành thị đến nông thôn.', 'Là cuộc diễn tập trực tiếp chuẩn bị cho Cách mạng tháng Tám năm 1945.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Tập hợp được đội quân chính trị đông đảo từ thành thị đến nông thôn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
