INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B08_66', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B08'), 'LS9_KNTT_B08', 'Nhà nước Việt Nam Dân chủ Cộng hoà được thành lập năm 1945 là nhà nước của', 'Xô viết đại biểu của công - nông.', 'công nhân, nông dân, binh lính.', 'toàn thể nhân dân Việt Nam.', 'liên hiệp kháng chiến chống Pháp.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: toàn thể nhân dân Việt Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B08_67', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B08'), 'LS9_KNTT_B08', 'Nội dung nào sau đây không phải là quyết dịnh của Hội nghị Ban Chấp hành Trung ương Đảng lần thứ 8 (5/1941)?', 'Xác định kẻ thù của cách mạng là Pháp - Nhật.', 'Xác định hình thái của cuộc cách mạng.', 'Nhiệm vụ chủ yếu là giải phóng dân tộc.', 'Thông qua chính sách đối nội và đối ngoại.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Thông qua chính sách đối nội và đối ngoại.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B08_68', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B08'), 'LS9_KNTT_B08', 'Sự kiện nào tạo nên cuộc khủng hoảng chính trị sâu sắc ở Đông Dương tháng 3 năm 1945?', 'Nhật đảo chính Pháp độc chiếm Đông Dương.', 'Ba nước ở Đông Nam Á giành độc lập dân tộc.', 'Pháp ráo riết chuẩn bị lực lượng phản công Nhật.', 'Nhật đầu hàng quân Đồng minh vô điều kiện.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Nhật đảo chính Pháp độc chiếm Đông Dương.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B08_70', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B08'), 'LS9_KNTT_B08', 'Trong Cách mạng tháng Tám năm 1945, khởi nghĩa tại các đô thị thắng lợi có ý nghĩa quyết định nhất vì đây là nơi', 'có nhiều căn cứ địa cách mạng của Việt Nam.', 'có đông đảo quần chúng giác ngộ cách mạng.', 'đặt cơ quan đầu não chỉ huy của lực lượng cách mạng.', 'tập trung các trung tâm kinh tế, chính trị của kẻ thù.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: tập trung các trung tâm kinh tế, chính trị của kẻ thù.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B08_74', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B08'), 'LS9_KNTT_B08', 'Tháng 12/1944, Đội Việt Nam Tuyên truyền Giải phóng quân đã giành thắng lợi đầu tiên ở', 'Phay Khắt và Nà Ngần.', 'Phay Khắt và Pác Pó.', 'Pắc Nặm và Na Rì.', 'Nà Ngần và Ngân Sơn.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Nà Ngần và Ngân Sơn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B08_76', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B08'), 'LS9_KNTT_B08', 'Đội Việt Nam Tuyên truyền Giải phóng quân được thành lập năm 1944 với nhiệm vụ trọng tâm nào sau đây?', 'Tiến hành khởi nghĩa từng phần ở các căn cứ địa.', 'Tuyên truyền, chính trị kết hợp với đấu tranh quân sự.', 'Xây dựng lực lượng chính trị đông đảo ở Việt Bắc.', 'Khởi nghĩa vũ trang giành chính quyền trong cả nước.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Tuyên truyền, chính trị kết hợp với đấu tranh quân sự.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B08_77', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B08'), 'LS9_KNTT_B08', 'Hội nghị Trung ương Đảng (11/1939) đã đánh dấu sự chuyển hướng đúng đắn về chiến lược cách mạng vì', 'đặt vấn đề dân tộc cho ba nước Đông Dương.', 'giải quyết kịp thời vấn đề ruộng đất cho nông dân.', 'xác định kẻ thù chủ yếu trước mắt là quân phiệt Nhật.', 'đã giương cao ngọn cờ giải phóng dân tộc.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: đã giương cao ngọn cờ giải phóng dân tộc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B08_78', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B08'), 'LS9_KNTT_B08', 'Nguyễn Ái Quốc chọn địa phương nào sau đây là nơi thí điểm xây dựng các đoàn thể quần chúng trong Mặt trận Việt Minh?', 'Thái Nguyên.', 'Tuyên Quang.', 'Lạng Sơn.', 'Cao Bằng.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Cao Bằng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B08_79', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B08'), 'LS9_KNTT_B08', 'Nội dung nào là căn cứ để xác định tính chất dân tộc của Cách mạng tháng Tám năm 1945 ở Việt Nam?', 'Đi từ khởi nghĩa từng phần tiến tới tổng khởi nghĩa.', 'Thành lập chính quyền nhà nước của toàn thể nhân dân.', 'Diễn ra có sự kết hợp hài hoà giữa nông thôn và thành thị.', 'Giải quyết một phần quyền lợi về ruộng đất của nông dân.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Thành lập chính quyền nhà nước của toàn thể nhân dân.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B08_80', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B08'), 'LS9_KNTT_B08', 'Pháp chấp nhận làm tay sai cho Nhật, cùng Nhật thống trị Đông Dương (9/1940 - 3/1945) vì', 'Phe phát xít đang mở rộng chiến tranh ra toàn thế giới.', 'thực dân Pháp đã suy yếu, không đủ sức chống lại Nhật.', 'Pháp muốn mượn tay Nhật đàn áp cách mạng Việt Nam.', 'Tránh mũi nhọn đấu tranh của nhân dân Đông Dương.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: thực dân Pháp đã suy yếu, không đủ sức chống lại Nhật.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B08_81', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B08'), 'LS9_KNTT_B08', 'Thủ đô của Khu Giải phóng Việt Bắc thành lập tháng 6 năm 1945 là', 'Chiêm Hóa (Tuyên Quang).', 'Tân Trào (Tuyên Quang).', 'Pác Pó (Cao Bằng).', 'Định Hóa (Thái Nguyên).', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Tân Trào (Tuyên Quang).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B08_82', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B08'), 'LS9_KNTT_B08', 'Trong Chiến tranh thế giới thứ hai, Nhật xâm lược Đông Dương (9/1940) nhằm mục đích cơ bản nào sau đây?', 'Biến Đông Dương thành thuộc địa và căn cứ quân sự.', 'Đặt Đông Dương dưới ô bảo trợ hạt nhân của Nhật.', 'Độc chiếm Đông Dương và các nước Đông Nam Á.', 'Chia đôi hệ thống thuộc địa của đế quốc Âu - Mỹ.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Biến Đông Dương thành thuộc địa và căn cứ quân sự.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_01', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Nội dung nào sau đây phản ánh tác động của Chiến tranh lạnh đến quan hệ quốc tế sau Chiến tranh thế giới thứ hai?', 'Dẫn tới sự hình thành trật tự thế giới đa cực.', 'Đưa các quốc gia khu vực xích lại gần nhau hơn.', 'Làm cho quan hệ quốc tế căng thẳng, phức tạp.', 'Làm cho kinh tế của cả Mĩ và Liên Xô suy giảm.', 3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Làm cho quan hệ quốc tế căng thẳng, phức tạp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_02', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Hội đồng tương trợ kinh tế (SEV) ra đời năm 1949 nhằm thực hiện mục tiêu nào sau đây?', 'Đẩy mạnh chương trình tư nhân hóa xí nghiệp nhà nước', 'Thúc đẩy sự phát triển xu thế toàn cầu hóa trên thế giới.', 'Tăng cường sự hợp tác giữa các nước xã hội chủ nghĩa.', 'Thúc đẩy sự tiến bộ vượt bậc về quân sự của các nước.', 3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Tăng cường sự hợp tác giữa các nước xã hội chủ nghĩa.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_03', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Chiến tranh lạnh chấm dứt năm 1989 đã có tác động nào sau đây đến tình hình thế giới?', 'Phạm vi ảnh hưởng của Mỹ và Liên Xô ngày càng bị thu hẹp.', 'Chấm dứt hoàn toàn các cuộc nội chiến xung đột trên toàn thế giới.', 'Nhiều tranh chấp, xung đột được giải quyết bằng biện pháp hòa bình.', 'Nền kinh tế Tây Âu và Nhật Bản không ngừng phát triển.', 3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Nhiều tranh chấp, xung đột được giải quyết bằng biện pháp hòa bình.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_05', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Nhân tố chủ yếu nào chi phối quan hệ quốc tế trong phần lớn nửa sau thế kỉ XX?', 'Liên minh châu Âu (EU).', 'Xu thế toàn cầu hóa.', 'Sự ra đời của NATO và Vác-sa-va.', 'Cục diện “Chiến tranh lạnh”.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Cục diện “Chiến tranh lạnh”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_06', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Sự kiện nào là “sản phẩm” của Chiến tranh lạnh và là cuộc đụng đầu trực tiếp đầu tiên giữa hai phe?', 'Cuộc chiến tranh Triều Tiên (1950 - 1953).', 'Cuộc chiến tranh xâm lược Đông Dương của Pháp (1945 - 1954).', 'Cuộc chiến tranh xâm lược Việt Nam của Mỹ (1954 - 1975).', 'Cuộc nội chiến ở Campuchia (1979 - 1991).', 1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: Cuộc chiến tranh Triều Tiên (1950 - 1953).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_07', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Để thực hiện Chiến tranh lạnh, Mỹ và Liên Xô đều', 'thiết lập được chủ quyền trên Mặt trăng.', 'chế tạo thành công bom nguyên tử.', 'tham gia vào chiến tranh ở khu vực châu Mỹ.', 'ban hành hiệp ước cấm vũ khí hạt nhân.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: chế tạo thành công bom nguyên tử.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_08', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Sự ra đời của tổ chức NATO và Vác-sa-va có tác động nào đến quan hệ quốc tế sau Chiến tranh thế giới thứ hai?', 'Đánh dấu sự phát triển vượt bậc của Mỹ và Liên Xô về quân sự.', 'Đánh dấu sự xác lập của cục diện hai cực, hai phe.', 'Mở màn cho sự xác lập của các tổ chức quân sự trên thế giới.', 'Chấm dứt mối quan hệ Đồng minh giữa Liên Xô và Mỹ.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Đánh dấu sự xác lập của cục diện hai cực, hai phe.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_09', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Nội dung nào sau đây phản ánh sự thay đổi quan hệ giữa Mỹ và Liên Xô Sau Chiến tranh thế giới thứ hai?', 'Từ liên minh chống phát xít chuyển sang đối đầu gay gắt.', 'Hợp tác chặt chẽ để tiêu diệt chủ nghĩa khủng bố trên thế giới.', 'Chuyển từ đối đầu căng thẳng sang đối thoại, hoà hoãn.', 'Hợp tác cùng nhau giải quyết nhiều vấn đề quốc tế lớn.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Từ liên minh chống phát xít chuyển sang đối đầu gay gắt.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_10', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Nội dung nào sau đây phản ánh đúng hành động của Liên Xô đối với bán đảo Triều Tiên trong thời kỳ Chiến tranh lạnh?', 'Viện trợ và trực tiếp tham gia vào cuộc chiến tranh với Hàn Quốc.', 'Xây dựng chính quyền mới thân Liên Xô ở miền Bắc Triều Tiên.', 'Đưa tên lửa hạt nhân và bom nguyên tử vào sử dụng ở Hàn Quốc.', 'Phản đối quá trình phi hạt nhân hóa trên bán đảo Triều Tiên.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Viện trợ và trực tiếp tham gia vào cuộc chiến tranh với Hàn Quốc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_11', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Nội dung nào sau đây phản ánh đúng chính sách của Liên Xô đối với Cuba trong thời kỳ Chiến tranh lạnh?', 'Thiết lập các căn cứ quân sự và căn cứ hải quân ở Cuba.', 'Giúp Cuba chế tạo tên lửa hạt nhân để đối trọng với Mỹ.', 'Tiến hành phi quân sự hóa để tập trung phát triển kinh tế.', 'Đưa quân đội thường trực và tên lửa hạt nhân vào Cuba.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Đưa quân đội thường trực và tên lửa hạt nhân vào Cuba.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_12', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Tháng 6 năm 1947, Mỹ đề ra kế hoạch Mácsan không nhằm mục đích nào?', 'Tạo nên sự đối lập về kinh tế và chính trị giữa các nước Tây Âu và Đông Âu.', 'Khống chế và nô dịch các nước đồng minh của Mỹ ở Tây Âu.', 'Thành lập liên minh quân sự chống lại Liên Xô và các nước Đông Âu.', 'Giúp các nước Tây Âu phục hồi nền kinh tế bị tàn phá sau chiến tranh.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Tạo nên sự đối lập về kinh tế và chính trị giữa các nước Tây Âu và Đông Âu.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_13', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Nội dung nào sau đây phản ánh chính sách của Mỹ đối với Cuba trong thời kỳ Chiến tranh lạnh?', 'Thực hiện phong tỏa hải quân đối với Cuba.', 'Yêu cầu Cuba phải tiến hành cải cách dân chủ.', 'Cấm Cuba được phổ biến vũ khí hạt nhân.', 'Cấm Cuba tham gia vào tổ chức Liên hợp quốc.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Thực hiện phong tỏa hải quân đối với Cuba.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_14', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Năm 1949, Liên Xô chế tạo thành công bom nguyên tử là biểu hiện của', 'xu thế toàn cầu hóa trên thế giới.', 'cuộc chạy đua vũ trang đối với Mỹ.', 'việc phổ biến vũ khí hạt nhân trên thế giới.', 'cuộc cách mạng xanh trong quân sự.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: cuộc chạy đua vũ trang đối với Mỹ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_15', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Trong thời kỳ Chiến tranh lạnh, nước Đức trở thành một tâm điểm đối đầu ở châu Âu giữa hai cực Xô - Mỹ?', 'Đức là thành trì của chủ nghĩa phát xít trước Chiến tranh thế giới thứ hai.', 'Nước Đức có chung đường biên giới với Liên Xô và các nước Bắc Âu.', 'Nước Đức đã hình thành hai nhà nước đối lập ở hai miền Đông -Tây.', 'Đức là nơi đặt trụ sở của khối Hiệp ước Bắc Đại Tây Dương (NATO).', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Nước Đức đã hình thành hai nhà nước đối lập ở hai miền Đông -Tây.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_16', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Sự kiện nào sau đây đánh dấu Chiến tranh lạnh chấm dứt sau hơn 40 tồn tại?', 'Tổ chức Vác-sa-va và SEV lần lượt giải thể.', 'Xô - Mĩ kí Hiệp ước về việc hạn chế vũ khí chiến lược.', 'Cuộc gặp gỡ Xô - Mỹ tại đảo Man- ta (12/1989).', 'Xô - Mỹ kí Hiệp ước về hạn chế phòng chống tên lửa.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Cuộc gặp gỡ Xô - Mỹ tại đảo Man- ta (12/1989).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_17', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Thông điệp của Tổng thống Truman tại Quốc hội Mỹ (3/1947) đã', 'tạo nên sự đối lập giữa các nước Đông Âu và Tây Âu.', 'ngăn chặn quá trình mở rộng của chủ nghĩa xã hội.', 'mở đầu việc xác lập trật tự hai cực trên thế giới.', 'củng cố hơn nữa mối quan hệ giữa Mỹ và Tây Âu.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: củng cố hơn nữa mối quan hệ giữa Mỹ và Tây Âu.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_18', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Chiến tranh lạnh chấm dứt tác động như thế nào đến tình hình các nước Đông Nam Á cuối thế kỉ XX?', 'Tạo điều kiện cho sự ra đời và phát triển của tổ chức ASEAN.', 'Làm hòa dịu quan hệ giữa ASEAN và các nước Đông Dương.', 'Làn sóng xã hội chủ nghĩa lan rộng ở Đông Nam Á.', 'Thúc đẩy phong trào giải phóng dân tộc phát triển mạnh.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Làm hòa dịu quan hệ giữa ASEAN và các nước Đông Dương.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_19', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Nội dung nào phản ánh đúng kết quả sự đối đầu căng thẳng giữa Mỹ và Liên Xô sau Chiến tranh thế giới thứ hai?', 'Dẫn đến những cuộc xung đột quân sự trực tiếp.', 'Dẫn đến cuộc chiến tranh thế giới mới.', 'Chuyển dần sang hòa bình, đối thoại, cùng phát triển.', 'Trở thành Đồng minh thân cận với nhau.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Chuyển dần sang hòa bình, đối thoại, cùng phát triển.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B09_20', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B09'), 'LS9_KNTT_B09', 'Mâu thuẫn gay gắt, quyết liệt giữa các nước lớn sau Chiến tranh thế giới thứ hai thực chất là sự mâu thuẫn về', 'tham vọng bá chủ thế giới.', 'những quyền lợi kinh tế khác nhau.', 'hệ tư tưởng chính trị khác nhau.', 'thành quả thắng lợi sau chiến tranh.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: hệ tư tưởng chính trị khác nhau.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_01', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Nội dung nào sau đây không phản ánh đúng tình hình xã hội của Đông Âu những năm 70,80 của thế kỷ XX?', 'Nhân dân phản đối chế độ đa nguyên, đa đảng.', 'Niềm tin của nhân dân vào chủ nghĩa xã hội giảm sút.', 'Tình trạng bất bình trong xã hội có sự gia tăng.', 'Đời sống của các tầng lớp nhân dân khó khăn.', 1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: Nhân dân phản đối chế độ đa nguyên, đa đảng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_03', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Chủ nghĩa xã hội ở Liên Xô và Đông Âu sụp đổ hoàn toàn năm 1991 chứng tỏ', 'hệ thống xã hội chủ nghĩa thế giới không còn tồn tại.', 'chiến lược toàn cầu bá chủ thế giới của Mĩ đã thành công.', 'hệ thống xã hội chủ nghĩa chỉ còn lại ở châu Á và châu Mĩ.', 'Liên Xô không đứng đầu phe xã hội chủ nghĩa ở châu Âu.', 1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: hệ thống xã hội chủ nghĩa thế giới không còn tồn tại.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_04', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Bài học kinh nghiệm cho Việt Nam từ sự sụp đổ của chủ nghĩa xã hội ở Liên Xô và Đông Âu là', 'tăng cường cải cách dân chủ trên mọi lĩnh vực.', 'tăng cường sự viện trợ và giúp đỡ của nước ngoài.', 'phải duy trì được mối liên hệ với các cường quốc.', 'phải giữ vững vai trò lãnh đạo của Đảng Cộng sản.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: phải giữ vững vai trò lãnh đạo của Đảng Cộng sản.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_05', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Nội dung nào sau đây phản ánh chính sách tích cực về giáo dục của Liên Xô sau Chiến tranh thế giới thứ hai?', 'Thực hiện chế độ giáo dục miễn phí.', 'Thành lập cơ sở giáo dục ở thuộc địa.', 'Tiến hành phổ cập giáo dục đại học.', 'Phát động phong trào Bình dân học vụ.', 1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: Thực hiện chế độ giáo dục miễn phí.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_06', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Sau khi Nhà nước dân chủ nhân dân ra đời, ở các nước Đông Âu, công nhân, nông dân, trí thức đã', 'thống trị các giai cấp trong xã hội.', 'quốc hữu hóa xí nghiệp của tư sản.', 'không được hưởng các quyền lợi.', 'trở thành người làm chủ đất nước.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: trở thành người làm chủ đất nước.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_07', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Ngày 21/12/1991, ở châu Âu, 11 nước cộng hòa kí hiệp định thành lập các quốc gia độc lập (SNG) chứng tỏ điều gì?', 'Sự đoàn kết giữa Liên Xô và Đông Âu có chuyển biến mới', 'Nhà nước Liên bang Cộng hòa XHCN không còn tồn tại.', 'Hiến pháp mới của Liên bang Nga là đúng đắn, phù hợp.', 'Sự đối đầu giữa Mỹ và Liên Xô đã sụp đổ hoàn toàn.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Nhà nước Liên bang Cộng hòa XHCN không còn tồn tại.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_08', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Trong công cuộc xây dựng chủ nghĩa xã hội, lĩnh vực kinh tế phát triển mạnh mẽ nhất của Liên Xô là', 'thủ công nghiệp.', 'công nghiệp.', 'thương nghiệp.', 'nông nghiệp.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: công nghiệp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_09', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Nội dung nào thể hiện vị thế công nghiệp của Liên Xô từ những năm 1950 đến nửa đầu những năm 70 của thế kỉ XX?', 'Cường quốc nông nghiệp thứ hai thế giới sau Mỹ.', 'Cường quốc công nghiệp thứ hai thế giới sau Mỹ.', 'Siêu cường kinh tế - tài chính lớn nhất thế giới.', 'Trở thành trung tâm kinh tế - tài chính lớn của thế giới.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Cường quốc công nghiệp thứ hai thế giới sau Mỹ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_10', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Nội dung nào là thành tựu lớn nhất về mặt quân sự của Liên Xô từ những năm 50 đến những năm 70 của thế kỉ XX?', 'Đạt thế cân bằng về sức mạnh quân sự với Mĩ.', 'Làm tan rã các liên minh quân sự của Mĩ trên thế giới.', 'Ký hiệp ước hạn chế vũ khí tiến công chiến lược.', 'Phá vỡ thế độc quyền về vũ khí nguyên tử của Mĩ.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Đạt thế cân bằng về sức mạnh quân sự với Mĩ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_11', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Trong nền chính trị từ năm 1945 đến năm 1973, Liên Xô đã', 'cho các đảng tự do ra tranh cử và nắm quyền.', 'xóa bỏ các tổ chức chính trị - xã hội trước đó.', 'tiến hành nhiều cuộc cải cách về thể chế.', 'tăng cường vai trò lãnh đạo của nhà nước.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: tăng cường vai trò lãnh đạo của nhà nước.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_13', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Sau Chiến tranh thế giới thứ hai, Liên Xô đã thực hiện chính sách kinh tế nào sau đây?', 'Thực hiện dân chủ hóa tuyệt đối trong lao động.', 'Xây dựng nền kinh tế hàng hóa nhiều thành phần.', 'Xây dựng nền kinh tế theo cơ chế thị trường.', 'Thực hiện cơ chế tập trung quan liêu bao cấp.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Thực hiện cơ chế tập trung quan liêu bao cấp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_14', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Trước Chiến tranh thế giới thứ hai, các nước Đông Âu lệ thuộc vào quốc gia nào sau đây?', 'Các nước Nam Âu.', 'Các nước Bắc Âu.', 'Các nước Tây Âu.', 'Mĩ, Liên Xô, Nhật Bản.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Các nước Tây Âu.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_16', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Vị tổng thống đầu tiên của Liên bang cộng hòa xã hội chủ nghĩa Xô viết (1922- 1991) là', 'Pu-tin.', 'En-xin.', 'Xta-lin.', 'Goóc-ba-chốp', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Goóc-ba-chốp') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_18', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Từ năm 1945 đến năm 1973, các nước Đông Âu đã đạt được thành tựu văn hóa tiêu biểu nào sau đây?', 'Xóa bỏ được nạn mù chữ.', 'Xây dựng nền văn hóa số.', 'Ngăn chặn du nhập văn hóa.', 'Phổ cập trung học phổ thông.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Xóa bỏ được nạn mù chữ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_19', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Năm 1949, Liên Xô và các nước Đông Âu thành lập Hội đồng tương trợ kinh tế (SEV) nhằm mục đích nào sau đây?', 'Viện trợ không hoàn lại cho các nước Đông Âu phát triển kinh tế.', 'Đạt được thế cân bằng về sức mạnh quân sự đối với các nước Tây Âu.', 'Tăng cường sự hợp tác giữa các nước xã hội chủ nghĩa ở châu Âu.', 'Tăng cường chạy đua vũ trang với các nước tư bản chủ nghĩa.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Tăng cường sự hợp tác giữa các nước xã hội chủ nghĩa ở châu Âu.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_21', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Nguyên nhân nào sau đây quyết định sự thành công của Liên Xô trong việc thực hiện kế hoạch 5 năm (1946 - 1950)?', 'Áp dụng những thành tựu của cách mạng khoa học – kĩ thuật.', 'Liên Xô thu nhiều lợi nhuận trong chiến tranh thế giới hai.', 'Lãnh thổ rộng lớn, tài nguyên phong phú, lao động dồi dào.', 'Tinh thần hăng hái lao động sản xuất của nhân dân Liên Xô.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Tinh thần hăng hái lao động sản xuất của nhân dân Liên Xô.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_22', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Sự sụp đổ của chủ nghĩa xã hội ở Liên Xô và Đông Âu có tác động nào sau đây?', 'Chủ nghĩa tư bản nắm quyền thống trị thế giới.', 'Làm cho trật tự hai cực Ianta hoàn toàn sụp đổ.', 'Chủ nghĩa xã hội sụp đổ hoàn toàn trên thế giới.', 'Mĩ và Liên Xô tuyên bố chấm dứt Chiến tranh lạnh.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Làm cho trật tự hai cực Ianta hoàn toàn sụp đổ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_23', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Nguyên nhân khách quan nào sau đây làm cho chế độ xã hội chủ nghĩa ở Liên Xô và Đông Âu khủng hoảng và sụp đổ?', 'Phong trào li khai diễn ra mạnh mẽ gây nhiều bất ổn chính trị.', 'Tổ chức Hiệp ước Vác-sa-va không phát huy được vai trò.', 'Đảng Cộng sản ở Liên Xô và Đông Âu bị đình chỉ hoạt động.', 'Hoạt động chống phá của các thế lực thù địch trong và ngoài nước.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Hoạt động chống phá của các thế lực thù địch trong và ngoài nước.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_24', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Lực lượng xã hội đông đảo nhất ở Liên Xô năm 1971 là', 'công nhân.', 'trí thức.', 'tiểu tư sản.', 'nông dân.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: công nhân.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_25', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Với chiến thắng chủ nghĩa phát xít và các lực lượng phản động, Liên Xô đã', 'hoàn thành phong trào cách mạng trên thế giới.', 'bảo vệ được cơ sở vật chất của chủ nghĩa xã hội.', 'bảo vệ được chế độ chính trị xã hội tiến bộ của mình.', 'xóa bỏ được những bất bình đẳng trong xã hội.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: bảo vệ được chế độ chính trị xã hội tiến bộ của mình.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_27', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Những ấn phẩm văn hóa của Liên Xô và Đông Âu trong những năm 80 của thế kỷ XX có nội dung nào sau đây?', 'Tuyên truyền lý tưởng của chủ nghĩa Mác - Lênin.', 'Chống việc hình thành chế độ đa nguyên, đa đảng.', 'Phổ biến lý luận của cách mạng xã hội chủ nghĩa.', 'Chống chủ nghĩa xã hội, tuyên truyền chế độ đa nguyên.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Chống chủ nghĩa xã hội, tuyên truyền chế độ đa nguyên.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_28', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Trong những năm chủ nghĩa xã hội ở Liên Xô và Đông Âu lâm vào khủng hoảng, Đảng và Nhà nước Việt Nam khẳng định', 'Việt Nam chịu tác động lớn nên cần phải đổi mới đất nước.', 'Việt Nam không chịu tác động từ cuộc khủng hoảng ở Liên Xô.', 'Việt Nam cần tăng cường viện trợ cho Liên Xô và Đông Âu.', 'mô hình chủ nghĩa xã hội chỉ phù hợp ở châu Á và Mĩ La-tinh.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Việt Nam chịu tác động lớn nên cần phải đổi mới đất nước.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_29', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Nội dung nào sau đây thể hiện tính ưu việt của chủ nghĩa xã hội ở Liên Xô từ năm 1945 đến năm 1973?', 'Đô thị hóa tất cả các vùng nông thôn.', 'Thực hiện chế độ giáo dục miễn phí.', 'Thực hiện cơ chế tập trung bao cấp.', 'Thực hiện chế độ khám bệnh miễn phí.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Thực hiện chế độ giáo dục miễn phí.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_30', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Trong những năm 80 của thế kỷ XX, cuộc cải tổ của Liên Xô đã', 'giải quyết được xung đột sắc tộc, tôn giáo.', 'xóa bỏ được nền chính trị chuyên chế.', 'xác lập hệ thống chính quyền tổng thống.', 'hình thành chế độ đa đảng, nhất nguyên.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: xác lập hệ thống chính quyền tổng thống.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_31', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Sau Chiến tranh thế giới thứ hai, Liên Xô đã', 'thực hiện dân chủ hóa hệ thống chính trị.', 'ban hành hiến pháp để sửa đổi chế độ.', 'duy trì các cơ quan lập ra trong thời chiến.', 'thành lập chính phủ kháng chiến mới.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: thực hiện dân chủ hóa hệ thống chính trị.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_32', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Sự hợp tác tương trợ về kinh tế giữa Liên Xô và Đông Âu được tăng cường sau sự kiện nào?', 'Tổ chức Hiệp ước Vác-sa-va ra đời năm 1955.', 'Đông Âu trở thành Đồng minh thân cận của Liên Xô.', 'Hội đồng tương trợ kinh tế (SEV) thành lập năm 1949.', 'Liên Xô viện trợ không hoàn lại cho các nước Đông Âu.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Hội đồng tương trợ kinh tế (SEV) thành lập năm 1949.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_34', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Nội dung nào sau đây phản ánh đúng tình hình kinh tế của Liên Xô trong những năm 1989 - 1991?', 'Cuộc cải tổ đã xây dựng được nền kinh tế thị trường.', 'Khôi phục được thành tựu kinh tế trước khủng hoảng.', 'Khan hiếm lương thực, thực phẩm và hàng tiêu dùng.', 'Thành phần kinh tế nhà nước giữa vai trò độc quyền.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Khan hiếm lương thực, thực phẩm và hàng tiêu dùng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_35', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Nguyên nhân chủ yếu nào dẫn đến sự sụp đổ CNXH ở Liên Xô và Đông Âu cuối thế kỉ XX?', 'Sự chống phá của các thế lực thù địch ở trong và ngoài nước.', 'Khi cải tổ phạm phải nhiều sai lầm, làm cho khủng hoảng trầm trọng.', 'Đường lối lãnh đạo mang tính chủ quan, quan liêu, bao cấp.', 'Không bắt kịp bước phát triển của khoa học kĩ thuật tiên tiến.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Khi cải tổ phạm phải nhiều sai lầm, làm cho khủng hoảng trầm trọng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_37', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Chính sách đối ngoại của Liên Xô từ năm 1950 đến đầu những năm 70 của thế kỉ XX không có nội dung nào dưới đây?', 'Bảo vệ hòa bình an ninh thế giới.', 'Ngả về các nước tư bản phương Tây.', 'Giúp đỡ các nước xã hội chủ nghĩa.', 'Ủng hộ phong trào giải phóng dân tộc.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Ngả về các nước tư bản phương Tây.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_38', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Trong quá trình xây dựng chủ nghĩa xã hội (1950 -1973), các nước Đông Âu đã', 'tiến hành thành công cuộc cách mạng chất xám.', 'thoát khỏi tình trạng nghèo nàn lạc hậu.', 'có tốc độ tăng trưởng nhanh nhất thế giới.', 'có sản lượng nông nghiệp hàng đầu thế giới.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: thoát khỏi tình trạng nghèo nàn lạc hậu.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_39', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Nội dung nào sau đây phản ánh đúng tình hình xã hội của các nước Đông Âu từ năm 1950 đến những năm 1970?', 'Tình trạng thất nghiệp kéo dài.', 'Giai cấp bóc lột bị xóa bỏ.', 'Niềm tin của nhân dân suy giảm.', 'Thu nhập quốc dân giảm sút.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Giai cấp bóc lột bị xóa bỏ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_40', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Sau Chiến tranh thế giới thứ hai, Liên Xô vượt Mỹ trong các lĩnh vực nào sau đây?', 'Công nghiệp dân dụng và ứng dụng.', 'Chế tạo vũ khí hiện đại.', 'Công nghiệp nặng.', 'Công nghiệp vũ trụ và điện hạt nhân.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Công nghiệp vũ trụ và điện hạt nhân.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B10_41', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B10'), 'LS9_KNTT_B10', 'Năm năm đầu sau Chiến tranh thế giới thứ hai, nội dung nào sau đây là nhiệm vụ trọng tâm của Liên Xô?', 'Khôi phục kinh tế, hàn gắn vết thương sau chiến tranh.', 'Xây dựng cơ sở vật chất kĩ thuật của chủ nghĩa xã hội.', 'Mở rộng quan hệ kinh tế đối ngoại với các nước lớn.', 'Tiêu diệt chủ nghĩa phát xít, bảo vệ hòa bình thế giới.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Khôi phục kinh tế, hàn gắn vết thương sau chiến tranh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B11_01', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B11'), 'LS9_KNTT_B11', 'Để thực hiện mục tiêu ngăn chặn đẩy lùi chủ nghĩa xã hội sau Chiến tranh thế giới thứ hai, Mỹ đã', 'đưa ra khẩu hiệu “thúc đẩy dân chủ”.', 'can thiệp vào khu vực Trung Đông.', 'phát động cuộc Chiến tranh lạnh.', 'biến Mỹ Latinh thành sâu sau.', 3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: phát động cuộc Chiến tranh lạnh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B11_02', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B11'), 'LS9_KNTT_B11', 'Theo quy định của Hiến pháp Mỹ, hai đảng nào thay nhau lên nắm chính quyền?', 'Đảng Tự do và Đảng Bảo thủ.', 'Đảng Cộng sản và Đảng Xã hội.', 'Đảng Cộng hòa và Đảng Xã hội.', 'Đảng Dân chủ và Đảng Cộng hòa.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Đảng Dân chủ và Đảng Cộng hòa.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B11_03', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B11'), 'LS9_KNTT_B11', 'Từ những năm 1950 đến năm 1991, nền kinh tế Mỹ không còn chiếm ưu thế tuyệt đối vì', 'sự vươn lên của các nước Tây Âu và Nhật Bản.', 'những cuộc đấu tranh của giai cấp công nhân.', 'đồng Đôla ngày càng có sự suy giảm về giá trị.', 'chính quyền không tổ chức cải cách, đổi mới.', 1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: sự vươn lên của các nước Tây Âu và Nhật Bản.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
