INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B11_10', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B11'), 'LS9_KNTT_B11', 'Sau Chiến tranh thế giới thứ hai, để thực hiện chiến lược toàn cầu, Mỹ đã', 'lôi kéo các nước nhận viện trợ.', 'đầu tư cho khoa học - công nghệ.', 'giải quyết các vấn đề lớn của thế giới.', 'viện trợ vô điều kiện cho các nước.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: lôi kéo các nước nhận viện trợ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
