INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_18', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Cuộc đấu tranh giành độc lập của Việt Nam, Lào, Inđônêxia năm 1945 có ý nghĩa quốc tế như thế nào?', 'Cổ vũ phong trào giải phóng dân tộc trên thế giới.', 'Làm chủ nghĩa xã hội trở thành hệ thống thế giới.', 'Làm xói mòn trật tự Ianta và Chiến tranh lạnh.', 'Góp phần giải trừ chủ nghĩa thực dân trên thế giới.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Góp phần giải trừ chủ nghĩa thực dân trên thế giới.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
