INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_20', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Trong quá trình xây dựng chủ nghĩa xã hội, Cuba đã', 'xóa bỏ nền nông nghiệp đa canh.', 'chú trọng đến độc canh (cây mía).', 'xây dựng nền nông nghiệp đơn nhất.', 'xóa bỏ nền nông nghiệp độc canh.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: xóa bỏ nền nông nghiệp độc canh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_21', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Kinh tế hướng nội của 5 nước sáng lập ASEAN có mục tiêu nào sau đây?', 'Thu hút vốn đầu tư xuất khẩu ra thị trường bên ngoài.', 'Phát triển công nghiệp tiêu dùng để hướng xuất khẩu.', 'Mở cửa kinh tế thu hút vốn đầu tư và kĩ thuật bên ngoài.', 'Xóa bỏ nghèo nàn, lạc hậu, xây dựng nền kinh tế tự chủ.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Xóa bỏ nghèo nàn, lạc hậu, xây dựng nền kinh tế tự chủ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
