INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_23', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Từ năm 1955, để nâng cao vị thế quốc tế của mình, Nhật Bản đã', 'đa dạng hóa quan hệ đối ngoại.', 'tham gia vào chiến tranh của Mỹ.', 'ban hành những Hiến pháp mới.', 'tiến hành cuộc cải cách dân chủ.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: đa dạng hóa quan hệ đối ngoại.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_24', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Nội dung nào sau đây phản ánh nguyên tắc hoạt động của tổ chức ASEAN?', 'Tiến hành hợp tác quốc tế bằng biện pháp hòa bình.', 'Sử dụng vũ lực hoặc đe doạn vũ lực đối với nhau.', 'Chung sống hòa bình, vừa hợp tác vừa đấu tranh.', 'Hợp tác phát triển có hiệu quả về kinh tế và văn hóa.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Hợp tác phát triển có hiệu quả về kinh tế và văn hóa.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
