INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_30', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Nội dung nào không phải là khó khăn mà Nhật Bản thường gặp trong quá trình phát triển đất nước?', 'Phụ thuộc vào nguồn nguyên nhiêu liệu nhập khẩu từ nước ngoài.', 'Cơ cấu kinh tế thiếu cân đối giữa các vùng và các ngành kinh tế.', 'Những xung đột quân sự kéo dài trên bán đảo Triều Tiên.', 'Sự cạnh tranh quyết liệt của Mỹ, Tây Âu, Trung Quốc, NICs.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Những xung đột quân sự kéo dài trên bán đảo Triều Tiên.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
