INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_60', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Nền tảng chính sách đối ngoại của Nhật Bản giai đoạn 1952 - 1973 là', 'tham gia vào các liên kết kinh tế khu vực.', 'duy trì liên minh chặt chẽ với Mỹ.', 'thiết lập quan hệ với các nước đồng minh cũ.', 'tăng cường quan hệ với các nước Đông Nam Á.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: duy trì liên minh chặt chẽ với Mỹ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_61', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Sự ra đời nhà nước Cộng hòa Nhân dân Trung Hoa (01.10.1949) có ý nghĩa quốc tế to lớn nào?', 'Mở rộng không gian địa lý của chủ nghĩa xã hội.', 'Mở ra kỉ nguyên độc lập, tự do và tiến lên CNXH.', 'Chấm dứt chiến tranh xâm lược thực dân kiểu mới.', 'Mở đường giải phóng cho các dân tộc ở châu Á.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Mở rộng không gian địa lý của chủ nghĩa xã hội.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_62', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Sau khi lật đổ chế độ độc tài thân Mỹ, nhân dân Cu-ba thực hiện nhiệm vụ cơ bản nào?', 'Giúp đỡ các nước Mỹ Latinh giành chính quyền.', 'Đấu tranh chống thù trong giặc ngoài.', 'Xây dựng cơ sở vật chất của chủ nghĩa xã hội.', 'Thành lập liên minh quân sự mới ở Mỹ Latinh.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Xây dựng cơ sở vật chất của chủ nghĩa xã hội.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_63', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Sau Chiến tranh thế giới thứ hai, tình hình Nhật Bản có điểm gì khác so với tình hình nước Mỹ?', 'Là nước thắng trận và thu nhiều lợi nhuận.', 'Là nước bại trận và bị chiến tranh tàn phá nặng nề.', 'Đất nước hòa bình, có điều kiện phát triển kinh tế.', 'Trở thành trung tâm kinh tế - tài chính lớn thế giới.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Là nước bại trận và bị chiến tranh tàn phá nặng nề.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
