INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_71', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Sau Chiến tranh thế giới thứ hai, để phát triển khoa học - kĩ thuật, Nhật Bản đã', 'kêu gọi nhà khoa học đến Nhật làm việc.', 'mua bằng phát minh, sáng chế của các nước.', 'đẩy mạnh đầu tư cho những nghiên cứu mới.', 'đi sâu vào các ngành công nghệ cao.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: mua bằng phát minh, sáng chế của các nước.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
