INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_73', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Từ năm 1958, Trung Quốc thực hiện đường lối ba ngọn cờ hồng” không bao gồm', '“Công xã nhân dân”.', '“Đường lối chung”.', '“Đại cách mạng văn hóa vô sản”', '“Đại nhảy vọt”', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: “Đại cách mạng văn hóa vô sản”') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_75', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Trước Chiến tranh thế giới thứ hai, kẻ thù của nhân dân các nước Đông Nam Á là', 'chế độ phân biệt chủng tộc.', 'đế quốc Âu-Mỹ.', 'chủ nghĩa thực dân mới.', 'chủ nghĩa Phát xít.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: đế quốc Âu-Mỹ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_76', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Nhận định nào sau đây phản ánh đúng về chính sách đối ngoại của Ấn Độ sau khi giành độc lập?', 'Hòa hoãn, tích cực.', 'Xu hướng trung lập, tích cực.', 'Hòa bình, trung lập tích cực.', 'Trung lập tích cực, tiến bộ.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Hòa bình, trung lập tích cực.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_77', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Quá trình xây dựng chủ nghĩa xã hội ở Cu-ba sau năm 1961 không đạt được thành tựu nào?', 'Xây dựng nền công nghiệp với cơ cấu ngành hợp lí.', 'Xây dựng ngành công nghiệp vũ trụ phát triển.', 'Xây dựng một nền nông nghiệp đa dạng.', 'Giáo dục, y tế, văn hóa phát triển, đạt trình độ cao.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Xây dựng ngành công nghiệp vũ trụ phát triển.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_78', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Sự kiện nào sau đây đặt nền tảng mới cho quan hệ giữa Mỹ và Nhật Bản sau Chiến tranh thế giới thứ hai?', 'Mỹ xây dựng căn cứ quân sự ở Nhật Bản.', 'Mỹ viện trợ cho Nhật Bản.', 'Kí kết Hiệp ước An ninh Mỹ - Nhật.', 'Mỹ đóng quân tại Nhật Bản.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Kí kết Hiệp ước An ninh Mỹ - Nhật.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
