INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B12_81', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B12'), 'LS9_KNTT_B12', 'Sau Chiến tranh thế giới thứ hai, giai đoạn nào nhân dân Campuchia rơi vào thảm họa diệt chủng?', 'Thời kỳ nội chiến kéo dài (1979 - 1991).', 'Thời kỳ đế quốc Mỹ xâm lược (1970 - 1975).', 'Tập đoàn Khơ-me đỏ cầm quyền (1975 - 1979).', 'Thực dân Pháp xâm lược (1945 - 1954).', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Tập đoàn Khơ-me đỏ cầm quyền (1975 - 1979).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
