INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_01', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Năm đầu sau Cách mạng tháng Tám năm 1945, nhân dân Việt Nam đẩy mạnh tăng gia sản xuất thực chất là biện pháp để', 'tiến hành cải cách ruộng đất.', 'phát động Tuần lễ vàng.', 'giữ vững quyền tự do, độc lập.', 'giải quyết nạn mù chữ.', 3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: giữ vững quyền tự do, độc lập.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_02', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Ngày 6/1/1946 diễn ra sự kiện nào có ý nghĩa lịch sử đặc biệt đối với nhân dân và đất nước Việt Nam?', 'Quốc hội quyết định thành lập Chính phủ Liên hiệp kháng chiến.', 'Chủ tịch Hồ Chí Minh ra Lời kêu gọi kháng chiến chống Pháp.', 'Đảng Cộng sản Đông Dương tiến hành đại hội đại biểu lần hai.', 'Lần đầu tiên tiến hành Tổng tuyển cử bầu Quốc hội khóa I.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Chủ tịch Hồ Chí Minh ra Lời kêu gọi kháng chiến chống Pháp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
