INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_05', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Sau khi Cách mạng tháng Tám thành công, các thế lực ngoại xâm và nội phản ở Việt Nam đều có chung âm mưu nào sau đây?', 'Biến Việt Nam là tâm điểm của cuộc đối đầu Đông - Tây', 'Chống phá và tiêu diệt nước Việt Nam non trẻ.', 'Ngăn cản quá trình hội nhập quốc tế của Việt Nam.', 'Duy trì chính quyền tay sai Trần Trọng Kim.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Chống phá và tiêu diệt nước Việt Nam non trẻ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_06', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Tổ chức nào được thành lập ở Việt Nam trong năm đầu sau Cách mạng tháng Tám năm 1945?', 'Hội Văn hóa Cứu quốc.', 'Đảng Xã hội Việt Nam.', 'Việt Nam Độc lập Đồng minh.', 'Việt Nam Giải phóng quân.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Đảng Xã hội Việt Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_07', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Năm đầu sau Cách mạng tháng Tám năm 1945, để xây dựng và củng cố chính quyền, nhân dân Việt Nam đã đẩy mạnh', 'cải cách ruộng đất và giảm sưu thuế.', 'việc gieo trồng cây lương thực, hoa màu.', 'việc cải tiến quản lý hợp tác xã bậc cao.', 'phá kho thóc để giải quyết nạn đói.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: việc gieo trồng cây lương thực, hoa màu.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_09', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Trong những năm 1945 - 1946, cách mạng Việt Nam thực hiện hai nhiệm quan trọng nào sau đây?', 'Bảo vệ và giữ vững chính quyền dân chủ nhân dân.', 'Đấu tranh chống các thế lực ngoại xâm và nội phản.', 'Xây dựng và bảo vệ chính quyền cách mạng non trẻ.', 'Xây dựng kinh tế và từng bước xóa đói giảm nghèo.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Xây dựng và bảo vệ chính quyền cách mạng non trẻ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_10', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Theo Hội nghị Pốt-xđam năm 1945, việc giải giáp quân đội phát xít Nhật ở Đông Dương được giao cho quân đội của', 'Anh và Mỹ.', 'Trung Hoa Dân quốc và Pháp.', 'Anh và Trung Hoa Dân quốc.', 'Anh và Pháp.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Anh và Trung Hoa Dân quốc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_11', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Sau bầu cử Quốc hội khoá I năm 1946, các địa phương Bắc Bộ, Trung Bộ đã', 'tiến hành bầu cử Hội đồng nhân dân các cấp.', 'thành lập các tổ chức đoàn thể dưới tên gọi Cứu quốc.', 'thành lập tòa án nhân dân và Ủy ban nhân dân các cấp.', 'đẩy mạnh việc cải cách cơ cấu tổ chức hành chính.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: tiến hành bầu cử Hội đồng nhân dân các cấp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_12', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Năm đầu sau Cách mạng tháng Tám năm 1945, lực lượng vũ trang nhân dân Việt Nam không bao gồm', 'lực lượng dân quân tự vệ.', 'đội quân chủ lực.', 'các đội vũ trang địa phương.', 'lực lượng giữ gìn hòa bình.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: lực lượng giữ gìn hòa bình.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_14', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Khẩu hiệu nào dưới đây không phù hợp với cách mạng Việt Nam trong những năm 1945 - 1946?', '“Tăng gia sản xuất ngay”.', '“Không một tấc đất bỏ hoang”.', '“Tăng gia sản xuất, thực hành tiết kiệm”.', '“Chia ngay ruộng đất cho nông dân”.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: “Chia ngay ruộng đất cho nông dân”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_15', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Năm đầu sau Cách mạng tháng Tám năm 1945, Nhà nước đã vận động toàn dân', 'cải cách toàn diện giáo dục.', 'thi đua dạy tốt, học tốt.', 'xây dựng nông thôn mới.', 'xây dựng đời sống văn hóa mới.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: xây dựng đời sống văn hóa mới.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_16', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Quá trình xâm lược Nam Bộ (9/1945 - 2/1946) của thực dân Pháp ở có sự hỗ trợ của lực lượng', 'Anh, Nhật.', 'Trung Hoa Dân quốc, Mỹ.', 'Anh, Mỹ.', 'Trung Hoa Dân quốc, Nhật.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Anh, Nhật.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_18', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Nội dung nào sau đây đúng về tình hình nước Việt Nam Dân chủ Cộng hòa ngay sau Cách mạng tháng Tám năm 1945?', 'Quyền độc lập tự do chưa được khẳng định.', 'Nhân dân chưa được hưởng quyền tự do.', 'Chưa có chính quyền Trung ương quản lý.', 'Nền độc lập bị đe dọa nghiêm trọng.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Nền độc lập bị đe dọa nghiêm trọng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_19', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Chính sách ngoại giao khôn khéo của Chính phủ Việt Nam với quân Trung Hoa Dân quốc và tay sai (2/9/1945 - 6/3/1946) đã', 'buộc chúng phải rút quân ra khỏi Việt Nam.', 'làm giảm những thiệt hại mà Việt Quốc, Việt Cách gây ra.', 'làm suy yếu chúng trong nội chiến với Đảng Cộng sản.', 'làm thất bại âm mưu lật đổ chính quyền của chúng.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: làm thất bại âm mưu lật đổ chính quyền của chúng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_21', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Nội dung nào sau đây không phải là yêu sách của thế lực Việt Quốc, Việt Cách đối với Chính phủ Việt Nam năm 1945 - 1946?', 'Đòi ta cung cấp một phần lương thực, thực phẩm, chất đốt.', 'Đòi gạt những đảng viên cộng sản ra khỏi Chính phủ lâm thời.', 'Đòi Việt Nam không ngoại giao với các quốc gia láng giềng.', 'Đòi tham gia vào Quốc hội và Chính phủ Việt Nam mới.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Đòi Việt Nam không ngoại giao với các quốc gia láng giềng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_23', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Nhà nước Việt Nam Dân chủ Cộng hoà từ tháng 9/1945 đến tháng 12/1946 bị đe dọa bởi quân đội những nước', 'nắm giữ quyền chi phối tổ chức Hiệp ước Bắc Đại Tây Dương (NATO).', 'thực thi nhiệm vụ quốc tế nhưng có những giã tâm và mục đích riêng.', 'đã giữ vai trò quan trọng nhất trong việc tiêu diệt chủ nghĩa phát xít.', 'đang có tham vọng khôi phục lại chủ quyền của mình ở Đông Dương.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: đang có tham vọng khôi phục lại chủ quyền của mình ở Đông Dương.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_25', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Lĩnh vực nào đóng vai trò quan trọng trong việc giáo dục lòng yêu nước ở Việt Nam sau Cách mạng tháng Tám năm 1945?', 'Y tế.', 'Xã hội.', 'Công nghệ.', 'Báo chí.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Xã hội.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_26', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Chính phủ Việt Nam kí với Pháp Hiệp định Sơ bộ và Tạm ước với mục đích chung nào sau đây?', 'Có thời gian hòa bình để xây dựng và củng cố lực lượng.', 'Đưa đất nước thoát khỏi tình thế “Ngàn cân treo sợi tóc”.', 'Chấm dứt chế độ chiếm đóng của quân Đồng minh.', 'Tránh tình trạng cùng một lúc phải đối phó với nhiều kẻ thù.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Có thời gian hòa bình để xây dựng và củng cố lực lượng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_29', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Một trong những biện pháp để giải quyết khó khăn về nạn dốt sau Cách mạng tháng Tám năm 1945 là', 'thành lập Nha Bình dân học vụ.', 'xây dựng các trường đại học.', 'mở trường học phố thông các cấp.', 'ban hành bản Hiến pháp mới.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: thành lập Nha Bình dân học vụ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_30', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Từ ngày 6/3/1946 đến ngày 19/12/1946, Chính phủ Việt Nam Dân chủ Cộng hòa thực hiện đối sách nào với Pháp?', 'Kiên quyết chiến đấu.', 'Hòa hoãn, nhân nhượng.', 'Đối đầu trực tiếp về quân sự.', 'Toàn quốc kháng chiến.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Hòa hoãn, nhân nhượng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_32', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Ngày 29/5/1946, tổ chức nào được thành lập nhằm tăng cường và mở rộng khối đoàn kết toàn dân?', 'Hội Liên hiệp quốc dân Việt Nam.', 'Mặt trận Việt Nam độc lập đồng minh.', 'Quân đội quốc gia Việt Nam.', 'Mặt trận Liên hiệp quốc dân Việt Nam.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Hội Liên hiệp quốc dân Việt Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_33', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Để chống phá cách mạng Việt Nam, quân Trung Hoa Dân quốc đã sử dụng các thế lực tay sai trong tổ chức nào sau đây?', 'Đại Việt, Việt Quốc.', 'Việt Quốc, Việt Cách.', 'Việt Quốc, Phục Việt.', 'Tân Việt, Việt Cách.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Việt Quốc, Việt Cách.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_35', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Nội dung nào sau đây phản ánh kết quả cuộc chiến đấu chống Pháp của nhân dân Nam Bộ (1945 - 1946)?', 'Đánh bại chính quyền và quân đội tay sai ở miền Nam.', 'Giành được chính quyền cơ sở, tiến hành cải cách ruộng đất.', 'Giữ được chính quyền cấp cơ sở, xây dựng lực lượng chính trị.', 'Giam chân quân Pháp nhiều tháng ở Sài Gòn, Chợ Lớn.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Giam chân quân Pháp nhiều tháng ở Sài Gòn, Chợ Lớn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_37', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Khi Hiệp ước Hoa - Pháp được kí kết (2/1946), Chính phủ nước Việt Nam Dân chủ Cộng hòa thực hiện chủ trương nào sau đây?', 'Phát động toàn quốc kháng chiến chống thực dân Pháp.', 'Đấu tranh chống quân Pháp và Trung Hoa Dân quốc.', 'Hòa hoãn và nhân nhượng có nguyên tắc với thực dân Pháp.', 'Hòa với Pháp để kháng chiến chống Trung Hoa Dân quốc.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Hòa hoãn và nhân nhượng có nguyên tắc với thực dân Pháp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_38', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Để chống Pháp xâm lược tháng 9 năm 1945, nhân dân miền Nam đã', 'phá hủy nhiều xí nghiệp, công sở, kho tàng, bến bãi.', 'xây dựng phòng tuyến dọc theo bờ biển Nam Bộ.', 'phối hợp với nhân dân Campuchia để chặn bước tiến.', 'tập kết lực lượng về chiến khu Dương Minh Châu.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: phá hủy nhiều xí nghiệp, công sở, kho tàng, bến bãi.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_39', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Sự kiện nào sau đây đã tạo cơ sở pháp lí quan trọng để nước Việt Nam đấu tranh ngoại giao với kẻ thù sau năm 1945?', 'Sự ra đời Chính phủ Liên hiệp kháng chiến Việt Nam (3/1946).', 'Bản Tuyên ngôn độc lập của Chủ tịch Hồ Chí Minh (9/1945).', 'Bản Hiến pháp của nước Việt Nam Dân chủ Cộng hòa (11/1946).', 'Sự ra đời Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa (8/1945).', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Sự ra đời Chính phủ Liên hiệp kháng chiến Việt Nam (3/1946).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_40', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Năm đầu sau Cách mạng tháng Tám, những biện pháp giải quyết “giặc dốt” của Chính phủ Việt Nam có ý nghĩa nào sau đây?', 'Đưa Việt Nam sánh ngang với các quốc gia trong khu vực và thế giới.', 'Nâng cao dân trí,thực hiện thành công phổ cập giáo dục tiểu học.', 'Giải quyết hậu quả chính sách “ngu dân” của thực dân Pháp.', 'Xóa bỏ tình trạng mù chữ, hình thành nền giáo dục phổ thông.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Giải quyết hậu quả chính sách “ngu dân” của thực dân Pháp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_45', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Để thôn tính được cả nước Việt Nam, đầu năm 1946, Pháp muốn đưa quân ra miền Bắc bằng biện pháp nào sau đây?', 'Đánh chiếm quân sự.', 'Bạo lực chiến tranh.', 'Tấn công quân sự.', 'Chính trị hòa bình.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Chính trị hòa bình.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_46', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Sau năm 1945, Đảng Cộng sản Đông Dương không tiến hành ngay cuộc cải cách ruộng đất vì', 'Việt Nam đang tập trung giải quyết nạn đói, chưa tăng gia sản xuất.', 'vấn đề ruộng đất không phải là vấn đề chiến lược của cách mạng.', 'muốn phát huy vai trò của địa chủ trong xây dựng và bảo vệ đất nước.', 'giai cấp đại địa chủ không chịu từ bỏ quyền sở hữu ruộng đất.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: muốn phát huy vai trò của địa chủ trong xây dựng và bảo vệ đất nước.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_47', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Một trong những biện pháp trước mắt để giải quyết khó khăn về nạn đói sau Cách mạng tháng Tám năm 1945 là', 'lập “Hũ gạo cứu đói".', 'thực hiện khẩu hiệu “Tắc đất tấc vàng".', 'thực hành tiết kiệm.', 'thực hiện tăng gia sản xuất.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: lập “Hũ gạo cứu đói".') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_48', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Một trong những biện pháp lâu dài để giải quyết nạn đói sau Cách mạng tháng Tám năm 1945 là', 'kêu gọi “Nhường cơm sẻ áo".', 'tổ chức “Ngày đồng tâm”.', 'tăng gia sản xuất.', 'điều hoà thóc gạo giữa các địa phương.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: tăng gia sản xuất.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_49', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Ngày 23/9/1945, để huy động nhân dân tham gia kháng chiến chống Pháp, cơ quan kháng chiến Nam Bộ đã', 'ra bản chỉ thị Toàn dân kháng chiến.', 'thống nhất ra Lời kêu gọi.', 'ra đường lối kháng chiến toàn dân.', 'rút ra khỏi Sài Gòn - Chợ lớn.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: thống nhất ra Lời kêu gọi.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_50', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Tháng 9/1945, Việt Nam Giải phóng quân đã đổi thành', 'Trung đoàn Thủ đô.', 'Vệ quốc đoàn.', 'Quân giải phóng.', 'Quân đội quốc gia.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Vệ quốc đoàn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_52', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Với việc kí kết bản Hiệp định Sơ bộ (06/03/1946), Chính phủ Pháp đã công nhận', 'độc lập, chủ quyền của nước Việt Nam.', 'quyền tự chủ của nước Việt Nam mới.', 'các quyền dân tộc cơ bản của Việt Nam.', 'Việt Nam là quốc gia độc lập trên thế giới.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: quyền tự chủ của nước Việt Nam mới.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_54', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Nội dung nào sau đây phản ánh chính sách đối ngoại của nước Việt Nam Dân chủ Cộng hòa sau Cách mạng tháng Tám năm 1945?', 'Đẩy mạnh các hoạt động nhằm chia rẽ sự liên kết của các thế lực ngoại xâm.', 'Nhận được sự hỗ trợ của các nước xã hội chủ nghĩa để đấu tranh chống Pháp.', 'Kiên quyết làm thất bại âm mưu chia rẽ phá hoại của Trung Hoa Dân quốc.', 'Có những hành động vãn hồi hòa bình với Pháp khi chúng tấn công Nam Bộ.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Kiên quyết làm thất bại âm mưu chia rẽ phá hoại của Trung Hoa Dân quốc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_56', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Để giải quyết cấp bách nạn đói sau năm 1945, Đảng và Chính phủ không sử dụng biện pháp nào?', 'Lập hũ gạo cứu đói.', 'Tiến hành bình quân ruộng đất.', 'Tổ chức “Ngày đồng tâm”.', 'Lưu thông gạo giữa các miền.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Tiến hành bình quân ruộng đất.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
