INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_59', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Thực dân Pháp chính thức quay trở lại xâm lược Việt Nam lần hai sau sự kiện nào sau đây?', 'Pháp núp bóng quân Anh để xây dựng chính quyền bù nhìn tay sai (2/9/1945).', 'Tấn công nhân dân Sài Gòn - Chợ Lớn mít tinh mừng ngày Độc lập (2/9/1945).', 'Chiếm các cảng ở Sài Gòn và sân bay để làm nơi đóng quân của Pháp.', 'Đánh úp trụ sở Uỷ ban nhân dân Nam Bộ và Cơ quan tự vệ Sài Gòn (23/9/1945).', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Đánh úp trụ sở Uỷ ban nhân dân Nam Bộ và Cơ quan tự vệ Sài Gòn (23/9/1945).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_60', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Đầu tháng 9 năm 1945, quân Anh và quân Trung Hoa Dân quốc vào Đông Dương với danh nghĩa nào sau đây?', 'Lực lượng ủng hộ Việt Nam đánh bại phát xít.', 'Quân Đồng minh giải giáp quân Nhật ở Đông Dương.', 'Lực lượng giữ gìn hòa bình của Liên hợp quốc.', 'Quân Đồng minh để kết thúc cuộc chiến tranh.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Quân Đồng minh giải giáp quân Nhật ở Đông Dương.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_61', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Để đấu tranh chống ngoại xâm nội phản (1945 - 1946), Đảng và Chính phủ Việt Nam đã sử dụng chính sách nào sau đây?', 'Từng bước phân hóa và cô lập kẻ thù của cách mạng.', 'Khoét sâu mâu thuẫn giữa các nước đồng minh.', 'Ngả về phía các nước Đồng minh để chống nội phản.', 'Hòa với kẻ thù nguy hiểm nhất để có thời gian hòa bình.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Từng bước phân hóa và cô lập kẻ thù của cách mạng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_62', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Đầu năm 1946, sau khi chiếm đóng các đô thị ở Nam Bộ và cực Nam Trung Bộ, thực dân Pháp có hành động mới nào sau đây?', 'Chuẩn bị tiến quân ra xâm lược miền Bắc.', 'Thiết lập Liên bang Đông Dương thuộc Pháp.', 'Thiết lập bộ máy cai trị mới ở Bắc Bộ.', 'Chờ viện binh để mở rộng xâm lược Nam Bộ.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Chuẩn bị tiến quân ra xâm lược miền Bắc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
