INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_72', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Năm đầu sau Cách mạng tháng Tám năm 1945, Chính phủ Việt Nam đã kiện toàn', 'Bộ Quốc phòng.', 'Bộ Canh tác.', 'Bộ Quân Nhu.', 'Bộ Quân y.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Bộ Quốc phòng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_73', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Ngày 9/11/1946, Quốc hội khóa I nước Việt Nam Dân chủ Cộng hòa đã thông qua nội dung nào?', 'Bản Hiến pháp của nước Việt Nam Dân chủ Cộng hòa.', 'Danh sách Chính phủ Liên hiệp kháng chiến chính thức.', 'Quyết định cho lưu hành tiền Việt Nam trên cả nước.', 'Quyết định phát động toàn quốc kháng chiến chống Pháp.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Bản Hiến pháp của nước Việt Nam Dân chủ Cộng hòa.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_74', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Trong những năm 1945 - 1946, để giải quyết ngay nạn đói, Chủ tịch Hồ Chí Minh đã kêu gọi nhân dân cả nước', 'lập “Hũ gạo cứu đói”.', 'tiến hành cải cách ruộng đất.', 'tăng gia sản xuất ngay.', 'phá kho thóc của Nhật.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: lập “Hũ gạo cứu đói”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B13_76', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B13'), 'LS9_KNTT_B13', 'Nội dung nào sau đây phản ánh ý nghĩa của cuộc Tổng tuyển cử ngày 6/1/1946 và việc bầu cử Hội đồng nhân dân các cấp?', 'Nâng cao vị thế của Việt Nam trên trường quốc tế.', 'Tạo uy tín trong nhân dân, khẳng định chủ quyền lãnh thổ.', 'Đưa đất nước thoát khỏi tình thế “Ngàn cân treo sợi tóc”.', 'Thể hiện tinh thần yêu nước và quyền làm chủ của nhân dân.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Thể hiện tinh thần yêu nước và quyền làm chủ của nhân dân.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_02', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Nền kinh tế được đẩy mạnh tăng gia sản xuất đầu năm 1946 đầu tiên và mạnh mẽ trên lĩnh vực nào?', 'Thương nghiệp.', 'Công nghiệp.', 'Nông nghiệp.', 'Thủ công nghiệp.', 3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Nông nghiệp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_03', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Đảng Cộng sản Đông Dương đưa ra đường lối kháng chiến toàn diện không dựa trên cơ sở nào?', 'Thực dân Pháp tấn công Việt Nam trên tất cả các mặt trận.', 'Việt Nam vừa kháng chiến chống Pháp, vừa xây dựng đất nước.', 'Nhân dân là lực lượng quan trọng tạo nên thắng lợi của kháng chiến.', 'Kháng chiến toàn dân nên cần phát huy sức mạnh trên mọi lĩnh vực.', 3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Nhân dân là lực lượng quan trọng tạo nên thắng lợi của kháng chiến.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_04', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', '“Quyết tử cho Tổ quốc quyết sinh” là lời khen ngợi của Chủ tịch Hồ Chủ Minh đối với', 'Quân đội quốc gia Việt Nam.', 'Trung đoàn Thủ đô.', 'Việt Nam Giải phóng quân.', 'Vệ quốc đoàn.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Trung đoàn Thủ đô.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_05', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Bản chỉ thị “Toàn dân kháng chiến” của Ban Thường vụ Trung ương Đảng (22/12/1946) đã', 'biểu dương tinh thần chiến đấu dũng cảm của Trung đoàn Thủ đô.', 'khẳng định đấu tranh của quần chúng quyết định thắng lợi quân sự.', 'vạch ra đường lối kháng chiến toàn dân, toàn diện cho thủ đô Hà Nội.', 'khái quát những nội dung cơ bản về đường lối kháng chiến chống Pháp.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: khái quát những nội dung cơ bản về đường lối kháng chiến chống Pháp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_06', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Tháng 12/1946, lực lượng quân sự nào được thành lập và chiến đấu anh dũng ở thủ đô Hà Nội?', 'Giải phóng quân.', 'Trung đoàn Thủ đô.', 'Vệ quốc đoàn.', 'Hội Liên Việt.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Trung đoàn Thủ đô.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_08', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Những hiệp định, hiệp ước đã ký kết giữa Việt Nam với Pháp năm 1946 là', 'cơ sở để tiếp tục hòa hoãn với Pháp từ năm 1946.', 'nỗ lực “cứu vãn nền hòa bình” của Chính phủ Việt Nam.', 'cơ sở để các nước công nhận và đặt quan hệ ngoại giao.', 'tham vọng của Pháp trong thiếp lập Liên bang Đông Dương.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: nỗ lực “cứu vãn nền hòa bình” của Chính phủ Việt Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_10', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Sau khi toàn quốc kháng chiến bùng nổ năm 1946, để chuẩn bị cho kháng chiến lâu dài, Đảng và Chính phủ đã', 'ban hành Chỉ thị Toàn dân kháng chiến.', 'di chuyển các cơ quan lên căn cứ Việt Bắc.', 'tiến hành bầu cử Hội đồng nhân dân các cấp.', 'mở các chiến dịch tấn công Pháp với quy mô lớn.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: di chuyển các cơ quan lên căn cứ Việt Bắc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_11', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Đường lối kháng chiến chống thực dân Pháp (1945 - 1954) không xác định nhiệm vụ nào của cách mạng Việt Nam?', 'Đem lại ruộng đất cho nhân dân.', 'Từng bước thực hiện nhiệm vụ dân chủ.', 'Hoàn thành nhiệm vụ giải phóng dân tộc.', 'Nâng cao vị thế Việt Nam trường quốc tế.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Đem lại ruộng đất cho nhân dân.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_12', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Cuộc chiến đấu trong các đô thị miền Bắc Việt Nam (12/1946 - 2/1947) diễn ra căng thẳng và quyết liệt nhất ở', 'Đà Nẵng.', 'Thủ đô Hà Nội.', 'Hải Phòng.', 'Nam Định.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Thủ đô Hà Nội.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_13', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Nội dung nào sau đây là kết quả trong cuộc chiến đấu ở các đô thị phía Bắc vĩ tuyến 16 (12/1946 - 2/1947)?', 'Phá tan kế hoạch tập trung binh lực của Pháp ở Đồng bằng Bắc Bộ.', 'Làm phá sản hoàn toàn kế hoạch đánh nhanh thắng nhanh của Pháp.', 'Tiêu diệt một bộ phận quân Pháp, buộc chúng phải phân tán binh lực.', 'Bảo vệ Trung ương Đảng, Chính phủ rút lui an toàn lên căn cứ Việt Bắc.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Bảo vệ Trung ương Đảng, Chính phủ rút lui an toàn lên căn cứ Việt Bắc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_15', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Đề ra kế hoạch tấn công lên Việt Bắc thu - đông 1947 là nội dung trong kế hoạch quân sự nào của Pháp?', 'Kế hoạch Đác-giăng-li-ơ.', 'Kế hoạch Bô-la-e.', 'Kế hoạch Rơ-ve.', 'Kế hoạch Đờ Lát đơ Tát-xi-nhi.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Kế hoạch Bô-la-e.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_16', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Cuối tháng 12 năm 1946, ở các đô thị phía Bắc vĩ tuyến 16, quân dân Việt Nam đã', 'bị động phân tán lực lượng.', 'chủ động tấn công quân Pháp.', 'chủ động rút lui ra khỏi các đô thị.', 'thực hiện “vườn không nhà trống”.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: chủ động tấn công quân Pháp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_17', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Kế hoạch tấn công lên Việt Bắc năm 1947 của thực dân Pháp nhằm mục đích cơ bản nào sau đây?', 'Nhanh chóng kết thúc chiến tranh.', 'Hoàn thành quá trình bình định Việt Nam.', 'Giành thắng lợi về quân sự để rút quân về nước.', 'Tăng cường hệ thống phòng thủ trên đường số 4.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Nhanh chóng kết thúc chiến tranh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_18', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Từ sau chiến dịch Việt Bắc thu - đông 1947, Pháp tăng cường thực hiện chính sách nào sau đây?', 'Mở rộng hoạt động bình định và lấn chiếm vùng giải phóng.', 'Bao vây và cô lập căn cứ địa Việt Bắc, phá hoại hậu phương.', 'Tiến hành chiến tranh kinh tế và tâm lí, phá hoại vùng tự do.', 'Dùng người Việt đánh người Việt, lấy chiến tranh nuôi chiến tranh.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Dùng người Việt đánh người Việt, lấy chiến tranh nuôi chiến tranh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_19', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Thắng lợi của quân dân Việt Nam trong chiến dịch Việt Bắc thu - đông năm 1947 có ý nghĩa nào sau đây?', 'Làm lung lay ý chí xâm lược của thực dân Pháp.', 'Làm thay đổi cục diện chiến tranh ở Đông Dương.', 'Giành được thế chủ động trên chiến trường chính.', 'Làm thất bại âm mưu “đánh nhanh thắng nhanh” của Pháp.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Làm thất bại âm mưu “đánh nhanh thắng nhanh” của Pháp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_20', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Điều kiện tiên quyết để thực hiện nhiệm vụ kháng chiến, kiến quốc ở Việt Nam thời kỳ 1945 - 1954 là', 'có sự ủng hộ to lớn của quốc tế.', 'có lực lượng vũ trang ba thứ quân.', 'có chính quyền dân chủ nhân dân.', 'có hậu phương vững mạnh về mọi mặt.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: có chính quyền dân chủ nhân dân.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_21', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Mục đích nào của Pháp đã thực hiện được trong cuộc tấn công quân sự lên Việt Bắc năm 1947?', 'Tiêu diệt cơ quan đầu não kháng chiến của Việt Nam.', 'Bước đầu kiểm soát được vùng biên giới Việt - Trung.', 'Đánh nhanh thắng nhanh, thành lập chính phủ bù nhìn.', 'Phá tan căn cứ địa Việt Bắc, tiêu diệt lực lượng Việt Nam.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Bước đầu kiểm soát được vùng biên giới Việt - Trung.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_22', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Chiến dịch Việt Bắc Thu - Đông 1947 không phải là', 'cuộc phản công quy mô lớn đầu tiên của bộ đội chủ lực Việt Nam.', 'trận quyết chiến chiến lược giữa quân đội Việt Nam và quân đội Pháp.', 'đòn đánh phủ đầu vào quyết tâm tái chiếm Đông Dương của thực dân Pháp.', 'việc thực hiện mưu đồ lớn để hoàn thành sớm mục tiêu xâm lược của Pháp.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: trận quyết chiến chiến lược giữa quân đội Việt Nam và quân đội Pháp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_23', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Năm 1949, sự kiện nào của lịch sử thế giới tạo điều kiện thuận lợi cho cách mạng Việt Nam?', 'Chiến tranh lạnh bao trùm toàn thế giới.', 'Sự ra đời của Hội đồng tương trợ kinh tế (SEV).', 'Sự ra đời của nước Cộng hòa Nhân dân Trung Hoa.', 'Sự ra đời của tổ chức Hiệp ước Bắc Đại Tây Dương.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Sự ra đời của nước Cộng hòa Nhân dân Trung Hoa.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_25', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Năm 1950, để đặt nền móng cho nền giáo dục dân tộc dân chủ nhân dân, Chính phủ nước Việt Nam Dân chủ Cộng hòa đã', 'xây dựng nhiều trường đại học lớn.', 'phát động phong trào xóa giặc dốt.', 'tiến hành cải cách giáo dục phổ thông.', 'phát động phong trào bình dân học vụ.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: tiến hành cải cách giáo dục phổ thông.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_26', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Nội dung nào sau đây là thắng lợi về mặt ngoại giao của nước Việt Nam Dân chủ Cộng hòa năm 1950?', 'Các nước XCHN công nhận và đặt quan hệ ngoại giao với Việt Nam.', 'Nhân dân Pháp và Việt Nam thành lập mặt trận chống kẻ thù chung.', 'Việt Nam nhận được viện trợ từ các nước yêu chuộng hòa bình thế giới.', 'Các nước đồng minh đã rút khỏi Việt Nam, ghi nhận Chính phủ Việt Nam.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Các nước XCHN công nhận và đặt quan hệ ngoại giao với Việt Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_27', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Quốc gia đầu tiên trên thế giới chính thức công nhận và đặt quan hệ ngoại giao với nước Việt Nam Dân chủ Cộng hòa là', 'Trung Quốc.', 'Liên Xô.', 'Mỹ.', 'Nhật Bản.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Trung Quốc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_29', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Âm mưu thâm độc, tàn bạo nào được Pháp đẩy mạnh thực hiện sau chiến dịch Việt Bắc thu - đông 1947 là', 'dùng người Việt đánh người Việt.', 'gây chiến tranh tâm lí và chiến tranh kinh tế.', 'chống phá vùng tự do bằng biệt kích, thổ phỉ.', 'dùng người Đông Dương trị người Đông Dương.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: dùng người Việt đánh người Việt.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_30', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Từ năm 1950, cuộc chiến tranh xâm lược của Pháp ở Đông Dương đã', 'chịu sự chi phối của hai cực, hai phe.', 'ngày càng lan rộng ra toàn khu vực châu Á.', 'có sự chuyển biến về bản chất chiến tranh.', 'thu hút sự can thiệp của các nước đồng minh.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: chịu sự chi phối của hai cực, hai phe.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_31', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Tháng 6 năm 1950, Đảng và Chính phủ quyết định mở chiến dịch Biên giới nhằm', 'nhanh chóng giành thắng lợi, bảo vệ độc lập dân tộc.', 'giam chân quân Pháp dọc theo tuyến biên giới Việt - Trung.', 'tạo những thuận lợi mới thúc đẩy cuộc kháng chiến tiến lên.', 'đẩy Pháp lâm vào mâu thuẫn giữa tập trung và phân tán binh lực.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: tạo những thuận lợi mới thúc đẩy cuộc kháng chiến tiến lên.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_32', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Pháp mở cuộc tấn công lên Việt Bắc thu - đông năm 1947 không nhằm mục đích nào sau đây?', 'Phá tan cơ quan đầu não kháng chiến.', 'Khóa chặt biên giới Việt Nam - Trung Quốc.', 'Thực hiện âm mưu đánh nhanh thắng nhanh.', 'Di chuyển hậu phương của Pháp lên Việt Bắc.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Di chuyển hậu phương của Pháp lên Việt Bắc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_34', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Khi thực dân Pháp mở cuộc tiến công lên Việt Bắc năm 1947, Trung ương Đảng ra bản chỉ thị', '“Tất cả cho chiến dịch, tất cả để chiến thắng”.', '“Chủ động, cơ động, linh hoạt và chắc thắng”.', '“Phải bẻ gãy các gọng kìm tấn công của Pháp”.', '“Phải phá tan cuộc tiến công mùa đông của giặc Pháp”.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: “Phải phá tan cuộc tiến công mùa đông của giặc Pháp”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_35', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Năm 1947, âm mưu khóa chặt biên giới Việt - Trung được Pháp thực hiện thông qua kế hoạch nào nào sau đây?', 'Cho quân nhảy dù xuống Bắc Kạn, Chợ Mới, Chợ Đồn, Chợ Giã.', 'Cho binh đoàn hỗn hợp ngược sông Hồng lên sông Lô, sông Gâm.', 'Cho cánh quân bộ từ Lạng Sơn lên Cao Bằng, chiếm giữ đường số 4.', 'Tấn công lên biên giới Việt - Trung, tiêu diệt lực lượng của Việt Nam.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Cho cánh quân bộ từ Lạng Sơn lên Cao Bằng, chiếm giữ đường số 4.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_41', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Đường lối kháng chiến chống Pháp của Đảng Cộng sản Đông Dương đã xác định mục đích nào sau đây?', 'Xóa bỏ mọi tàn dư của chế độ phong kiến ở Việt Nam.', 'Tịch thu hết ruộng đất của phong kiến chia cho nông dân.', 'Đánh đổ đế quốc Pháp, phong kiến và bọn phản cách mạng.', 'Đánh đuổi thực dân Pháp xâm lược, giành độc lập hoàn toàn.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Đánh đuổi thực dân Pháp xâm lược, giành độc lập hoàn toàn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_43', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Hội nghị Văn hóa toàn quốc lần thứ hai (1948) đã', 'thành lập Hội văn hóa cứu quốc để tập hợp các văn nghệ sĩ.', 'phát động phong trào Bình dân học vụ trên phạm vi cả nước.', 'nhấn mạnh nhiệm vụ xây dựng văn hóa phục vụ kháng chiến.', 'quyết định tiến hành cải cách giáo dục từ mầm non đến đại học.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: nhấn mạnh nhiệm vụ xây dựng văn hóa phục vụ kháng chiến.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_44', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Cuối tháng 12 năm 1946, ở các đô thị phía Bắc vĩ tuyến 16, quân dân Việt Nam đã', 'bao vây, chặn quân tiếp viện của Pháp để tiêu diệt chúng.', 'thực hiện các đợt giảng hòa với Pháp để bảo toàn lực lượng.', 'xây dựng những hậu phương tại chỗ để tăng cường tiềm lực.', 'tổ chức các trận đánh làm tiêu hao một bộ phận sinh lực Pháp.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: tổ chức các trận đánh làm tiêu hao một bộ phận sinh lực Pháp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_45', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Trong chiến dịch Việt Bắc thu - đông 1947, thắng lợi tiêu biểu của quân dân Việt Nam trên đường số 4 là ở', 'Bản Sao', 'Khe Lau.', 'Thất Khê.', 'Đông Khê.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Bản Sao') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_46', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Trong kế hoạch Bô-la-e, để bao vây Việt Bắc từ phía Tây, Pháp đã sử dụng thủ đoạn nào sau đây?', 'Cho quân nhảy dù xuống Bắc Kạn, Chợ Đồn, Chợ Mới, Chợ Giã.', 'Cho binh đoàn hỗn hợp theo sông Hồng lên sông Lô, sông Gâm.', 'Cho quân bộ hành quân theo đường số 4 từ Lạng Sơn lên Cao Bằng.', 'Cho binh đoàn hỗn hợp hợp quân tại Đài Thị, Chiêm Hóa, Tuyên Quang.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Cho binh đoàn hỗn hợp theo sông Hồng lên sông Lô, sông Gâm.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_48', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Nội dung nào sau đây phản ánh kết quả trong cuộc chiến đấu ở các đô phị phía Bắc vĩ tuyến 16 (1946-1947)?', 'Lực lượng chủ lực rút lui an toàn ra vùng hậu phương.', 'Kế hoạch đánh nhanh thắng nhanh của Pháp thất bại.', 'Giải phóng được một vùng rộng lớn ở các đô thị miền Bắc.', 'Âm mưu “dùng người Việt đánh người Việt” của Pháp tan rã.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Lực lượng chủ lực rút lui an toàn ra vùng hậu phương.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_49', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Cuối năm 1947, đại bộ phận quân Pháp phải rút khỏi Việt Bắc, một bộ phận ở lại chiếm giữ', 'đường số 3.', 'đường số 4.', 'Chợ Đồn, Chợ Rã.', 'Chiêm Hoá (Tuyên Quang).', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: đường số 4.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_50', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Cuối năm 1947, Pháp mở cuộc tấn công lên Việt Bắc nhằm thực hiện mưu đồ', 'nhanh chóng kết thúc chiến tranh.', 'kết thúc chiến tranh trong danh dự.', 'giải phóng một vùng biên giới rộng lớn.', 'giam chân lực lượng của ta ở Việt Bắc.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: nhanh chóng kết thúc chiến tranh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_55', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Trong cuộc chiến tranh xâm lược Đông Dương (1950 - 1954), Chính phủ Pháp đã nhận viện trợ của nước nào sau đây?', 'Nhật Bản.', 'Mỹ.', 'Anh.', 'Đức.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Mỹ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_56', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Lợi dụng tình hình Pháp xa lầy ở chiến trường Đông Dương những năm 1950, đế quốc Mỹ đã', 'phản đối cuộc chiến tranh xâm lược của Pháp ở Đông Dương.', 'can thiệp sâu và dính líu trực tiếp vào chiến tranh Đông Dương.', 'đưa quân đội sang Đông Dương hỗ trợ quân Pháp trên chiến trường.', 'hất cẳng Pháp để biến Đông Dương thành thuộc địa kiểu mới của Mỹ.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: can thiệp sâu và dính líu trực tiếp vào chiến tranh Đông Dương.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_57', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Tháng 5 năm 1949, với sự đồng ý và giúp đỡ của Mỹ, Chính phủ Pháp đề ra kế hoạch quân sự mới nào ở Việt Nam?', 'Kế hoạch Na-va.', 'Kế hoạch Bô-la-e.', 'Kế hoạch Đờ Lát đơ Tát-xi-nhi.', 'Kế hoạch Rơ-ve.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Kế hoạch Rơ-ve.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_58', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Hai hệ thống phòng ngự được Pháp thiết lập ở Việt Nam năm 1950 nhằm bao vây, cô lập căn cứ địa Việt Bắc là', 'Hệ thống phòng ngự trên đường số 4 và “vành đai trắng”.', 'Hệ thống “vành đai trắng” ở Đông Bắc và Đồng bằng Bắc Bộ.', 'Hệ thống phòng ngự trên đường số 4 và “Hành lang Đông - Tây”.', 'Phòng tuyến “boong-ke” và hệ thống phòng ngự trên đường số 4.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Hệ thống phòng ngự trên đường số 4 và “Hành lang Đông - Tây”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_59', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Kế hoạch Rơ-ve của Pháp thực hiện ở Việt Nam từ năm 1949 không có nội dung nào sau đây?', 'Tăng cường hệ thống phòng thủ của Pháp trên đường số 4.', 'Thiết lập hành lang Đông - Tây để cô lập căn cứ địa Việt Bắc.', 'Xây dựng phòng tuyến boongke để bảo vệ đồng bằng Bắc Bộ.', 'Chuẩn bị kế hoạch tấn công quy mô lớn lên căn cứ địa Việt Bắc.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Xây dựng phòng tuyến boongke để bảo vệ đồng bằng Bắc Bộ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_60', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Tháng 6/1950, Đảng và Chính phủ quyết định mở chiến dịch Biên giới nhằm mục đích nào sau đây?', 'Khai thông biên giới Việt - Trung và mở rộng căn cứ địa Việt Bắc.', 'Đánh tan quân Pháp ở miền Bắc, nhanh chóng kết thúc chiến tranh.', 'Phá tan kế hoạch Rơ-ve và âm mưu đánh nhanh thắng nhanh của Pháp.', 'Giải phóng biên giới, tạo điều kiện để giải phóng miền Nam Trung Quốc.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Khai thông biên giới Việt - Trung và mở rộng căn cứ địa Việt Bắc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_61', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Trận tấn công mở màn của quân dân Việt Nam trong chiến dịch Biên giới thu - đông 1950 là ở', 'Đông Khê.', 'Thất Khê.', 'Na Sầm.', 'Cao Bằng.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Đông Khê.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_62', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Đảng và Chính phủ Việt Nam chọn Đông Khê là điểm tấn công mở màn chiến dịch Biên giới thu đông năm 1950 vì', 'Đông Khê giữ vị trí chiến lược quan trọng trên đường số 4.', 'Đông Khê có địa hình thuận lợi cho sự tác chiến của quân ta.', 'Đông Khê được Pháp tập trung đông quân để bảo vệ Thất Khê.', 'Đông Khê là nơi tập trung nhiều binh lực nhất của thực dân Pháp.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Đông Khê giữ vị trí chiến lược quan trọng trên đường số 4.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_63', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Quân dân Việt Nam chiếm được Đông Khê (18/9/1950) đã có tác động nào sau đây?', 'Buộc Pháp phải dừng các kế hoạch quân sự khác.', 'Pháp gặp phải tổn thất lớn, phải rút khỏi đường số 4.', 'Quân Pháp ở Cao Bằng bị cô lập, Thất Khê bi uy hiếp.', 'Buộc Pháp phải tăng thêm viện binh để bảo vệ đường số 4.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Quân Pháp ở Cao Bằng bị cô lập, Thất Khê bi uy hiếp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B14_64', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B14'), 'LS9_KNTT_B14', 'Quân dân Việt Nam đạt được kết quả nào trong chiến dịch Biên giới thu - đông 1950?', 'Buộc Pháp phải điều chỉnh nội dung của kế hoạch Rơve.', 'Giải phóng được một vùng biên giới Việt - Trung rộng lớn.', 'Phá tan mối liên hệ giữa căn cứ địa Việt Bắc với Liên khu III.', 'Giành quyền chủ động chiến lược trên chiến trường chính Bắc Bộ.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Giải phóng được một vùng biên giới Việt - Trung rộng lớn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_02', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Mỹ kí với Bảo Đại Hiệp ước Hợp tác kinh tế Việt - Mỹ năm 1951 nhằm mục đích nào sau đây?', 'Trực tiếp ràng buộc Chính phủ Bảo Đại vào Mỹ.', 'Gián tiếp viện trợ kinh tế cho Chính phủ Bảo Đại.', 'Từng bước dính líu vào chiến tranh Đông Dương.', 'Từng bước can thiệp vào chiến tranh Đông Dương.', 1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: Trực tiếp ràng buộc Chính phủ Bảo Đại vào Mỹ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_03', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Kế hoạch Đờ Lát Đờcátơri (1950) và kế hoạch Nava (1953) đã', 'làm thay đổi các kế hoạch quân sự trước đó của Việt Nam.', 'đẩy cuộc chiến tranh xâm lược của thực dân Pháp lên quy mô lớn.', 'mở đường cho Mỹ thay Pháp quyết định vấn đề chiến tranh.', 'thực hiện thành công và đạt được mục tiêu chiến lược đặt ra.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: đẩy cuộc chiến tranh xâm lược của thực dân Pháp lên quy mô lớn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_05', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Nội dung nào phản ánh khó khăn của Pháp trên lĩnh vực quân sự sau 8 năm tiến hành chiến tranh xâm lược Đông Dương?', 'Thường xuyên bị lực lượng du kích của Việt Nam quấy rối.', 'Mỹ cắt giảm bớt viện trợ vũ khí, phương tiện chiến tranh cho Pháp.', 'Quân số bị thiệt hại nặng, vùng chiếm đóng ngày càng được mở rộng.', 'Lâm vào thế bị động, mâu thuẫn giữa tập trung và phân tán lực lượng.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Lâm vào thế bị động, mâu thuẫn giữa tập trung và phân tán lực lượng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_06', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Năm 1953-1954, Pháp tập trung lực lượng cơ động chiến lược mạnh ở đồng bằng Bắc Bộ không nhằm mục tiêu nào sau đây?', 'Buộc lực lượng của ta phải phân tán để đối phó.', 'Thực hiện đòn tấn công quyết định khi có điều kiện.', 'Giành lại sự chủ động chiến lược trên chiến trường.', 'Xoay chuyển tình thế trên chiến trường Đông Dương.', 1, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là A: Buộc lực lượng của ta phải phân tán để đối phó.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_07', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Nội dung nào sau đây không phải mục đích của Pháp khi đề ra kế hoạch Na-va năm 1953?', 'Kết thúc chiến tranh ở Việt Nam trong danh dự.', 'Chuyển bại thành thắng trong vòng 18 tháng.', 'Xoay chuyển cục diện chiến tranh Đông Dương.', 'Biến Điện Biên Phủ thành pháo đài bất khả xâm phạm.', 4, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là D: Biến Điện Biên Phủ thành pháo đài bất khả xâm phạm.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_08', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Mỹ ủng hộ và giúp đỡ Pháp thực hiện kế hoạch Na-va ở Đông Dương năm 1953 nhằm mục đích cơ bản nào sau đây?', 'Giúp Pháp kết thúc chiến tranh Đông Dương trong danh dự.', 'Triển khai chiến lược toàn cầu ở Việt Nam và Đông Nam Á.', 'Ép Pháp kéo dài và mở rộng chiến tranh xâm lược Đông Dương.', 'Giúp Pháp giành quyền chủ động trên chiến trường chính Bắc Bộ.', 3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Ép Pháp kéo dài và mở rộng chiến tranh xâm lược Đông Dương.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_11', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Kế hoạch Đờ Lát Đờcátơri (1950) và kế hoạch Nava (1953) của thực dân Pháp đã', 'đưa cuộc chiến tranh xâm lược của Pháp thay đổi về bản chất.', 'thất bại kế hoạch đánh chắc thắng chắc của quân dân Việt Nam.', 'gây nhiều khó khăn cho cuộc kháng chiến của nhân dân Việt Nam.', 'giành được quyền chủ động chiến lược trên chiến trường chính Bắc Bộ.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: gây nhiều khó khăn cho cuộc kháng chiến của nhân dân Việt Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_12', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Thắng lợi của quân dân Việt Nam trong chiến dịch Hòa Bình (1951 - 1952), Tây Bắc(10/1952), Thượng Lào (4/1953) đã', 'thể hiện vai trò của chiến tranh du kích.', 'chấm dứt thời kỳ bị động trên chiến trường.', 'giữ vững quyền chủ động trên chiến trường.', 'làm thất bại kế hoạch viện trợ quân sự của Mỹ.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: giữ vững quyền chủ động trên chiến trường.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_15', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Hội nghị Bộ Chính trị Trung ương Đảng họp đề ra kế hoạch tác chiến Đông - Xuân 1953 - 1954 không nhằm mục đích nào?', 'Tiêu diệt một bộ phận sinh lực quân Pháp.', 'Giải phóng đất đai, giữ vững thế chủ động.', 'Buộc Pháp phải tập trung binh lực ở Điện Biên.', 'Buộc Pháp phải bị động phân tán lực lượng đối phó.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Buộc Pháp phải tập trung binh lực ở Điện Biên.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_17', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Địa điểm nào sau đây không phải là nơi quân Pháp tập trung binh lực trong những năm 1953 - 1954?', 'Đông Bắc.', 'Điện Biên Phủ.', 'Luông Pha Bang.', 'Đồng bằng Bắc Bộ.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Đông Bắc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_18', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Trong cuộc tiến công chiến lược Đông - Xuân 1953 - 1954, quân dân Việt Nam đã buộc Pháp phải phân tán binh lực ở', 'Điện Biên Phủ, Luông Pha-bang, Xê-nô, Mường Sài.', 'Điện Biên Phủ, Mường Sài, Xê-nô, Plây-ku, Kon Tum', 'Điện Biên Phủ, Xê-nô, Plây-ku, Luông Pha-bang, Tây Nguyên.', 'Điện Biên Phủ, Xê-nô, Luông Pha-bang, Mường Sài, Plây-ku.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Điện Biên Phủ, Xê-nô, Luông Pha-bang, Mường Sài, Plây-ku.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_19', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Trong Đông - Xuân 1953 - 1954, nơi nào tập trung binh lực lớn thứ hai của Pháp ở Đông Dương?', 'Đồng bằng Bắc Bộ.', 'Xê-nô.', 'Điện Biên Phủ.', 'Plây-ku.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Điện Biên Phủ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_21', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Nhận xét nào là đúng nhất về hậu phương của Việt Nam trong kháng chiến chống Pháp (1945 - 1954)?', 'Hậu phương của Việt Nam tập trung chủ yếu ở Việt Bắc.', 'Hậu phương ở Việt Nam có sự bất đối xứng với tiền tuyến.', 'Hậu phương luôn đứng phía sau tiền tuyến, cổ vũ tiền tuyến.', 'Hậu phương không có ranh giới rõ ràng phân biệt với tiền tuyến.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Hậu phương không có ranh giới rõ ràng phân biệt với tiền tuyến.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_22', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Nội dung nào là nhiệm vụ trọng tâm về giáo dục mà Chính phủ Việt Nam thực hiện trong những năm 1951 - 1953?', 'Đẩy mạnh phong trào bình dân học vụ.', 'Tiếp tục tiến hành cải cách giáo dục phổ thông.', 'Bước đầu tiến hành cải cách giáo dục phổ thông.', 'Đẩy mạnh xây dựng các trường đại học trên cả nước.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Tiếp tục tiến hành cải cách giáo dục phổ thông.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_23', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Sự kiện nào sau đây không phải là hoạt động chính trị tiêu biểu ở Việt Nam năm 1951?', 'Sự ra đời của Liên minh nhân dân Việt - Miên - Lào.', 'Đại hội thống nhất Mặt trận Việt Minh và Hội Liên Việt.', 'Đại hội Chiến sĩ thi đua và Cán bộ gương mẫu toàn quốc.', 'Đại hội đại biểu lần thứ II của Đảng Cộng sản Đông Dương.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Đại hội Chiến sĩ thi đua và Cán bộ gương mẫu toàn quốc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_24', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Tổ chức nào không tham gia trong cuộc kháng chiến toàn quốc chống thực dân Pháp (1946 - 1954)?', 'Hội Liên hiệp quốc dân Việt Nam.', 'Mặt trận Việt Nam độc lập đồng minh.', 'Mặt trận Liên hiệp quốc dân Việt Nam.', 'Mặt trận dân tộc giải phóng miền Nam Việt Nam.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Mặt trận dân tộc giải phóng miền Nam Việt Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_26', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Điểm mấu chốt trong kế hoạch Na-va 1953 - 1954 của Pháp là', 'phân tán lực lượng để đối phó với chiến dịch tiến công của ta.', 'tập trung lực lượng cơ động chiến lược mạnh ở đồng bằng Bắc Bộ.', 'tập trung quân ở Tây Bắc và Bắc Lào để giành quyền chủ động.', 'tấn công giành thắng lợi để buộc ta phải ký Hiệp định Giơnevơ.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: tập trung lực lượng cơ động chiến lược mạnh ở đồng bằng Bắc Bộ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_27', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Từ thu - đông 1953 - 1954, trên chiến trường Đông Dương, Pháp tập trung binh lực lớn nhất ở', 'Tây Bắc.', 'đồng bằng Bắc Bộ.', 'Thượng Lào.', 'Việt Bắc.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: đồng bằng Bắc Bộ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_29', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Các cuộc tấn công của quân dân Việt Nam trong Đông - Xuân 1953 - 1954 đã có tác động nào sau đây?', 'Quân Pháp đã phải rút khỏi chiến trường Lào và Bắc Đông Dương.', 'Quân Pháp đồng bằng Bắc Bộ suy yếu, không có khả năng chiến đấu.', 'Quân Pháp giành được thế chủ động ở Trung Bộ và Nam Đông Dương.', 'Pháp xây dựng Điện Biên Phủ thành tập đoàn cứ điểm mạnh ở Đông Dương.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Pháp xây dựng Điện Biên Phủ thành tập đoàn cứ điểm mạnh ở Đông Dương.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_32', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Na-va và nhiều nhà quân sự Pháp - Mỹ đều coi tập đoàn cứ điểm Điện Biên Phủ như', '“Nóc nhà ở khu vực Đông Dương”.', '“Một pháo đài bất khả xâm phạm”.', '“Bàn xoay quan trọng ở Đông Nam Á”.', '“Cứ điểm mạnh nhất ở Đông Dương”.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: “Một pháo đài bất khả xâm phạm”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_33', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Từ ngày 30/3 đến ngày 26/4, quân đội Việt Nam tấn công quân Pháp ở Điện Biên Phủ nhằm thực hiện mục tiêu nào sau đây?', 'Chặn con đường rút chạy của Pháp sang Trung Quốc.', 'Hạn chế việc tiếp viện của quân Pháp đến các cứ điểm.', 'Buộc Pháp phải thay đổi cách thức bố trí quân ở Điện Biên.', 'Mở rộng vùng giải phóng sang Bắc Lào và Bắc Đông Dương.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Chặn con đường rút chạy của Pháp sang Trung Quốc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_34', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Tập đoàn cứ điểm Điện Biên Phủ do Pháp xây dựng có điểm yếu nào sau đây?', 'Tiếp giáp với Trung Quốc và Lào nên dễ bị tấn công từ nhiều phía.', 'Nằm ở lòng chảo Điện Biên, địa hình bằng phẳng, máy bay khó hạ cánh.', 'Nằm xa hậu phương của Pháp, rất dễ cô lập khi đường bộ bị khống chế.', 'Nằm ở địa bàn trọng yếu, tập trung đông binh lực của quân đội Việt Nam.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Nằm xa hậu phương của Pháp, rất dễ cô lập khi đường bộ bị khống chế.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_35', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Tháng 12/1953, Bộ Chính trị Trung ương Đảng quyết định mở chiến dịch Điện Biên Phủ không nhằm mục đích nào sau đây?', 'Tiêu diệt bộ phận quan trọng sinh lực quân đội Pháp.', 'Giải phóng Tây Bắc, tạo điều kiện giải phóng Bắc Lào.', 'Buộc Pháp phải phân tán lực lượng đối phó với quân ta.', 'Đập tan tập đoàn cứ điểm mạnh nhất Đông Dương của Pháp.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Buộc Pháp phải phân tán lực lượng đối phó với quân ta.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_36', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Trong chiến dịch lịch sử Điện Biên Phủ năm 1954, quân đội Việt Nam mở màn tiến công tiêu diệt quân đội Pháp ở', 'cứ điểm Him Lam và toàn bộ phân khu Bắc.', 'cứ điểm Hồng Cúm và toàn bộ phân phu Nam.', 'sân bay Mường Thanh và phân khu Trung Tâm.', 'trung tâm chỉ huy của Pháp ở phân khu Trung tâm.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: cứ điểm Him Lam và toàn bộ phân khu Bắc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_37', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Phương châm tác chiến của bộ đội Việt Nam thực hiện trong chiến dịch Điện Biên Phủ năm 1954 là', '“Tích cực, chủ động, cơ động, linh hoạt”.', '“Đánh chắc thắng chắc”.', '“Thần tốc, bất ngờ, táo bạo, chắc thắng”.', '“Đánh nhanh thắng nhanh”.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: “Đánh chắc thắng chắc”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_38', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Trọng điểm tấn công của quân đội Việt Nam trong xuân hè năm 1954 là', 'toàn tỉnh Lai Châu.', 'đồng bằng Bắc Bộ.', 'căn cứ địa Việt Bắc.', 'sân bay Mường Thanh.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: sân bay Mường Thanh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_39', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Chiến thắng Điện Biên Phủ năm 1954 đã làm phá sản hoàn toàn kế hoạch nào của Pháp?', 'Rơ-ve.', 'Đờ Lát đơ Tát-xi-nhi.', 'Na-va.', 'Đờ Ca-xtơ-ri.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Na-va.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_41', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Chiến thắng Điện Biên Phủ là đỉnh cao của Tiến công chiến lược Đông - Xuân 1953 - 1954 vì', 'giải phóng hoàn toàn đất nước, đi lên xây dựng chủ nghĩa xã hội.', 'bước đầu làm phá sản kế hoạch quân sự Na-va của thực dân Pháp.', 'đã kết thúc hoàn toàn cuộc chiến tranh xâm lược của thực dân Pháp.', 'đập tan hoàn toàn kế hoạch Na-va, đánh bại ý chí xâm lược của Pháp.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: đập tan hoàn toàn kế hoạch Na-va, đánh bại ý chí xâm lược của Pháp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_45', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Trong cuộc kháng chiến chống thực dân Pháp (1945 - 1954) của nhân dân Việt Nam, lực lượng vũ trang giữ vai trò', 'quyết định thắng lợi.', 'xung kích, tiên phong.', 'hỗ trợ lực lượng chính trị.', 'cổ vũ quần chúng nhân dân.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: quyết định thắng lợi.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_46', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Quyền dân tộc cơ bản được ghi nhận trong Hiệp định Giơ-ne-vơ năm 1954 là', 'Độc lập, thống nhất, quyền lựa chọn con đường phát triển phù hợp.', 'Độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ ở Đông Dương.', 'Quyền tự chủ, dân tộc tự quyết và toàn vẹn lãnh thổ ở Đông Dương.', 'Độc lập, chủ quyền và không can thiệp vào công việc nội bộ của nhau.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ ở Đông Dương.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_47', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Theo Hiệp định Giơ-ne-vơ năm 1954, Việt Nam sẽ thống nhất đất nước bằng con đường', 'thương thuyết hòa bình ở hai miền.', 'Trưng cầu ý kiến của nhân dân.', 'Tổng tuyển cử tự do trong cả nước.', 'Hiệp thương chính trị giữa hai miền.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Tổng tuyển cử tự do trong cả nước.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_48', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Hiệp định Giơ-ne-vơ năm 1954 về kết thúc chiến tranh lập lại hòa bình ở Đông Dương không có nội dung nào sau đây?', 'Trách nhiệm thi hành Hiệp định thuộc về các bên kí kết và người kế tục.', 'Việt Nam sẽ thống nhất đất nước bằng cuộc Tổng tuyển cử tự do (7/1956).', 'Hai bên tạm thời ngừng bắn trong hai năm để đi đến một giải pháp hòa bình.', 'Pháp cam kết tôn trọng các quyền dân tộc cơ bản của ba nước Đông Dương.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Hai bên tạm thời ngừng bắn trong hai năm để đi đến một giải pháp hòa bình.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_50', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Ủy ban quốc tế sẽ giám sát việc thi hành Tổng tuyển cử tự do ở Việt Nam năm 1956 bao gồm những nước nào sau đây?', 'Ấn Độ, Ca-na-da, Ba Lan.', 'In-đô-nê-xia, Ấn Độ, Ba Lan.', 'In-đô-nê-xia, Ấn Độ, Ca-na-da.', 'Ca-na-da, Ấn Độ, Nam Tư.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Ấn Độ, Ca-na-da, Ba Lan.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_51', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Hiệp định Giơ-ne-vơ năm 1954 về kết thúc chiến tranh và lập lại hòa bình ở Đông Dương có ý nghĩa nào sau đây?', 'Tác động trực tiếp tới phong trào giải phóng dân tộc ở châu Phi.', 'Góp phần chấm dứt chiến tranh xâm lược của Pháp ở Đông Dương.', 'Pháp phải rút hết quân đội ra khỏi ba nước Đông Dương năm 1954.', 'Mỹ thất bại trong âm mưu viện trợ cho Pháp xâm lược Đông Dương.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Góp phần chấm dứt chiến tranh xâm lược của Pháp ở Đông Dương.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_52', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Một trong những hoạt động xây dựng hậu phương kháng chiến chống Pháp của nhân dân Việt Nam (1945 - 1954) là', 'xây dựng nền kinh tế thị trường.', 'xóa bỏ kinh tế tập trung, bao cấp.', 'tiến hành phổ cập giáo dục tiểu học.', 'tiếp tục phong trào bình dân học vụ.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: tiếp tục phong trào bình dân học vụ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_54', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Nội dung nào không phải là tình thế của quân Pháp sau khi quân dân Việt Nam mở các cuộc tấn công Đông Xuân 1953 - 1954?', 'Phân tán lực lượng.', 'Bị động đối phó với ta.', 'Lún sâu vào thế phòng ngự.', 'Phụ thuộc vào quân đội Mỹ.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Phân tán lực lượng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_57', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Nội dung nào sau đây phải ánh nguyên nhân quyết định thắng lợi của cuộc kháng chiến chống Pháp (1945 - 1954)?', 'Tình đoàn kết chiến đấu của nhân dân ba nước Đông Dương và thế giới.', 'Nhân dân ta có truyền thống yêu nước, ý chí đấu tranh kiên cường bất khuất.', 'Sự lãnh đạo sáng suốt của Đảng Cộng sản đứng đầu là Chủ tịch Hồ Chí Minh.', 'Toàn Đảng, toàn dân Việt Nam đồng lòng nhất trí tiến hành Tổng khởi nghĩa.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Sự lãnh đạo sáng suốt của Đảng Cộng sản đứng đầu là Chủ tịch Hồ Chí Minh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
