INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_70', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Nhận định nào là đúng nhất về mối quan hệ giữa chiến thắng Điện Biên Phủ với Hiệp định Giơnevơ 1954 về Đông Dương?', 'Thắng lợi ở Điện Biên Phủ buộc Pháp ký kết Hiệp định Giơnevơ.', 'Hiệp định Giơnevơ là điều kiện để giành thắng lợi ở Điện Biên Phủ.', 'Thắng lợi ở Điện Biên Phủ buộc các nước lớn mở hội nghị Giơnevơ.', 'Thắng lợi của Hiệp định Giơnevơ quyết định thắng lợi Điện Biên Phủ.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Thắng lợi ở Điện Biên Phủ buộc Pháp ký kết Hiệp định Giơnevơ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
