INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_77', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Nội dung nào không phải là nguyên nhân khách quan dẫn tới thắng lợi của cuộc kháng chiến chống Pháp (1945 - 1954)?', 'Thắng lợi của phong trào giải phóng dân tộc ở châu Phi.', 'Sự đoàn kết liên minh chiến đấu của ba nước Đông Dương.', 'Sự ủng hộ của nhân dân Pháp và loài người tiến bộ trên thế giới.', 'Sự ủng hộ và giúp đỡ của các nước xã hội chủ nghĩa trên thế giới.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Thắng lợi của phong trào giải phóng dân tộc ở châu Phi.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
