INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_80', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Sau 8 năm tiến hành chiến trang xâm lược Việt Nam (1945 - 1953), Pháp không gặp phải khó khăn nào sau đây?', 'Pháp lâm vào mâu thuẫn giữa tập trung và phân tán lực lượng.', 'Quâng Pháp lâm vào thế bị động trên chiến trường chính Bắc Bộ.', 'Vùng chiếm đóng của Pháp ở Đông Dương ngày càng bị thu hẹp.', 'Những giải pháp ngoại giao của Pháp đều không thu được kết quả.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Những giải pháp ngoại giao của Pháp đều không thu được kết quả.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_81', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Kế hoạch Na-va của Pháp khi mới ra đời năm 1953 đã hàm chứa yếu tố thất bại vì', 'ra đời trong khó khăn bị động nhưng mục tiêu và tham vọng lớn.', 'ngân sách chiến tranh trống rỗng, quân đội Pháp không còn tinh thần.', 'bị mất quyền chủ động chiến lược trên toàn chiến trường Đông Dương.', 'phong trào phản đối chiến tranh xâm lược Việt Nam ở Pháp dâng cao.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: ra đời trong khó khăn bị động nhưng mục tiêu và tham vọng lớn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_83', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Chiến thắng nào của quân dân Việt Nam đã làm phá sản hoàn toàn kế hoạch Na-va?', 'Chiến thắng Việt Bắc thu - đông 1947.', 'Chiến thắng Điện Biên Phủ năm 1954.', 'Chiến thắng Biên giới thu - đông 1950.', 'Chiến thắng Đông - Xuân 1953 - 1954.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Chiến thắng Điện Biên Phủ năm 1954.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_85', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Cuộc đấu tranh trên bàn Hội nghị Giơ-ne-vơ Việt Nam thắng lợi chưa triệt để là do', 'Liên Xô và các nước dân chủ chưa ủng hộ Việt Nam.', 'Mỹ can thiệp và dính líu vào cuộc chiến tranh của Pháp.', 'Việt Nam chưa có thắng lợi quyết chiến trên chiến trường.', 'Việt Nam chưa đánh bại hoàn toàn quân Pháp về quân sự.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Việt Nam chưa đánh bại hoàn toàn quân Pháp về quân sự.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
