INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_91', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Cuộc kháng chiến chống thực dân Pháp xâm lược của nhân dân Đông Dương (1953 - 1954) kết thúc bằng giải pháp nào?', 'Ngoại giao.', 'Quân sự.', 'Kinh tế.', 'Văn hóa.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Ngoại giao.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_93', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Hiệp định Giơ-ne-vơ năm 1954 về Đông Dương có điểm hạn chế vì ở Việt Nam', 'chỉ giải phóng miền Bắc.', 'chỉ giải phóng miền Nam.', 'không có vùng giải phóng.', 'chỉ giải phóng Điện Biên Phủ.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: chỉ giải phóng miền Bắc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_94', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Quyền dân tộc cơ bản của nhân dân Việt Nam lần đầu tiên được hiệp định quốc tế nào công nhận?', 'Hiệp định Sơ bộ năm 1946.', 'Hiệp định I-an-ta năm 1945.', 'Hiệp định Pa-ri năm 1973.', 'Hiệp định Giơ-ne-vơ năm 1954.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Hiệp định Giơ-ne-vơ năm 1954.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_95', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Chiến thắng nào của quân dân Việt Nam đã đánh bại hoàn toàn ý chí xâm lược của Pháp?', 'Hiệp định Giơ-ne-vơ năm 1954.', 'Chiến thắng Điện Biên Phủ năm 1954.', 'Chiến thắng Biên giới thu - đông 1950.', 'Chiến cuộc Đông - Xuân 1953 - 1954.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Chiến thắng Điện Biên Phủ năm 1954.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_96', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Kế hoạch quân sự cuối cùng của Pháp thực hiện trong chiến tranh xâm lược Đông Dương (1945 - 1954) là', 'kế hoạch Đờ Ca-xtơ-ri.', 'kế hoạch Na-va.', 'kế hoạch Đờ Lát đơ Tát-xi-nhi.', 'kế hoạch Rơ-ve.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: kế hoạch Na-va.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_97', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Chiến dịch nào quân dân Việt Nam chủ động mở cuộc tấn công đầu tiên đánh vào các cứ điểm của Pháp giai đoạn 1945 - 1954?', 'Chiến dịch Thượng Lào năm 1953.', 'Chiến dịch Việt Bắc thu - đông 1947.', 'Chiến dịch Biên giới thu - đông 1950.', 'Chiến dịch Điện Biên Phủ năm 1954.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Chiến dịch Biên giới thu - đông 1950.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_100', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Nội dung nào sau đây phản ánh khó khăn chủ quan của quân và dân Việt Nam khi mở chiến dịch Điện Biên Phủ năm 1954?', 'Điện Biên Phủ là tập đoàn cứ điểm mạnh nhất Đông Dương của Pháp.', 'Điện Biên Phủ ở vùng rừng núi, không phải chiến trường sở trường của ta.', 'Các nước xã hội chủ nghĩa chưa ủng hộ Việt Nam kháng chiến chống Pháp.', 'Điện Biên Phủ xa hậu phương Việt Bắc, khó khăn về tiếp tế cho chiến dịch.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Điện Biên Phủ xa hậu phương Việt Bắc, khó khăn về tiếp tế cho chiến dịch.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B15_103', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B15'), 'LS9_KNTT_B15', 'Hiệp định Giơ-ve-vơ 1954 về Đông Dương còn có điểm hạn chế vì được kí kết trong bối cảnh nào sau đây?', 'So sánh lực lượng trên chiến trường có lợi cho Pháp.', 'Việt Nam chưa giành được thắng lợi quân sự quyết định.', 'Việt Nam chưa nhận được sự ủng hộ của các nước lớn.', 'Nhiều vấn đề của quốc tế do các nước lớn quyết định.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Nhiều vấn đề của quốc tế do các nước lớn quyết định.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_01', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Đại hội đại biểu lần thứ III của Đảng Lao động Việt Nam (9/1960) đã chỉ rõ', 'ý nghĩa của tổng tuyển cử và thống nhất đất nước.', 'vị trí, vai trò của cách mạng từng miền Bắc, Nam.', 'đặc trưng trong con đường đi lên chủ nghĩa xã hội.', 'nhiệm vụ chống chiến tranh phá hoại miền Bắc của Mĩ.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: vị trí, vai trò của cách mạng từng miền Bắc, Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_02', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Đại hội đại biểu lần thứ III của Đảng Lao động Việt Nam (9/1960) thông qua nội dung nào sau đâu?', 'Phương pháp thống nhất đất nước', 'Nhiệm vụ cải tạo xã hội chủ nghĩa.', 'Kế hoạch nhà nước 5 năm (1961 - 1965).', 'Báo cáo Bàn về cách mạng Việt Nam.', 3, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là C: Kế hoạch nhà nước 5 năm (1961 - 1965).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_03', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Trong những năm 1954 - 1964, nhân dân miền Bắc không thực hiện nhiệm vụ trọng tâm nào sau đây?', 'Thực hiện kế hoạch Nhà nước 5 năm (1961 - 1965).', 'Đoàn kết với Campuchia chống chiến tranh đặc biệt.', 'Cải cách ruộng đất, hàn gắn vết thương chiến tranh.', 'Khôi phục và phát triển kinh tế, chi viện cho tiền tuyến.', 2, 20, 'WARM_UP', 'EASY', 'Đáp án đúng là B: Đoàn kết với Campuchia chống chiến tranh đặc biệt.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
