INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_11', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Phong trào “Đồng khởi” (1959 - 1960) của nhân dân miền Nam diễn ra tiêu biểu ở', 'Ninh Thuận.', 'Bình Định.', 'Bến Tre.', 'Quảng Ngãi.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Bến Tre.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
