INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_14', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Sau khi được thành lập, Ủy ban Nhân dân tự quản ở Bến Tre đã thi hành chính sách tích cực nào sau đây?', 'Phát triển kinh tế, cải tạo xã hội chủ nghĩa.', 'Mở những lớp dạy chữ Quốc ngữ, xóa bỏ giặc dốt.', 'Tiến hành tổng tuyển cử để xây dựng chính quyền.', 'Tịch thu ruộng đất của cường hào chia cho nông dân.', 4, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là D: Tịch thu ruộng đất của cường hào chia cho nông dân.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_15', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Sau phong trào “Đồng khởi” (1959 - 1960), lực lượng chính trị của cách mạng miền Nam Việt Nam được tập hợp trong', 'Quân giải phóng miền Nam Việt Nam.', 'Trung ương cục miền Nam Việt Nam.', 'Mặt trận Dân tộc giải phóng miền Nam Việt Nam.', 'Chính phủ lâm thời Cộng hòa miền Nam Việt Nam.', 3, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là C: Mặt trận Dân tộc giải phóng miền Nam Việt Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_16', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Nội dung nào sau đây phản ánh ý nghĩa của phong trào “Đồng khởi” (1959 - 1960) ở miền Nam Việt Nam?', 'Đánh bại hoàn toàn chiến lược tìm và diệt của Mĩ.', 'Giáng đòn nặng nề vào chính sách thực dân mới của Mĩ.', 'Đánh tan âm mưa dùng người Việt đánh người Việt của Mĩ.', 'Đẩy chính quyền Sài Gòn lâm vào khủng hoảng triền miên.', 2, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là B: Giáng đòn nặng nề vào chính sách thực dân mới của Mĩ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_17', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Trong những năm 1961 - 1965, Mĩ thực hiện loại hình chiến tranh nào ở miền Nam Việt Nam Việt Nam?', '“Chiến tranh đặc biệt”.', '“Chiến tranh cục bộ”.', '“Chiến tranh đơn phương”.', '“Việt Nam hóa chiến tranh”.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: “Chiến tranh đặc biệt”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_18', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Từ đầu năm 1961, Mĩ chuyển sang thực hiện chiến lược “Chiến tranh đặc biệt” ở miền Nam Việt Nam vì', 'hình thức thống trị bằng chính quyền tay sai độc tài thất bại.', 'Mĩ muốn đưa quân đội sang miền Nam tham chiến trực tiếp.', 'Mĩ muốn cứu vãn cho sự thất bại ở chiến trường Triều Tiên.', 'chính quyền và quân đội Sài Gòn không đảm nhận nhiệm vụ.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: hình thức thống trị bằng chính quyền tay sai độc tài thất bại.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_19', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Chiến lược “Chiến tranh đặc biệt” của Mĩ ở miền Nam Việt Nam nhằm thực hiện âm mưu trực tiếp nào sau đây?', 'Dùng người Việt đánh người Việt.', 'Áp đảo quân chủ lực của Việt Nam.', 'Biến Việt Nam thành thuộc địa kiểu mới.', 'Dùng người Đông Dương đánh người Đông Dương.', 1, 20, 'PRACTICE', 'MEDIUM', 'Đáp án đúng là A: Dùng người Việt đánh người Việt.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_25', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', '“Quốc sách” để Mĩ và chính quyền Sài Gòn nhằm bình định miền Nam Việt Nam trong Chiến tranh đặc biệt (1961 - 1965) là', 'Dồn dân lập “Ấp chiến lược”.', 'chiến dịch “tràn ngập lãnh thổ”.', 'các cuộc hành quân tìm diệt và bình định.', 'chiến thuật “Trực thăng vận, thiết xa vận”.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Dồn dân lập “Ấp chiến lược”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_28', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Phong trào “Đồng khởi” (1959 - 1960) ở miền Nam Việt Nam không có ý nghĩa nào sau đây?', 'Đưa cách mạng miền Nam chuyển sang thế tiến công.', 'Làm lung lay tận gốc chính quyền tay sai Ngô Đình Diệm.', 'Đánh dấu bước phát triển nhảy vọt của cách mạng miền Nam.', 'Đánh bại hoàn toàn quốc sách bình định của chính quyền Diệm.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Đánh bại hoàn toàn quốc sách bình định của chính quyền Diệm.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_29', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Mặt trận Dân tộc giải phóng miền Nam Việt Nam ra đời năm 1960 nhằm mục đích nào sau đây?', 'Thực hiện đàm phàn tay đôi với Mĩ và tay sai.', 'Đoàn kết toàn dân, đấu tranh chống Mĩ và tay sai.', 'Lãnh đạo cách mạng dân tộc dân chủ nhân dân ở miền Nam.', 'Đấu tranh chống các loại hình chiến tranh xâm lược của Mĩ.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Đoàn kết toàn dân, đấu tranh chống Mĩ và tay sai.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_30', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Thắng lợi to lớn của nhân dân miền Nam trong phong trào “Đồng khởi” (1959 - 1960) là', 'Mĩ phải chuyển từ đánh nhanh thắng nhanh sang đánh lâu dài.', 'buộc Mĩ phải tiến hành “Mĩ hóa” chiến tranh xâm lược miền Nam.', 'phá vỡ chính sách bình đinh miền Nam và phá hoại miền Bắc của Mĩ.', 'phá vỡ từng mảng lớn bộ máy cai trị của Mĩ – Diệm ở nhiều thôn xã.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: phá vỡ từng mảng lớn bộ máy cai trị của Mĩ – Diệm ở nhiều thôn xã.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_32', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Kế hoạch Nhà nước 5 năm (1961 - 1965) ở miền Bắc phải tạm dừng năm 1964 vì', 'các nhiệm vụ đã hoàn thành trước thời hạn.', 'Đảng có chủ trương chuyển hướng chỉ đạo.', 'Mĩ gây ra cuộc chiến tranh phá hoại lần thứ nhất.', 'đã xây dựng thành công cơ sở của chủ nghĩa xã hội.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Mĩ gây ra cuộc chiến tranh phá hoại lần thứ nhất.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_33', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Trong chiến lược “Chiến tranh đặc biệt” (1961 - 1965) ở miền Nam Việt Nam, Mĩ sử dụng chiến thuật nào?', '“Trực thăng vận, thiết xa vận”.', '“Thà giết nhầm còn hơn bỏ sót”.', '“Tiêu diệt cộng sản không thương tiếc”.', '“Tìm diệt” và “Bình định” trên toàn miền Nam.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: “Trực thăng vận, thiết xa vận”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_36', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Những thắng lợi trên mặt trận quân sự của quân dân miền Nam trong Đông - Xuân 1964 - 1965 có ý nghĩa nào sau đây?', 'Buộc Mỹ phải thay đổi mục tiêu chiến lược của “Chiến tranh đặc biệt”.', 'Đánh dấu sự sụp đổ hoàn toàn của chiến lược “Chiến tranh đặc biệt”.', 'Chứng tỏ quân dân miền Nam có thể đánh bại quân đội viễn chinh Mỹ.', 'Đánh dấu sự sụp đổ của chiến tranh xâm lược thực dân kiểu mới của Mĩ.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Đánh dấu sự sụp đổ hoàn toàn của chiến lược “Chiến tranh đặc biệt”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_37', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Chiến lược “Chiến tranh đặc biệt” của Mĩ (1961 - 1965) ở miền Nam đã bị phá sản hoàn toàn vì', 'mâu thuẫn gay gắt giữa Mĩ và chính quyền Việt Nam Cộng hoà.', 'Quân đội Sài Gòn không có khả năng tác chiến trên chiến trường.', 'quân dân miền Nam giành thắng lợi trên mặt trận quân sự, chính trị.', '“Ấp chiến lược” - xương sống của “Chiến tranh đặc biệt” bị bẻ gãy.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: quân dân miền Nam giành thắng lợi trên mặt trận quân sự, chính trị.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_39', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Bản chất của chiến tranh xâm lược thực dân kiểu mới của Mĩ thực hiện ở miền Nam Việt Nam không phải là', 'dựng nên chính quyền tay sai Ngô Đình Diệm để cai trị miền Nam.', 'viện trợ cho chính quyền Sài Gòn để tiến hành khai thác thuộc địa.', 'tăng cường viện trợ kinh tế, tài chính, quân sự cho chính quyền Sài Gòn.', 'sử dụng quân đội Sài Gòn là lực lượng tác chiến chính trên chiến trường.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: viện trợ cho chính quyền Sài Gòn để tiến hành khai thác thuộc địa.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_40', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Tính đến năm 1964, từng mảng lớn “Ấp chiến lược” của Mĩ và chính quyền Sài Gòn bị phá vỡ chứng tỏ nội dung nào sau đây?', 'Chính quyền Sài Gòn không thể bình định được miền Nam.', 'Phong trào đấu tranh binh vận phát triển mạnh ở miền Nam.', 'Chiến lược “Chiến tranh đặc biệt” đứng trước nguy cơ phá sản.', 'Mỹ không thực hiện được cuộc chiến tranh chính quy ở miền Nam.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Chính quyền Sài Gòn không thể bình định được miền Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_41', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Chiến thắng Ấp Bắc (01/1963) chứng tỏ quân và dân miền Nam Việt Nam có khả năng', 'đánh bại quân đội Mĩ và quân đồng minh của Mĩ.', 'đánh bại cố vấn Mĩ trong “Chiến tranh đặc biệt”.', 'đánh bại quân đội Sài Gòn trong “Chiến tranh đặc biệt”.', 'đánh bại chiến tranh xâm lược thực dân kiểu mới của Mĩ.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: đánh bại quân đội Sài Gòn trong “Chiến tranh đặc biệt”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_42', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Trong chiến lược “Chiến tranh đặc biệt” (1961 - 1965), quân đội Sài Gòn có vai trò nào sau đây?', 'Hỗ trợ quân viễn chinh Mĩ chiến đấu.', 'Mở rộng chiến tranh ra toàn Đông Dương.', 'Xung kích hỗ trợ chiến thuật “Thiết xa vận”.', 'Lực lượng tác chiến chính trên chiến trường.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Lực lượng tác chiến chính trên chiến trường.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_43', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Chiến thắng Bình Giã (12/1964) của quân và dân miền Nam Việt Nam có ý nghĩa nào sau đây?', 'Buộc Mỹ phải đề ra chiến lược Chiến tranh cục bộ.', 'Mở đầu cho phong trào đánh Mĩ trên toàn miền Nam.', 'Làm phá sản hoàn toàn chiến lược Chiến tranh đặc biệt.', 'Chiến lược “Chiến tranh đặc biệt” về cơ bản bị phá sản.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Chiến lược “Chiến tranh đặc biệt” về cơ bản bị phá sản.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_47', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Chiến thắng Ấp Bắc (1963) trong chiến lược “Chiến tranh đặc biệt” không có ý nghĩa nào sau đây?', 'Mở ra khả năng đánh thắng quân đội Sài Gòn.', 'Mở ra cao trào “Thi đua Ấp Bắc, giết giặc lập công”.', 'Phá vỡ ách kìm kẹp miền Nam của chính quyền Sài Gòn.', 'Bước đầu đánh bại chiến thuật “Trực thăng vận, thiết xa vận”.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Phá vỡ ách kìm kẹp miền Nam của chính quyền Sài Gòn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_49', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Để biến miền Nam Việt Nam thành thuộc địa kiểu mới, thành căn cứ quân sự ở Đông Dương và Đông Nam Á, Mỹ đã', 'giúp đỡ nhân dân miền Nam Việt Nam khắc phục hậu quả của chiến tranh.', 'dựng lên chính quyền Ngô Đình Diệm, âm mưu chia cắt lâu dài Việt Nam.', 'thực hiện các điều khoản của Hiệp định Giơnevơ mà Pháp chưa thi hành.', 'viện trợ cho Pháp để kéo dài và quốc tế hóa chiến tranh Đông Dương .', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: dựng lên chính quyền Ngô Đình Diệm, âm mưu chia cắt lâu dài Việt Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_50', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Cuộc đấu tranh chống và phá “ấp chiến lược” của nhân dân miền Nam trong kháng chiến chống Mỹ đi đôi với', 'xây dựng làng chiến đấu.', 'biểu tình đòi Mỹ rút quân.', 'chi viện cho chiến trường Lào.', 'đấu tranh trên mặt trận ngoại giao.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: xây dựng làng chiến đấu.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_51', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Cách mạng miền Nam Việt Nam chuyển sang thời kỳ tiến hành chiến tranh giải phóng từ sau sự kiện nào?', 'Phong trào Đồng khởi (1959 - 1960).', 'Hiệp định Giơnevơ năm 1954 được ký kết.', 'Mỹ dựng lên chính quyền tay sai Ngô Đình Diệm.', 'Chiến tranh đặc biệt (1961 - 1965) thất bại.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Phong trào Đồng khởi (1959 - 1960).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_53', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Cao trào cách mạng nào diễn ra mạnh mẽ trên toàn miền Nam trong chiến lược “Chiến tranh đặc biệt”?', '“Thi đua Ấp Bắc, giết giặc lập công”.', '“Tìm Mĩ mà đánh, lùng ngụy mà diệt”.', '“Đánh cho Mĩ cút, đánh cho ngụy nhào”.', '“Quyết tâm đánh thắng giặc Mĩ xâm lược”.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: “Thi đua Ấp Bắc, giết giặc lập công”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B16_54', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B16'), 'LS9_KNTT_B16', 'Nhận xét nào không đúng về “Ấp chiến lược” do Mĩ và chính quyền Sài Gòn xây dựng ở miền Nam Việt Nam (1961 - 1965)?', 'Được xây dựng, canh phòng nghiêm ngặt nhằm dồn dân sống tập trung.', 'Là căn cứ quân sự của Mỹ để đàn áp đấu tranh chính trị của nhân dân ta.', 'Tác nhân dân ra khỏi cách mạng rồi đẩy họ đến chỗ chống phá cách mạng.', 'Một kiểu trại tập trung tại những vùng do chính quyền Sài Gòn kiểm soát.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Là căn cứ quân sự của Mỹ để đàn áp đấu tranh chính trị của nhân dân ta.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
