INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_53', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Từ 1969 - 1973, Mĩ thực hiện chiến lược nào sau đây nhằm mở rộng phạm vi chiến tranh hơn nữa?', 'Chiến tranh đặc biệt.', 'Đông Dương hóa chiến tranh.', 'Chiến tranh phá hoại.', 'Việt Nam hóa chiến tranh.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Đông Dương hóa chiến tranh.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_54', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Lực lượng chủ yếu trong chiến lược “Việt Nam hóa chiến tranh” (1969 - 1973) của Mĩ ở miền Nam Việt Nam là', 'quân viễn chinh Mĩ có sự hỗ trợ của quân đội Sài Gòn.', 'quân viễn chinh Mĩ, quân chư hầu và quân đội Sài Gòn.', 'quân đồng minh của Mĩ, lính Âu - Phi, quân đội Sài Gòn.', 'quân đội Sài Gòn có sự hỗ trợ của hỏa lực không quân Mĩ.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: quân đội Sài Gòn có sự hỗ trợ của hỏa lực không quân Mĩ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_56', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Nội dung nào là điểm tương đồng về nhiệm vụ lịch sử của ba nước Việt Nam, Lào, Cam-pu-chia giai đoạn 1970 - 1975?', 'Tiến hành cuộc kháng chiến chống thực dân Pháp.', 'Thực hiện chính sách đối ngoại hòa bình, trung lập.', 'Tiến hành cuộc đấu tranh để bảo vệ độc lập dân tộc.', 'Xây dựng đất nước phát triển theo con đường XHCN.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Tiến hành cuộc đấu tranh để bảo vệ độc lập dân tộc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_58', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Bộ Chính trị quyết định mở cuộc Tổng tiến công và nổi dậy xuân Mậu Thân 1968 nhằm mục đích nào sau đây?', 'Ngăn cản chiến lược Việt Nam hóa chiến tranh.', 'Buộc Mĩ phải ngừng ném bom bắn phá miền Bắc.', 'Buộc Mĩ phải ký Hiệp định Pari, rút quân về nước.', 'Đánh đòn mạnh vào chính quyền và quân đội Sài Gòn.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Đánh đòn mạnh vào chính quyền và quân đội Sài Gòn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_61', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Ngay sau khi ra đời, Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam đã đạt được thành tích nổi bật nào sau đây?', 'Xoá bỏ được tàmanhr hương .', 'Đã hoàn thiện bộ máy chính quyền từ Trung ương tới địa phương.', 'Lãnh đạo nhân dân miền Nam đấu tranh chống Mĩ giành thắng lợi.', 'Được nhiều nước trên thế giới công nhận và đặt quan hệ ngoại giao.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Được nhiều nước trên thế giới công nhận và đặt quan hệ ngoại giao.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_62', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Cuộc hành quân mang tên “Lam Sơn - 719” (1971) của Mĩ và quân đội Sài Gòn nhằm chiếm giữ', 'đường 14 - Phước Long.', 'đường Hồ Chí Minh trên bộ.', 'đường 9 - Nam Lào.', 'căn cứ quân sự ở Chu Lai.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: đường 9 - Nam Lào.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_63', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Nội dung nào sau đây phản ánh thủ đoạn của Mĩ khi thực hiện chiến lược “Đông Dương hóa chiến tranh” (1969 - 1973)?', 'Lợi dụng mâu thuẫn Trung - Xô để cô lập cách mạng Đông Dương.', 'Dựng lên chính quyền tay sai Ngô Đình Diệm ở miền Nam Việt Nam.', 'Sử dụng quân đội Sài Gòn lật đổ chính phủ Xi-ha-núc ở Cam-pu-chia.', 'Sử dụng quân đội Lào sang tham chiến ở Việt Nam để lập chính quyền mới.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Lợi dụng mâu thuẫn Trung - Xô để cô lập cách mạng Đông Dương.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
