INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_67', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Nội dung nào không phải là mục đích phong trào đấu tranh chính trị của nhân dân miền Nam những năm 1969 - 1973?', 'Chống “bình định”.', 'Đòi cải cách ruộng đất.', 'Đòi quyền tự do dân chủ.', 'Phá “Ấp chiến lược”.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Đòi cải cách ruộng đất.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_73', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Trong Chiến tranh cục bộ, Mĩ không mở cuộc hành quân “Tìm diệt” và “Bình định” nào sau đây?', 'Cuộc chiến tranh phá hoại miền Bắc lần thứ nhất (1965 - 1968).', 'Cuộc tấn công vào Đông Nam Bộ và Khu V (mùa khô 1965 - 1966).', 'Cuộc hành quân tấn công vào thôn Vạn Tường - Quảng Ngãi (8/1965).', 'Cuộc tấn công vào chiến khu Dương Minh Châu (mùa khô 1966 - 1967).', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Cuộc chiến tranh phá hoại miền Bắc lần thứ nhất (1965 - 1968).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
