INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_76', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Thủ đoạn của Mĩ trong chiến lược “Việt Nam hóa chiến tranh” và “Đông Dương hóa chiến tranh” (1969 - 1973) không phải là', 'sử dụng quân đội Sài Gòn tác chiến chính trên chiến trường.', 'mở các chiến dịch tấn công nhằm tạo ra chiến tuyến rõ ràng.', 'đàm phán với Việt Nam ở Hội nghị Pa-ri để rút quân về nước.', 'sử dụng quân đội Sài Gòn sang xâm lược Cam-pu-chia và Lào.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: mở các chiến dịch tấn công nhằm tạo ra chiến tuyến rõ ràng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_77', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Trong cuộc Tiến công chiến lược năm 1972, quân và dân Việt Nam mở cuộc tấn công vào những hướng quan trọng ở', 'Quảng Trị, Tây Nguyên, Tây Nam Bộ.', 'Đông Nam Bộ, Quảng Trị, Đà Nẵng.', 'Quảng Trị, Tây Nguyên, Đông Nam Bộ.', 'Đông Nam Bộ, Tây Nguyên, Liên Khu V.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Quảng Trị, Tây Nguyên, Đông Nam Bộ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_79', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Thắng lợi của quân dân Việt Nam trong cuộc Tiến công chiến lược năm 1972 đã buộc Mĩ phải tuyên bố', '“Mĩ hóa” chiến tranh xâm lược.', '“phi Mĩ hóa” chiến tranh xâm lược.', '“Mĩ hóa” trở lại chiến tranh xâm lược.', 'chấm dứt chiến tranh phá hoại miền Bắc.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: “Mĩ hóa” trở lại chiến tranh xâm lược.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_80', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Nội dung nào sau đây không phản ánh nhiệm vụ của nhân dân miền Bắc Việt Nam trong những năm 1969 - 1971?', 'Phát triển kinh tế, văn hóa, xã hội.', 'Chi viện cho miền Nam, Lào và Campuchia.', 'Khắc phục hậu quả của chiến tranh phá hoại.', 'Chống chiến tranh phá hoại lần thứ hai của Mĩ', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Chống chiến tranh phá hoại lần thứ hai của Mĩ') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_85', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Cuộc tập kích không quân bằng máy bay B52 của Mĩ (12/1972) tập trung chủ yếu tàn phá', 'Hà Nội, Huế.', 'Hà Nội, Đà Nẵng.', 'Hà Nội, Hải Phòng.', 'Hà Nội, Nam Định.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Hà Nội, Hải Phòng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_87', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Nội dung nào sau đây phản ánh ý nghĩa của Hiệp định Pa-ri về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam năm 1973?', 'Mở ra kỉ nguyên độc lập, thống nhất, đi lên chủ nghĩa xã hội.', 'Hoàn thành sự nghiệp “Đánh cho Mĩ cút, đánh cho ngụy nhào”.', 'Mĩ công nhận các quyền dân tộc cơ bản của ta, rút quân về nước.', 'Là thắng lợi của sự kết hợp giữa đấu tranh kinh tế, chính trị, ngoại giao.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Là thắng lợi của sự kết hợp giữa đấu tranh kinh tế, chính trị, ngoại giao.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_90', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Nhận xét nào sau đây là đúng về nội dung của Hiệp định Pa-ri năm 1973 về Việt Nam?', 'Quân đội các bên sẽ ngừng bắn, giữ nguyên vị trí chiếm đóng tại chỗ.', 'Hội nghị hai bên và được quyết định bởi 2 nước: Việt Nam và Hoa Kì.', 'Hai bên thực hiện ngừng bắn, tập kết, chuyển quân, chuyển giao khu vực.', 'Miền Nam Việt Nam có hai chính quyền, hai quân đội, hai vùng kiểm soát.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Miền Nam Việt Nam có hai chính quyền, hai quân đội, hai vùng kiểm soát.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_91', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Trong cuộc chiến tranh phá hoại miền Bắc (1964 - 1972), Mĩ đã đạt được âm mưu nào sau đây?', 'Ngăn chặn được mọi sự chi viện từ nước ngoài vào miền Bắc.', 'Chặn đứng con đường tiếp tế chi viện từ miền Bắc vào miền Nam.', 'Buộc Việt Nam phải kí hiệp định với những điều khoản có lợi cho Mĩ.', 'Phá hoại tiềm lực kinh tế quốc phòng, gây tổn thất lớn về người và của.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Phá hoại tiềm lực kinh tế quốc phòng, gây tổn thất lớn về người và của.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_93', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Hoàn cảnh lịch sử nào tạo nên sự thay đổi căn bản trong so sánh lực lượng có lợi cho cách mạng miền Nam từ đầu năm 1973?', 'Quân đội Sài Gòn không còn tinh thần chiến đấu.', 'Vùng giải phóng của ta được mở rộng và lớn mạnh.', 'Mĩ kí Hiệp định Pa-ri và rút quân đội ra khỏi miền Nam.', 'Mĩ tuyên bố ngừng ném bom đánh phá hoàn toàn miền bắc.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Mĩ kí Hiệp định Pa-ri và rút quân đội ra khỏi miền Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_94', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Sau khi Hiệp định Pa-ri được kí kết (01/1973), Mĩ vẫn “ngoan cố” tiếp tục chiến tranh ở miền Nam Việt Nam vì đã', 'giữ lại cố vấn quân sự.', 'để lại lực lượng quân đội.', 'không thực hiện ngừng bắn.', 'lấn chiếm vùng giải phóng.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: giữ lại cố vấn quân sự.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_95', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Sau Hiệp định Pa-ri 1973 về Việt Nam, so sánh lực lượng ở miền Nam thay đổi có lợi cho cách mạng vì', 'quân Mĩ và đồng minh của Mĩ đã rút khỏi miền Nam Việt Nam.', 'Chính quyền và quân đội Sài Gòn không còn khả năng chiến đấu.', 'miền Nam có hai chính quyền, hai quân đội, hai vùng kiểm soát.', 'miền Nam được hoàn toàn giải phóng đi lên xây dựng CNXH.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: quân Mĩ và đồng minh của Mĩ đã rút khỏi miền Nam Việt Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_97', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Sau thắng lợi Đường 14 - Phước Long (từ 12/12/1974 đến 6/1/1975) của quân dân miền Nam, chính quyền Sài Gòn đã', 'tuyên bố đầu hàng không điều kiện.', 'phản ứng yếu ớt, chủ yếu dùng áp lực từ xa.', 'cầu viện trợ quân sự của Hoa Kì để chiếm lại.', 'phản ứng mạnh và đưa quân đến hòng chiếm lại.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: phản ứng mạnh và đưa quân đến hòng chiếm lại.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_99', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Chiến thắng Đường 14 - Phước Long (6/1/1975) của quân dân miền Nam Việt Nam không chứng tỏ nội dung nào sau đây?', 'Sự suy yếu và bất lực của quân đội sài Gòn.', 'Sự lớn mạnh và khả năng thắng lớn của quân ta.', 'Điều kiện giải phóng miền Nam đã hội tụ đầy đủ.', 'Quân Mỹ khó có khả năng can thiệp quân sự trở lại.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Điều kiện giải phóng miền Nam đã hội tụ đầy đủ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_108', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Cuộc đàm phán về kết thúc chiến tranh ở Việt Nam trên bàn Hội nghị Pa-ri diễn ra căng thẳng, quyết liệt và kéo dài vì', 'quân đội Sài Gòn chưa bị đánh bại hoàn toàn trên chiến trường.', 'hội nghị chưa có sự can thiệp của các quốc gia và tổ chức quốc tế.', 'hội nghị chịu ảnh hưởng của sự đối đầu giữa hai cực, hai phe.', 'bản chất hiếu chiến của Mĩ và lập trường khác biệt của hai bên.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: bản chất hiếu chiến của Mĩ và lập trường khác biệt của hai bên.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_110', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Hiệp định Pa-ri năm 1973 công nhận thực tế miền Nam Việt Nam có hai chính quyền là', 'Việt Nam Cộng hoà và Việt Nam Dân chủ Cộng hòa.', 'Việt Nam Cộng hòa và Cộng hòa miền Nam Việt Nam.', 'Việt Nam Dân chủ Cộng hòa và Chính quyền Sài Gòn.', 'Chính quyền Ngô Đình Diệm và Cộng hòa miền Nam Việt Nam.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Việt Nam Cộng hòa và Cộng hòa miền Nam Việt Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_111', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Bộ Chính trị Trung ương Đảng Lao động Việt Nam quyết định chọn Tây Nguyên làm hướng tiến công chủ yếu trong năm 1975 vì', 'là nơi tập kết hàng chi viện từ miền Bắc và miền Nam.', 'là nơi tập trung nhiều cơ quan chỉ huy của quân Sài Gòn.', 'là địa bàn chiến lược quan trọng, lực lượng của địch mỏng.', 'là căn cứ quân sự liên hợp lớn nhất của Mĩ và quân đội Sài Gòn.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: là địa bàn chiến lược quan trọng, lực lượng của địch mỏng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_113', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Nội dung nào sau đây phản ánh vị thế của Đà Nẵng trong chiến lược của Mỹ ở miền Nam Việt Nam?', 'Là địa bàn chiến lược quan trọng để chống phá miền Bắc.', 'Là thành phố lớn tập trung nhiều cơ quan đầu não của địch.', 'Căn cứ phòng thủ của địch để bảo vệ Sài Gòn từ phía Đông.', 'Căn cứ quân sự liên hợp lớn nhất của Mĩ và quân đội Sài Gòn.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Căn cứ quân sự liên hợp lớn nhất của Mĩ và quân đội Sài Gòn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_114', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Chiến thắng trong chiến dịch Huế - Đà Nẵng năm 1975 của quân dân Việt Nam có ý nghĩa nào sau đây?', 'Ngăn chặn mọi sự can thiệp trở lại bằng quân sự của đế quốc Mĩ.', 'Mở đường cho việc vận tải chi viện quy mô lớn từ miền Bắc vào Nam.', 'Chuyển sang giai đoạn Tổng tiến công chiến lược trên toàn miền Nam.', 'Góp phần đẩy nhanh quá trình giải phóng miền Nam, thống nhất đất nước.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Góp phần đẩy nhanh quá trình giải phóng miền Nam, thống nhất đất nước.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_115', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Sau thất bại chiến dịch Tây Nguyên, Huế - Đà Nẵng, chính quyền Sài Gòn lùi về phòng thủ ở', 'Đường 14 - Phước Long.', 'Phan Rang.', 'Dinh Độc lập.', 'Phan Thiết.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Phan Rang.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_117', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Tháng 3/1975, Bộ Chính trị Trung ương Đảng quyết định mở chiến dịch Hồ Chí Minh nhằm mục đích cơ bản nào sau đây?', 'Tiêu diệt chính quyền Sài Gòn và quân đội Sài Gòn.', 'Chiếm đất, giành dân, mở rộng vùng giải phóng của ta.', 'Thực hiện đầy đủ những quy định của Hiệp định Pa-ri.', 'Đánh bại sự can thiệp của Mĩ vào miền Nam Việt Nam.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Tiêu diệt chính quyền Sài Gòn và quân đội Sài Gòn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_118', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'So với Chiến dịch Điện Biên Phủ năm 1954, chiến dịch Hồ Chí Minh năm 1975 của quân dân Việt Nam diễn ra ở địa bàn nào?', 'Đô thị lớn.', 'Rừng núi.', 'Nông thôn.', 'Trung du.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Đô thị lớn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_121', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Chiến dịch Hồ Chí Minh năm 1975 không có điểm tương đồng với chiến dịch Điện Biên Phủ năm 1954 về', 'lực lượng lãnh đạo.', 'kết quả chiến dịch.', 'mục tiêu tiến công', 'quyết tâm giành thắng lợi.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: mục tiêu tiến công') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_122', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Sự kiện nào sau đây báo hiệu sự toàn thắng của chiến dịch Hồ Chí Minh lịch sử năm 1975 của quân dân miền Nam Việt Nam?', 'Quân ta tiến vào trung tâm Sài Gòn.', 'Xe tăng và bộ binh của ta tiến vào dinh Độc Lập.', 'Lá cờ cách mạng tung bay trên nóc dinh Độc Lập.', 'Dương Văn Minh tuyên bố đầu hàng vô điều kiện.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Lá cờ cách mạng tung bay trên nóc dinh Độc Lập.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_123', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Chiến dịch Hồ Chí Minh có ý nghĩa quyết định đối với thắng lợi của cuộc Tổng tiến công và nổi dậy Xuân năm 1975 vì', 'làm cho chính quyền Sài Gòn đứng trước nguy cơ sụp đổ.', 'đập tan chính quyền Việt Nam Cộng hòa và quân đội Sài Gòn.', 'mở đầu quá trình sụp đổ của chính quyền và quân đội Sài Gòn.', 'đánh bại chiến dịch “Tràn ngập lãnh thổ” của quân đội Sài Gòn.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: đập tan chính quyền Việt Nam Cộng hòa và quân đội Sài Gòn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_126', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Nội dung nào không được ghi nhận trong Hiệp định Pa-ri về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam năm 1973?', 'Nhân dân miền Nam sẽ tự quyết định tương lai chính trị.', 'Hai bên thực hiện ngừng bắn để đi đến việc đàm phán chính thức.', 'Hoa Kì cam kết tôn trọng các quyền dân tộc cơ bản của Việt Nam.', 'Các bên ngừng bắn tại chỗ, trao trả cho nhau tù binh và dân thường.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Hai bên thực hiện ngừng bắn để đi đến việc đàm phán chính thức.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_128', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Một trong những nội dung của Hiệp định Pa-ri về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam năm 1973 là', 'tôn trọng các quyền dân tộc cơ bản của nhân dân ba nước Đông Dương.', 'các bên tham chiến thực hiện tập kết, chuyển quân, chuyển giao khu vực.', 'Việt Nam tiến tới thống nhất bằng cuộc tổng tuyển cử tự do vào năm 1973.', 'Hoa Kì rút hết quân đội, quân đồng minh về nước, hủy hỏ các căn cứ quân sự', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Hoa Kì rút hết quân đội, quân đồng minh về nước, hủy hỏ các căn cứ quân sự') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_129', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Lực lượng chính trị tồn tại ở miền Nam Việt Nam theo quy định của Hiệp định Pa-ri năm 1973 không phải là', 'lực lượng ủng hộ Việt Nam Cộng hòa.', 'lực lượng chư hầu.', 'lực lượng ủng hộ Cộng hòa miền Nam Việt Nam.', 'lực lượng trung gian.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: lực lượng chư hầu.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_131', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Thực chất mối quan hệ giữa hai chính quyền ở miền Nam Việt Nam sau khi Hiệp định Pa-ri (1973) được kí kết là', 'hòa hoãn, đối thoại.', 'hợp tác, thống nhất.', 'hài hòa, thống nhất.', 'đối đầu, căng thẳng.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: đối đầu, căng thẳng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_133', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Hiệp định Pa-ri về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được kí kết đã có tác động nào sau đây?', 'Gây rối loạn trong hàng ngũ kẻ thù, tạo điều kiện thuận lợi cho ta.', 'Mĩ bị suy giảm thế lực nên thi hành chính sách đối ngoài hoà bình.', 'Tạo thời cơ thuận lợi để ta tiến lên giải phóng hoàn toàn miền Nam.', 'Không chấp nhận thất bại, Mỹ can thiệp trở lại miền Nam bằng quân sự.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Tạo thời cơ thuận lợi để ta tiến lên giải phóng hoàn toàn miền Nam.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_134', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Địa bàn tác chiến chính và đầu tiên của quân dân Việt Nam trong cuộc Tổng tiến công và nổi dậy Xuân năm 1975 là', 'Huế - Đà Nẵng.', 'Tây Nguyên.', 'Đông Nam Bộ.', 'Sài Gòn - Gia Định.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Tây Nguyên.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_136', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Trong cuộc Tổng tiến công và nổi dậy Xuân 1975, quân dân Việt Nam đã vận dụng lối đánh nghi binh trong trận đánh vào', 'Huế.', 'Buôn Ma Thuột.', 'Plây-ku.', 'Đà Nẵng.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Buôn Ma Thuột.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_137', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Trong những năm 1974 - 1975, chính quyền Sài Gòn xây dựng tuyến phòng thủ ở Tây Nguyên còn nhiều sơ hở vì', 'Tây Nguyên cách xa miền Bắc, quân ta không thể tấn công tới.', 'nhận định sai hướng tiến công của ta, nên ít chú trọng phòng thủ.', 'Mĩ muốn dùng Tây Nguyên để thu hút quân giải phóng Việt Nam.', 'Tây Nguyên núi rừng không phải là chiến trường sở trường của địch.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: nhận định sai hướng tiến công của ta, nên ít chú trọng phòng thủ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_138', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Tỉnh cuối cùng của miền Nam Việt Nam được giải phóng trong cuộc Tổng tiến công và nổi dậy Xuân 1975 là', 'Hà Tiên.', 'Đồng Nai Thượng.', 'Châu Đốc.', 'Bà Rịa - Vũng Tàu.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Châu Đốc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_139', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Chiến dịch Tây Nguyên (3/1975) của quân dân Việt Nam được mở màn bằng cuộc tấn công vào', 'Plây-ku.', 'Buôn Ma Thuột.', 'Kon Tum.', 'Đắc Lắc.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Buôn Ma Thuột.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_143', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Trận đánh nào mang tính trinh sát chiến lược của quân dân miền Nam trong những năm 1974 - 1975?', 'Chiến dịch Đường 14 - Phước Long.', 'Chiến dịch Tây Nguyên.', 'Chiến dịch Hồ Chí Minh.', 'Chiến dịch Huế - Đà Nẵng.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Chiến dịch Đường 14 - Phước Long.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_144', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Nội dung nào sau đây phản ánh điểm giống nhau giữa Chiến dịch Điên Biên Phủ (1954) và Chiến dịch Hồ Chí Minh (1975)?', 'Cuộc tiến công chủ yếu của lực lượng vũ trang.', 'Đập tan hoàn toàn đầu não và sào huyệt cuối cùng của địch.', 'Cuộc tiến công của lực lượng vũ trang và nổi dậy của quần chúng.', 'Những thắng lợi có ý nghĩa quyết định kết thúc cuộc kháng chiến.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Những thắng lợi có ý nghĩa quyết định kết thúc cuộc kháng chiến.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_145', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Sự kiện nào báo hiệu sự toàn thắng của cuộc Tổng tiến công và nổi dậy Xuân 1975?', 'Xe tăng và bộ binh của ta tiến vào dinh Độc Lập.', 'Lá cờ cách mạng tung bay trên nóc dinh Độc Lập.', 'Dương Văn Minh tuyên bố đầu hàng vô điều kiện.', 'Châu Đốc là tỉnh cuối cùng ở miền Nam được giải phóng.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Châu Đốc là tỉnh cuối cùng ở miền Nam được giải phóng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_148', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Thắng lợi trong cuộc kháng chiến chống Mĩ, cứu nước (1954 - 1975) của nhân dân Việt Nam đã mở ra kỉ nguyên', 'giải phóng dân tộc gắn liền với giải phóng xã hội.', 'giải phóng dân tộc gắn liền với giải phóng giai cấp.', 'đất nước độc lập, thống nhất, đi lên chủ nghĩa xã hội.', 'Nhân dân lao động nắm chính quyền, làm chủ đất nước.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: đất nước độc lập, thống nhất, đi lên chủ nghĩa xã hội.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_149', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Sự kiện nào đã mở ra quá trình “vừa đánh vừa đàm” của cách mạng Việt Nam trong kháng chiến chống Mĩ?', 'Cuộc Tiến công chiến lược năm 1972.', 'Chiến thắng Điện Biên Phủ trên không năm 1972.', 'Cuộc Tổng tiến công và nổi dậy Xuân Mậu Thân 1968.', 'Chiến thắng trong hai mùa khô 1965 - 1966 và 1966 - 1967.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Cuộc Tổng tiến công và nổi dậy Xuân Mậu Thân 1968.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_151', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Mĩ đẩy mạnh chiến tranh phá hoại miền Bắc lần thứ hai năm 1972 nhằm cứu vãn sự thất bại của chiến lược nào?', '“Chiến tranh đặc biệt”.', '“Chiến tranh cục bộ”.', '“Việt Nam hóa chiến tranh”.', '“Đông Dương hóa chiến tranh”.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: “Việt Nam hóa chiến tranh”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_153', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Chiến dịch Hồ Chí Minh (1975) với Chiến dịch Điện Biên Phủ (1954) có điểm khác biệt cơ bản về', 'sự huy động cao nhất lực lượng.', 'kết quả của chiến dịch.', 'phương châm tác chiến.', 'quyết tâm giành thắng lợi.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: phương châm tác chiến.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_156', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Từ năm 1954 đến năm 1975, những chiến lược chiến tranh Mĩ thực hiện ở miền Nam Việt Nam có điểm tương đồng về', 'âm mưu chiến lược.', 'thủ đoạn của chiến tranh.', 'quy mô của chiến lược.', 'lực lượng tham chiến chính.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: âm mưu chiến lược.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_159', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Quyết định để nhân dân miền Nam sử dụng bạo lực cách mạng đánh đổ chính quyền Mĩ - Diệm là nội dung quan trọng của', 'Đại hội đại biểu của Đảng Lao động Việt Nam lần thứ III (9/1960).', 'Hội nghị lần thứ 21 Ban Chấp hành Trung ương Đảng (7/1973).', 'Hội nghị lần thứ 15 Ban Chấp hành Trung ương Đảng (1/1959).', 'Hội nghị lần thứ 24 Ban Chấp hành Trung ương Đảng (9/1975).', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Hội nghị lần thứ 15 Ban Chấp hành Trung ương Đảng (1/1959).') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_160', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Trong những năm 1965 - 1975, Mĩ phải chấm dứt tất cả các hành động chống phá miền Bắc Việt Nam sau sự kiện nào?', 'Sau thắng lợi của chiến dịch Hồ Chí Minh.', 'Sau thắng lợi của trận “Điện Biên Phủ trên không”.', 'Sau khi Hiệp định Pa-ri về Việt Nam được kí kết.', 'Sau cuộc Tổng tiến công và nổi dậy Xuân 1975.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Sau khi Hiệp định Pa-ri về Việt Nam được kí kết.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_164', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Nhân dân miền Bắc đạt được thành tự nào trong hơn 20 năm xây dựng CNXH (1954 - 1975)?', 'Đưa Việt Nam trở thành nước nông nghiệp trong phe xã hội chủ nghĩa.', 'Bước đầu xây dựng được cơ sở vật chất - kĩ thuật của chủ nghĩa xã hội.', 'Đưa miền Bắc tiến nhanh, tiến mạnh, tiến vững chắc lên chủ nghĩa xã hội.', 'Đạt được thành tựu vượt bậc, trở thành một nước xã hội chủ nghĩa điển hình.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Bước đầu xây dựng được cơ sở vật chất - kĩ thuật của chủ nghĩa xã hội.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_165', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Trong những năm 1974 - 1975, chiến dịch nào của quân dân Việt Nam thể hiện kế sách “điều địch để đánh địch”?', 'Chiến dịch đường 14 - Phước Long.', 'Chiến dịch Tây Nguyên.', 'Chiến dịch Huế - Đà Nẵng.', 'Chiến dịch Sài Gòn - Gia Định.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Chiến dịch Tây Nguyên.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_167', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Cuộc kháng chiến chống Mĩ của nhân dân Việt Nam (1954 - 1975) kết thúc thắng lợi hoàn toàn bằng giải pháp nào?', 'Ngoại giao.', 'Quân sự.', 'Kinh tế.', 'Chính trị.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Quân sự.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_169', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Phương thức “xã giải phóng xã, huyện giải phóng huyện, tỉnh giải phóng tỉnh” được nhân dân miền Nam sử dụng trong', 'phong trào “Đồng khởi” ở Nam Bộ và Tây Nguyên.', 'chiến dịch Tây Nguyên và chiến dịch Huế - Đà Nẵng.', 'cuộc Tổng tiến công và nổi dậy Xuân Mậu Thân năm 1968.', 'giải phóng các tỉnh còn lại ở miền Nam sau khi giải phóng Sài Gòn.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: chiến dịch Tây Nguyên và chiến dịch Huế - Đà Nẵng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_171', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Mĩ thực hiện chủ trương “phi Mĩ hóa” chiến tranh xâm lược Việt Nam trong chiến lược nào?', '“Chiến tranh đơn phương”.', '“Chiến tranh đặc biệt”.', '“Việt Nam hóa chiến tranh”.', '“Chiến tranh cục bộ”.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: “Việt Nam hóa chiến tranh”.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_172', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Năm 1965, Mĩ ồ ạt đưa quân viễn chinh, quân đồng minh vào chiến trường miền Nam Việt Nam vì', 'muốn nhanh chóng kết thúc chiến tranh ở Việt Nam.', 'quân đội Sài Gòn không có khả năng tự đứng vững.', 'muốn tiến hành cuộc đảo chính lật đổ Ngô Đình Diệm.', 'muốn đẩy mạnh chiến tranh ra cả ba nước Đông Dương.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: quân đội Sài Gòn không có khả năng tự đứng vững.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_173', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Chiến dịch Điện Biên Phủ năm 1954 và Chiến dịch Hồ Chí Minh năm 1975 có điểm tương đồng nào sau đây?', 'Sử dụng lối đánh du kích là chủ yếu.', 'Là trận quyết chiến chiến lược với kẻ thù.', 'Có sự điều chỉnh về phương châm tác chiến.', 'Có sự kết hợp chiến trường Lào và Campuchia.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Là trận quyết chiến chiến lược với kẻ thù.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_174', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Mĩ tiến hành chiến tranh xâm lược Việt Nam (1954 - 1975) nhằm thực hiện mục tiêu nào trong chiến lược toàn cầu?', 'Khống chế và nô dịch các nước đồng minh.', 'Can thiệp vào công việc nội bộ của các nước.', 'Ngăn chặn tiến tới tiêu diệt chủ nghĩa xã hội.', 'Đảo bảo an ninh Mĩ với lực lượng quân sự mạnh.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Ngăn chặn tiến tới tiêu diệt chủ nghĩa xã hội.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_175', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Việc ký với Hoa Kỳ Hiệp định Pari năm 1973, Việt Nam', 'chưa hoàn thành cách mạng dân tộc dân chủ nhân dân.', 'chỉ phải đối phó với một kẻ thù là chính quyền Sài Gòn.', 'đánh bại hoàn toàn các chiến lược chiến tranh của Mỹ.', 'hoàn thành kế hoạch thống nhất đất nước về lãnh thổ.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: chỉ phải đối phó với một kẻ thù là chính quyền Sài Gòn.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_176', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Chủ trương của Đảng trong Tổng tiến công và nổi dậy Xuân năm 1975 đã', 'có sự điều chỉnh linh hoạt về thời gian giải phóng.', 'có sự thay đổi liên tục về phương châm tác chiến.', 'chuyển hướng tiến công từ đô thị về nông thôn.', 'chuyển hướng từ tổng tiến công sang nổi dậy.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: có sự điều chỉnh linh hoạt về thời gian giải phóng.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_177', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Cuộc chiến tranh phá hoại miền Bắc của đế quốc Mỹ (1965 - 1972) đã', 'tiêu diệt toàn bộ lực lượng phòng không không quân miền Bắc.', 'ngăn chặn được những cuộc tấn công của quân giải phóng miền Nam.', 'làm cho miền Bắc bị chậm tiến lên sản xuất lớn lại vài ba kế hoạch.', 'làm cho đường Trường Sơn trên bộ và trên biển không còn tồn tại.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: làm cho miền Bắc bị chậm tiến lên sản xuất lớn lại vài ba kế hoạch.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_178', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Với cuộc Tổng tiến công và nổi dậy Xuân năm 1975, chính quyền Sài Gòn bị lật đổ nhưng chưa xóa bỏ hoàn toàn được', 'cơ sở kinh tế mà chính quyền Sài Gòn đã xây dựng ở miền Nam.', 'cơ sở của chính quyền Sài Gòn ở địa phương cùng những di hại của xã hội cũ.', 'cơ sở hạ tầng kĩ thuật ở miền Nam mà chính quyền Sài Gòn đã xây dựng.', 'chính quyền Sài Gòn và cơ cấu tổ chức nhà nước Việt Nam Cộng hòa.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: cơ sở của chính quyền Sài Gòn ở địa phương cùng những di hại của xã hội cũ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B17_P_179', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B17'), 'LS9_KNTT_B17', 'Cuộc kháng chiến chống Mỹ cứu nước (1954 - 1975) của nhân dân Việt Nam là cuộc tiến công toàn diện của quần chúng vào', 'quân viễn chinh xâm lược nhà nghề của kẻ thù.', 'những thế lực nội phản làm tay sai cho đế quốc Mỹ.', 'những căn cứ quân sự của chúng lập ra ở hai miền.', 'đội quân xâm lược và những công cụ do chúng lập ra.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: những thế lực nội phản làm tay sai cho đế quốc Mỹ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
