INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B18_P_42', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B18'), 'LS9_KNTT_B18', 'Nhận xét nào sau đây phản ánh đúng về sự hình thành trật tự thế giới sau Chiến tranh lạnh?', 'Chịu tác động của nhiều nhân tố nên diễn ra phức tạp, chậm chạp.', 'Hình thành thông qua các hội nghị với các hiệp định được ký kết.', 'Được hình thành sau những xung đột quân sự giữa hai khối đối lập.', 'Các quốc gia có sự cân bằng về quyền lực tham gia xây dựng trật tự.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Chịu tác động của nhiều nhân tố nên diễn ra phức tạp, chậm chạp.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B18_P_43', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B18'), 'LS9_KNTT_B18', 'Sau Chiến tranh lạnh, tương quan lực lượng giữa các cường quốc trên thế giới có tác động nào đến quan hệ quốc tế?', 'Đẩy nhanh quá trình thiết lập trật tự thế giới mới do Mỹ thống trị.', 'Góp phần tạo nên xu thế hoà bình, ổn định và phát triển trên thế giới.', 'Ngăn chặn được những “di chứng” của Chiến tranh lạnh trên thế giới.', 'Góp phần hình thành trật tự thế giới theo xu thế đa cực, nhiều trung tâm.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: Góp phần hình thành trật tự thế giới theo xu thế đa cực, nhiều trung tâm.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B18_P_44', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B18'), 'LS9_KNTT_B18', 'Nhận xét nào sau đây phản ánh đúng về quan hệ quốc tế trong đầu thế kỷ XXI?', 'Các quốc gia có quan hệ phức tạp, đan xen và phụ thuộc lẫn nhau.', 'Nhiều biến động nhưng vẫn giữ được hòa bình tuyệt đối để phát triển.', 'Những xung đột tôn giáo và sắc tộc không còn trong các liên minh kinh tế.', 'Mâu thuẫn lợi ích được hóa giải khi các nước gia nhập các tổ chức quốc tế.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Các quốc gia có quan hệ phức tạp, đan xen và phụ thuộc lẫn nhau.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B18_P_46', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B18'), 'LS9_KNTT_B18', 'Trong trật tự thế giới đa cực, sự gia tăng vai trò của các trung tâm, các tổ chức quốc tế phản ánh nội dung nào sau đây?', 'So sánh lực lượng mới trong quan hệ quốc tế.', 'Nền kinh tế thế giới đã đạt được công bằng mới.', 'Quy luật phát triển đồng đều của lịch sử thế giới.', 'Trình độ phát triển của các nước không còn chênh lệch.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: So sánh lực lượng mới trong quan hệ quốc tế.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
