INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_53', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Tiền đề thúc đẩy sự bùng nổ của cuộc cách mạng khoa học - công nghệ ở nửa sau thế kỷ XX là', 'sự vươn lên mạnh mẽ của nền kinh tế Mỹ, Tây Âu, Nhật Bản.', 'những thắng lợi của phong trào giải phóng dân tộc trên thế giới.', 'những hậu quả nặng nề của cuộc Chiến tranh thế giới lần hai.', 'những thành tựu về khoa học - kỹ thuật cuối thế kỷ XIX đầu thế kỷ XX.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: những thành tựu về khoa học - kỹ thuật cuối thế kỷ XIX đầu thế kỷ XX.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_54', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Một trong những đặc điểm của cuộc cách mạng khoa học - công nghệ nửa sau thế kỷ XX là', 'diễn ra với quy mô lớn, tốc độ nhanh, đạt được nhiều thành tựu kỳ diệu.', 'khoa học và kỹ thuật tồn tại độc lập, khoa học mở đường cho sản xuất.', 'thời gian từ phát minh khoa học đến ứng dụng vào sản xuất kéo dài.', 'kỹ thuật trở thành nguồn gốc chính của những tiến bộ về khoa học.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: diễn ra với quy mô lớn, tốc độ nhanh, đạt được nhiều thành tựu kỳ diệu.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_55', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Xu thế toàn cầu hoá nửa cuối thế kỷ XX, đầu thế kỷ XXI đã', 'giải quyết triệt để tình trạng thiếu nguồn năng lượng.', 'làm cho đời sống của con người trở nên an toàn hơn.', 'đảm bảo cân bằng tăng trưởng kinh tế với công bằng xã hội.', 'làm tăng tính phụ thuộc lẫn nhau giữa các quốc gia, dân tộc.', 4, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là D: làm tăng tính phụ thuộc lẫn nhau giữa các quốc gia, dân tộc.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_57', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Trong xu thế phát triển của thế giới thế kỷ XXI, Việt Nam sẽ đứng trước nguy cơ tụt hậu, nếu', 'không tiến hành phát minh, cải tiến khoa học- kĩ thuật.', 'bỏ lỡ cơ hội, không hoà nhập vào nền kinh tế thế giới.', 'không phát triển nền văn hóa đậm đà bản sắc dân tộc.', 'tự tin vào chính mình, phát triển nền kinh tế nông nghiệp.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: bỏ lỡ cơ hội, không hoà nhập vào nền kinh tế thế giới.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_58', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Sau Chiến tranh thế giới thứ hai, cuộc cách mạng khoa học - kĩ thuật có ý nghĩa tích cực là', 'giảm bớt tình trạng tai nạn lao động và giao thông.', 'nâng cao đời sống vật chất và tinh thần của con người.', 'hạn chế các vũ khí hủy diệt và phương tiện chiến tranh.', 'tình trạng ô nhiễm môi trường sẽ được giải quyết triệt để.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: nâng cao đời sống vật chất và tinh thần của con người.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
