INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_63', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Nội dung nào không phải là tác động tiêu cực của cuộc cách mạng khoa học - kĩ thuật nửa sau thế kỉ XX?', 'Chế tạo vũ khí và phương tiện chiến tranh mạng tính hủy diệt.', 'Bùng nổ dân số và cạn kiệt những nguồn tài nguyên thiên nhiên.', 'Ô nhiễm môi trường, nhiễm phóng xạ nguyên tử, tai nạn lao động', 'Dịch bệnh mới, những mối đe dọa về đạo đức, xã hội, an ninh.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Bùng nổ dân số và cạn kiệt những nguồn tài nguyên thiên nhiên.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_64', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Trong cuộc cách mạng khoa học - kĩ thuật lần thứ hai, mọi phát minh kĩ thuật đều bắt nguồn từ', 'nghiên cứu khoa học.', 'nải tiến kĩ thuật.', 'nhu cầu chiến tranh.', 'từ thực tiễn đời sống.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: nghiên cứu khoa học.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
