INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_67', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Nhân tố nào có ý nghĩa quyết định để tăng trưởng kinh tế và nâng cao không ngừng mức sống của con người trong thế kỉ XX?', 'Tìm ra sự sống ở những hành tinh mới.', 'Cuộc cách mạng khoa học - kĩ thuật.', 'Sự phát triển của chủ nghĩa tư bản.', 'Sự chấm dứt cuộc Chiến tranh lạnh.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Cuộc cách mạng khoa học - kĩ thuật.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_71', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Một trong những thành tựu tiêu biểu của cuộc cách mạng khoa học - kỹ thuật hiện đại trên lĩnh vực vật lý là', 'công nghệ vi sinh', 'dữ liệu lớn', 'vật liệu mới', 'công nghệ tế bào', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: vật liệu mới') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_72', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Một trong những ý nghĩa của các cuộc cách mạng khoa học - kỹ thuật thời kì hiện đại với kinh tế là', 'mở rộng và đa dạng hóa các hình thức sản xuất.', 'thúc đẩy sự phân hóa trong lực lượng lao động', 'làm tăng sự lệ thuộc của con người vào công nghệ.', 'thúc đẩy sự giao lưu, kết nối văn hoá toàn cầu.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: mở rộng và đa dạng hóa các hình thức sản xuất.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_74', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Nội dung nào sau đây không phản ánh đúng ý nghĩa của các cuộc cách mạng khoa học - kỹ thuật thời kì hiện đại?', 'Hình thành hai giai cấp cơ bản trong xã hội tư bản là tư sản và vô sản.', 'Tạo ra các ngành sản xuất tự động, năng suất lao động được tăng cao', 'Thúc đẩy quá trình toàn cầu hóa và khu vực hóa nền kinh tế thế giới', 'Thúc đẩy giao lưu văn hóa giữa các quốc gia và khu vực trên thế giới', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Hình thành hai giai cấp cơ bản trong xã hội tư bản là tư sản và vô sản.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_75', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Nội dung nào sau đây phản ánh đúng ý nghĩa của các cuộc cách mạng khoa học - kỹ thuật thời kì hiện đại về mặt xã hội?', 'Dẫn đến sự phân hóa trong lực lượng lao động.', 'Thúc đẩy giao lưu và kết nối văn hoá toàn cầu.', 'Thúc đẩy sự phát triển của thương mại điện tử.', 'Làm xuất hiện nhiều ngành công nghiệp mới.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: Dẫn đến sự phân hóa trong lực lượng lao động.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_77', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Các cuộc cách mạng khoa học - kỹ thuật hiện đại đã làm cho', 'mâu thuẫn giữa giai cấp vô sản và tư sản sâu sắc hơn', 'số lượng công nhân lao động phổ thông giảm dần', 'lao động tay chân thay thế hoàn toàn bằng máy móc', 'số lượng công nhân có tri thức, kĩ năng giảm dần', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: số lượng công nhân lao động phổ thông giảm dần') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_78', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Tự động hóa và công nghệ rôbốt ra đời trong các cuộc cách mạng khoa học - kỹ thuật hiện đại đã', 'gây ra tình trạng ô nhiểm môi trường.', 'thúc đẩy sự giao lưu văn hóa toàn cầu.', 'tạo nguy cơ người lao động bị mất việc làm.', 'gây ra sự phân hóa giàu nghèo trong xã hội.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: tạo nguy cơ người lao động bị mất việc làm.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_79', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Những thay đổi căn bản về cơ cấu sản xuất của nhân loại trong thế kỷ XX bắt nguồn từ', 'Chiến tranh thế giới thứ hai.', 'Chiến tranh lạnh do Mỹ phát động.', 'cách mạng khoa học - công nghệ.', 'khủng hoảng năng lượng năm 1973.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: cách mạng khoa học - công nghệ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_80', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Trước sự phát triển như vũ bão của cách mạng khoa học - công nghệ nửa sau thế kỷ XX, các quốc gia cần phải', 'loại bỏ hoàn toàn những ngành thủ công truyền thống.', 'tăng cường tính chủ động, không phụ thuộc vào công nghệ.', 'chống lại xu thế toàn cầu hoá và sự “hoà tan” về văn hoá.', 'sử dụng các thành tựu đó vào mục đích hoà bình, nhân đạo.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: tăng cường tính chủ động, không phụ thuộc vào công nghệ.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_82', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Sự phát triển nhanh chóng của cuộc cách mạng khoa học - kỹ thuật hiện đại dẫn đến hiện tượng nổi bật nào sau đây?', 'Rò rỉ hạt nhân.', 'Chảy máu tài nguyên.', 'Sự bùng nổ thông tin.', 'Chảy máu chất xám.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Sự bùng nổ thông tin.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_83', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Hiện nay, thương mại quốc tế gia tăng mạnh mẽ là sự phản ánh', 'sự phát triển và tác động to lớn của các công ty xuyên quốc gia.', 'thu nhập quốc dân của tất cả các nước trên thế giới đều tăng nhanh.', 'nền kinh tế các nước trên thế giới quan hệ chặt chẽ, phụ thuộc lẫn nhau.', 'các công ty xuyên quốc gia đẩy mạnh hoạt động ở các nước phát triển.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: nền kinh tế các nước trên thế giới quan hệ chặt chẽ, phụ thuộc lẫn nhau.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_84', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Cuộc cách mạng khoa học - kỹ thuật hiện đại đã gây ra hậu quả tiêu cực nào?', 'Ô nhiễm môi trường được cải thiện.', 'Làm quan hệ các nước lớn căng thẳng.', 'Nguy cơ mất an ninh của các quốc gia.', 'Thu hẹp chênh lệch giữa các quốc gia.', 3, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là C: Nguy cơ mất an ninh của các quốc gia.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_85', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Nội dung nào sau đây phản ánh không đúng những tác động của xu thế toàn cầu hoá đối với thế giới?', 'Thúc đẩy nhanh sự hình thành thị trường kinh tế toàn cầu.', 'Tác động tới sự hình thành chủ nghĩa khủng bố trên thế giới.', 'Làm gia tăng giao lưu, trao đổi văn hoá giữa các quốc gia, dân tộc.', 'Đem lại sự tăng trưởng cao về kinh tế, xã hội hoá lực lượng sản xuất.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Tác động tới sự hình thành chủ nghĩa khủng bố trên thế giới.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_86', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Nội dung nào sau đây phản ánh không đúng những tác động của toàn cầu hoá đối với Việt Nam trong thế kỷ XXI?', 'Mở rộng hoạt động thương mại, xuất khẩu lao động.', 'Thúc đẩy Việt Nam đề ra đường lối đổi mới đất nước.', 'Góp phần nâng cao uy tín, địa vị quốc gia trên thế giới.', 'Tạo điều kiện cho quá trình hội nhập khu vực và thế giới.', 2, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là B: Thúc đẩy Việt Nam đề ra đường lối đổi mới đất nước.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_87', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Xét về mặt kinh tế, toàn cầu hoá tạo điều kiện cho Việt Nam', 'tiếp cận vốn đầu tư nước ngoài.', 'giảm chênh lệch về giàu nghèo.', 'thu hẹp hoạt động thương mại.', 'định hình nền văn hoá toàn cầu.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: tiếp cận vốn đầu tư nước ngoài.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
