INSERT INTO lesson_question (id, lesson_id, lesson_code, question_text, option_1, option_2, option_3, option_4, correct_answer, time_limit, stage_tag, difficulty, explanation) VALUES ('Q_LS9_B21_P_89', (SELECT id FROM lesson_metadata WHERE code = 'LS9_KNTT_B21'), 'LS9_KNTT_B21', 'Trên lĩnh vực văn hoá, toàn cầu hoá trong thế kỷ XXI cho phép Việt Nam', 'tiếp thu tinh hoa văn hoá của nhân loại.', 'làm xói mòn bản sắc văn hoá truyền thống.', 'xây dựng những chuẩn mực văn hoá thế giới.', 'kiểm soát được những trào lưu văn hoá mới.', 1, 30, 'PRACTICE', 'HARD', 'Đáp án đúng là A: tiếp thu tinh hoa văn hoá của nhân loại.') ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, lesson_code = EXCLUDED.lesson_code, question_text = EXCLUDED.question_text, option_1 = EXCLUDED.option_1, option_2 = EXCLUDED.option_2, option_3 = EXCLUDED.option_3, option_4 = EXCLUDED.option_4, correct_answer = EXCLUDED.correct_answer, time_limit = EXCLUDED.time_limit, stage_tag = EXCLUDED.stage_tag, difficulty = EXCLUDED.difficulty, explanation = EXCLUDED.explanation;
